function shouldRefreshForEvent(event: IDEEvent): boolean {
  return event.type.startsWith('execution:')
    || event.type.startsWith('ai:')
    || event.type.startsWith('frontier:')
    || event.type === 'workspace:changed'
    || event.type === 'provider:updated'
    || event.type === 'toolchain:updated'
    || event.type.startsWith('blackboard:')
    || event.type.startsWith('agent:')
    || event.type.startsWith('harness:')
    || event.type.startsWith('planner:')
    || event.type.startsWith('orchestrator:');
}

function shouldRefreshFrontierQueueForEvent(event: IDEEvent): boolean {
  return event.type.startsWith('frontier:')
    || event.type.startsWith('blackboard:')
    || event.type.startsWith('agent:')
    || event.type.startsWith('planner:')
    || event.type.startsWith('orchestrator:')
    || event.type === 'harness:case-run'
    || event.type === 'ai:action-completed';
}

function mergeDesktopBackendStatus(current: DesktopStatus | null, next: DesktopStatus): DesktopStatus {
  return {
    ...next,
    recentWorkspaces: next.recentWorkspaces && next.recentWorkspaces.length > 0
      ? next.recentWorkspaces
      : current?.recentWorkspaces ?? [],
    runtime: next.runtime && Object.keys(next.runtime).length > 0
      ? next.runtime
      : current?.runtime,
  };
}

