  function syncAIConversationFromIDEData(next: IDEData) {
    if (!next.aiConversation) {
      return;
    }
    setAIConversation(next.aiConversation);
    setAIStatus(aiConversationLoadedStatus(next.aiConversation));
  }

  async function refreshAIConversationSessions(statusPrefix = '') {
    if (statusPrefix) {
      setAISessionStatus(statusPrefix);
    }
    try {
      const sessions = await fetchAIConversationSessions();
      setAISessions(sessions);
      if (statusPrefix) {
        setAISessionStatus(`${zhCN.ai.sessionRefresh}: ${sessions.length} ${zhCN.ai.sessionsCount}`);
      }
      return sessions;
    } catch (error) {
      if (statusPrefix) {
        setAISessionStatus(`${zhCN.ai.sessionLoadFailed}: ${formatErrorMessage(error)}`);
      }
      return [];
    }
  }

  useEffect(() => {
    function handleShortcut(event: KeyboardEvent) {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') {
        event.preventDefault();
        void openCommandPalette();
      }
      if (event.key === 'Escape') {
        setPaletteOpen(false);
      }
    }
    window.addEventListener('keydown', handleShortcut);
    return () => window.removeEventListener('keydown', handleShortcut);
  }, []);

  async function openCommandPalette() {
    try {
      const status = await loadDesktopStatus();
      setDesktopStatus(current => mergeDesktopBackendStatus(current, status));
    } finally {
      setPaletteOpen(true);
    }
  }

