  function storeBlackboardQueryResult(query: BlackboardQuery, blackboard: BlackboardState) {
    if (!hasActiveBlackboardQuery(query)) {
      setBlackboardView(null);
      setIDEData(current => ({ ...current, blackboard }));
      return;
    }
    setBlackboardView(blackboard);
  }

  async function refreshBlackboardQueryResult(query: BlackboardQuery): Promise<BlackboardState> {
    const normalizedQuery = normalizeBlackboardQuery(query);
    const blackboard = await queryBlackboardItems(normalizedQuery);
    storeBlackboardQueryResult(normalizedQuery, blackboard);
    return blackboard;
  }

  async function queryBlackboard(query: BlackboardQuery): Promise<BlackboardState | null> {
    const normalizedQuery = normalizeBlackboardQuery(query);
    setBlackboardFilterBusy(true);
    setBlackboardUpdateStatus(zhCN.blackboard.filtering);
    try {
      const blackboard = await refreshBlackboardQueryResult(normalizedQuery);
      setBlackboardUpdateStatus(`${zhCN.blackboard.filterApplied}: ${blackboard.items.length} ${zhCN.blackboard.itemCount}`);
      return blackboard;
    } catch (error) {
      setBlackboardUpdateStatus(`${zhCN.blackboard.filterFailed}: ${formatErrorMessage(error)}`);
      return null;
    } finally {
      setBlackboardFilterBusy(false);
    }
  }

  async function batchUpdateBlackboardSelection(request: BlackboardBatchUpdateRequest, query: BlackboardQuery): Promise<BlackboardBatchUpdateResult | null> {
    const entries = Object.entries(request.update).filter(([, value]) => value !== undefined && value !== '');
    if (request.ids.length === 0) {
      setBlackboardUpdateStatus(zhCN.blackboard.selectionRequired);
      return null;
    }
    if (entries.length === 0) {
      setBlackboardUpdateStatus(zhCN.blackboard.batchUpdateRequired);
      return null;
    }
    const [field, value] = entries[0];
    const normalizedField: BlackboardBatchField = field === 'priority' ? 'priority' : 'status';
    const nextValue = String(value);
    const label = normalizedField === 'priority' ? blackboardPriorityLabel(nextValue) : blackboardStatusLabel(nextValue);
    setBlackboardBatchBusy({ ids: request.ids, field: normalizedField, value: nextValue });
    setBlackboardUpdateStatus(`${zhCN.blackboard.batchUpdating}: ${request.ids.length} ${zhCN.blackboard.itemCount} · ${label}`);
    try {
      const result = await batchUpdateBlackboardItems(request);
      await refreshBlackboardQueryResult(query);
      setBlackboardUpdateStatus(`${zhCN.blackboard.batchUpdated}: ${result.count} ${zhCN.blackboard.itemCount}`);
      return result;
    } catch (error) {
      setBlackboardUpdateStatus(`${zhCN.blackboard.batchUpdateFailed}: ${formatErrorMessage(error)}`);
      return null;
    } finally {
      setBlackboardBatchBusy(null);
    }
  }

  async function linkBlackboardDependencies(ids: string[], request: BlackboardDependencyLinkRequest, query: BlackboardQuery): Promise<boolean> {
    if (ids.length === 0) {
      setBlackboardUpdateStatus(zhCN.blackboard.selectionRequired);
      return false;
    }
    if (request.dependencyIds.length === 0) {
      setBlackboardUpdateStatus(zhCN.blackboard.dependencyIdsRequired);
      return false;
    }
    setBlackboardDependencyBusy({ id: ids.join(',') });
    setBlackboardUpdateStatus(`${zhCN.blackboard.dependencyLinking}: ${ids.length} ${zhCN.blackboard.itemCount}`);
    try {
      await Promise.all(ids.map(id => linkBlackboardItemDependencies(id, request)));
      await refreshBlackboardQueryResult(query);
      setBlackboardUpdateStatus(`${zhCN.blackboard.dependencyLinked}: ${ids.length} ${zhCN.blackboard.itemCount}`);
      return true;
    } catch (error) {
      setBlackboardUpdateStatus(`${zhCN.blackboard.dependencyLinkFailed}: ${formatErrorMessage(error)}`);
      return false;
    } finally {
      setBlackboardDependencyBusy(null);
    }
  }

  async function updateAgentTaskLifecycle(task: AgentTask, status: AgentTaskLifecycleStatus) {
    const request: AgentTaskUpdateRequest = { id: task.id, status };
    const label = agentTaskLifecycleLabel(status);
    setAgentTaskLifecycleBusy({ id: task.id, status });
    setAgentTaskLifecycleStatus(`${zhCN.ai.agentTaskLifecycleUpdating}: ${task.title} · ${label}`);
    try {
      const updatedTask = await updateAgentTask(task.id, request);
      setAgentTaskLifecycleStatus(`${zhCN.ai.agentTaskLifecycleUpdated}: ${updatedTask.title} · ${agentStatusLabel(updatedTask.status)}`);
      await refresh();
    } catch (error) {
      setAgentTaskLifecycleStatus(`${zhCN.ai.agentTaskLifecycleFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAgentTaskLifecycleBusy(null);
    }
  }

  async function updateBlackboardItemFields(item: BlackboardItem, request: BlackboardItemUpdateRequest) {
    const entries = Object.entries(request).filter(([, value]) => value !== undefined && value !== '');
    if (entries.length === 0) {
      return;
    }
    const [field, value] = entries[0];
    const nextValue = String(value);
    const label = field === 'priority' ? blackboardPriorityLabel(nextValue) : blackboardStatusLabel(nextValue);
    setBlackboardUpdateBusy({ id: item.id, field: field === 'priority' ? 'priority' : 'status', value: nextValue });
    setBlackboardUpdateStatus(`${zhCN.blackboard.updateUpdating}: ${item.title} · ${label}`);
    try {
      const updatedItem = await updateBlackboardItem(item.id, request);
      setAICollaborationLastBlackboard(current => current?.id === updatedItem.id ? updatedItem : current);
      setBlackboardUpdateStatus(`${zhCN.blackboard.updateUpdated}: ${updatedItem.title} · ${blackboardStatusLabel(updatedItem.status)} · ${blackboardPriorityLabel(updatedItem.priority)}`);
      await refreshBlackboardQueryResult(blackboardFilterDraft);
      void refreshFrontierQueue(frontierQueueQuery);
      void refreshFrontierDependencies(frontierQueueQuery);
    } catch (error) {
      setBlackboardUpdateStatus(`${zhCN.blackboard.updateFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setBlackboardUpdateBusy(null);
    }
  }

  async function createAgentTaskEventRecord(task: AgentTask, action: AgentTaskEventAction, input: AgentTaskEventSubmitInput) {
    const agentId = input.agentId.trim();
    const summary = input.summary.trim();
    const detail = input.detail.trim();
    const artifactPath = input.artifactPath.trim();
    const executionId = input.executionId.trim();
    if (!summary) {
      setAgentTaskEventStatus(zhCN.agents.eventSummaryRequired);
      return;
    }
    if (action === 'claim' && !agentId) {
      setAgentTaskEventStatus(zhCN.agents.eventAgentIdRequired);
      return;
    }
    const request: AgentTaskEventCreateRequest = {
      kind: action,
      status: action === 'claim' ? 'in_progress' : undefined,
      agentId: agentId || undefined,
      title: action === 'claim' ? zhCN.agents.eventClaimTitle : zhCN.agents.eventLogTitle,
      summary,
      detail: detail || undefined,
      source: zhCN.agents.eventSourceWorkbench,
      filePath: task.filePath,
      artifactPath: artifactPath || undefined,
      executionId: executionId || undefined,
      replayEventId: task.replayEventId,
      reportFindingId: task.reportFindingId,
    };
    setAgentTaskEventBusy({ id: task.id, action });
    setAgentTaskEventStatus(`${zhCN.agents.eventRecording}: ${task.title} · ${agentTaskEventActionLabel(action)}`);
    try {
      const event = await createAgentTaskEvent(task.id, request);
      setAgentTaskEventStatus(`${zhCN.agents.eventRecorded}: ${event.title || event.summary || event.id}`);
      await refresh();
    } catch (error) {
      setAgentTaskEventStatus(`${zhCN.agents.eventCreateFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAgentTaskEventBusy(null);
    }
  }

  async function runAgentTaskProvider(task: AgentTask, request: AgentProviderRunRequest) {
    setAgentProviderRunBusyTaskIds(current => current.includes(task.id) ? current : [...current, task.id]);
    setAgentProviderRunErrors(current => {
      const next = { ...current };
      delete next[task.id];
      return next;
    });
    let completedRun: AgentProviderRun | null = null;
    try {
      const run = await runAgentTaskWithProvider(task.id, {
        providerName: request.providerName,
        model: request.model,
        maxTokens: request.maxTokens,
        source: request.source,
      });
      completedRun = run;
      setAgentProviderRuns(current => ({ ...current, [task.id]: run }));
    } catch (error) {
      setAgentProviderRunErrors(current => ({
        ...current,
        [task.id]: `${zhCN.agents.providerRunFailed}: ${formatErrorMessage(error)}`,
      }));
    } finally {
      setAgentProviderRunBusyTaskIds(current => current.filter(id => id !== task.id));
    }

    if (!completedRun) {
      return;
    }
    try {
      await refresh();
    } catch (error) {
      setAgentProviderRunErrors(current => ({
        ...current,
        [task.id]: `${zhCN.agents.providerRunRefreshFailed}: ${formatErrorMessage(error)}`,
      }));
    }
  }

  async function runAgentTaskProviderBatch(request: AgentProviderBatchRunRequest) {
    setAgentProviderBatchRunBusy(true);
    setAgentProviderBatchRunError('');
    setAgentProviderBatchRun(null);
    try {
      const batchRun = await runAgentTasksWithProviderBatch(request);
      const batchRunsByTask = batchRun.runs.flatMap((run, index) => {
        const taskId = run.task?.id?.trim() || batchRun.taskIds[index]?.trim();
        return taskId ? [{ run, taskId }] : [];
      });
      const batchTaskIds = new Set(batchRunsByTask.map(item => item.taskId));
      setAgentProviderBatchRun(batchRun);
      setAgentProviderRuns(current => {
        const next = { ...current };
        for (const { run, taskId } of batchRunsByTask) {
          next[taskId] = run;
        }
        return next;
      });
      setAgentProviderRunErrors(current => {
        const next = { ...current };
        for (const taskId of batchTaskIds) {
          delete next[taskId];
        }
        return next;
      });
      try {
        await refresh();
      } catch (error) {
        setAgentProviderBatchRunError(`${zhCN.agents.providerRunRefreshFailed}: ${formatErrorMessage(error)}`);
      }
    } catch (error) {
      setAgentProviderBatchRunError(`${zhCN.agents.batchRunFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAgentProviderBatchRunBusy(false);
    }
  }

  useEffect(() => {
    let cancelled = false;
    let disconnect: (() => void) | undefined;

    async function refreshIfMounted() {
      const [next, desktop] = await Promise.all([loadIDEData(), loadDesktopStatus()]);
      if (cancelled) {
        return;
      }
      setIDEData(next);
      setDesktopStatus(desktop);
      syncFrontierQueueFromIDEData(next);
      syncAIConversationFromIDEData(next);
      void refreshAIPromptRegistry();
      void refreshAIConversationSessions();
      void refreshEventlogEvents(eventlogFilterRef.current);
      setSelectedNodeId(current => {
        if (next.graphNodes.some(node => node.id === current)) {
          return current;
        }
        return '';
      });
      setSelectedReplayEventId(current => {
        if (next.replayEvents.some(event => event.id === current) || eventlogEventsRef.current.events.some(event => event.id === current)) {
          return current;
        }
        return eventlogEventsRef.current.events[0]?.id ?? next.replayEvents[0]?.id ?? '';
      });
      setSelectedReportFindingId(current => {
        if (next.reportFindings.some(finding => finding.id === current)) {
          return current;
        }
        return next.reportFindings[0]?.id ?? '';
      });
    }

    async function connectEventStreamIfMounted() {
      const cleanup = await connectIDEEventStream(event => {
        if (shouldRefreshForEvent(event)) {
          void refreshIfMounted();
        }
        if (shouldRefreshFrontierQueueForEvent(event)) {
          void refreshFrontierQueue(frontierQueueQueryRef.current);
          void refreshFrontierDependencies(frontierQueueQueryRef.current);
          void refreshFrontierMonitor(frontierQueueQueryRef.current);
        }
      });
      if (cancelled) {
        cleanup();
        return;
      }
      disconnect?.();
      disconnect = cleanup;
    }

    void refreshIfMounted();
    void connectEventStreamIfMounted();
    const interval = window.setInterval(() => void refreshIfMounted(), 30_000);
    return () => {
      cancelled = true;
      disconnect?.();
      window.clearInterval(interval);
    };
  }, []);

  useEffect(() => {
    frontierQueueQueryRef.current = frontierQueueQuery;
  }, [frontierQueueQuery]);

  useEffect(() => {
    eventlogFilterRef.current = eventlogFilter;
  }, [eventlogFilter]);

  useEffect(() => {
    eventlogEventsRef.current = eventlogEvents;
  }, [eventlogEvents]);

  const selectedNode = useMemo(
    () => ideData.graphNodes.find(node => node.id === selectedNodeId),
    [ideData.graphNodes, selectedNodeId],
  );
  const selectedReplayEvent = useMemo(
    () => eventlogEvents.events.find(event => event.id === selectedReplayEventId) ?? ideData.replayEvents.find(event => event.id === selectedReplayEventId) ?? eventlogEvents.events[0] ?? ideData.replayEvents[0],
    [eventlogEvents.events, ideData.replayEvents, selectedReplayEventId],
  );

  useEffect(() => {
    if (missionDirty) {
      return;
    }
    setMissionNameDraft(ideData.mission.name);
    setMissionGoalDraft(ideData.mission.goal);
    setMissionCommandDraft(ideData.mission.command);
    setMissionStatus(ideData.mission.status);
  }, [ideData.mission, missionDirty]);

  useEffect(() => {
    if (mode === 'ai') {
      void refreshAIConversation();
      void refreshAIActions();
      void refreshAIConversationSessions();
      void refreshFrontierQueue(frontierQueueQuery);
      void refreshFrontierDependencies(frontierQueueQuery);
      void refreshFrontierMonitor(frontierQueueQuery);
    }
  }, [mode]);

  useEffect(() => {
    if (mode === 'agents') {
      void refreshRuntimeWorkerState();
    }
  }, [mode]);

