  async function runSearch() {
    const query = searchQuery.trim();
    const requestID = workspaceSearchRequestRef.current + 1;
    workspaceSearchRequestRef.current = requestID;
    setSearchResults([]);
    if (!query) {
      setWorkspaceSearchState('invalid');
      return;
    }
    setWorkspaceSearchState('loading');
    try {
      const results = await searchWorkspace(searchQuery);
      if (workspaceSearchRequestRef.current !== requestID) {
        return;
      }
      setSearchResults(results);
      setWorkspaceSearchState('success');
    } catch {
      if (workspaceSearchRequestRef.current !== requestID) {
        return;
      }
      setWorkspaceSearchState('error');
    }
  }

