  async function openAIContextReference(reference: AIContextReference) {
    const id = reference.id?.trim() ?? '';
    const kind = reference.kind?.trim() ?? '';
    const path = (reference.path || '').trim();
    const filePath = aiReferenceFilePath(reference);
    if (!id && !path) {
      return;
    }
    const statusLabel = reference.label || id || path;
    if (filePath) {
      await onOpenReportActionFile(filePath);
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'execution' || id.startsWith('exec-')) {
      await inspectExecution(id || path);
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'graphNode') {
      setSelectedNodeId(id);
      setMode('graph');
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'replayEvent' || kind === 'replayRun') {
      setSelectedReplayEventId(id);
      setMode('replay');
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'reportFinding' || kind === 'finding') {
      setSelectedReportFindingId(id);
      setMode('report');
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'blackboard') {
      setMode('blackboard');
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'agentTask' || kind === 'agent') {
      setMode('agents');
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'frontierDependency') {
      setMode(frontierDependencyReferenceMode(reference));
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'harnessCase' || kind === 'harnessResult' || kind === 'harness') {
      setMode('harness');
      setHarnessStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'plannerPlan' || kind === 'orchestratorRun' || kind === 'orchestratorObservation' || kind === 'orchestratorAdvance' || kind === 'aiMessage' || kind === 'aiActionTrace' || kind === 'toolCall' || kind === 'actionTrace') {
      setMode('ai');
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    if (kind === 'provider' || kind === 'settings' || kind === 'prompt' || kind === 'promptVersion') {
      setSettingsFocus(current => settingsFocusForAIReference(reference, (current?.sequence ?? 0) + 1));
      setMode('settings');
      setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
      return;
    }
    setAIStatus(`${zhCN.ai.referenceOpened}: ${statusLabel}`);
  }

  async function refreshAIConversation() {
    setAIStatus(zhCN.ai.loadingConversation);
    try {
      const conversation = await fetchAIConversation();
      setAIConversation(conversation);
      setAIStatus(aiConversationLoadedStatus(conversation));
      void refreshAIConversationSessions();
    } catch (error) {
      setAIConversation(null);
      setAIStatus(`${zhCN.ai.loadFailed}: ${formatErrorMessage(error)}`);
    }
  }

  function updateAICollaborationDraft(patch: Partial<AICollaborationDispatchDraft>) {
    setAICollaborationDraft(current => ({ ...current, ...patch }));
  }

  function buildAICollaborationTitle(explicit: string, body: string, fallbackTitle: string, fallbackBody: string) {
    const explicitTitle = explicit.trim() || fallbackTitle.trim();
    if (explicitTitle) {
      return explicitTitle;
    }
    const firstLine = (body.trim() || fallbackBody.trim()).split(/\r?\n/).find(line => line.trim() !== '')?.trim();
    return firstLine ? firstLine.slice(0, 80) : '';
  }

  async function createAICollaborationBlackboardGoal(): Promise<BlackboardItem | null> {
    const content = aiCollaborationDraft.blackboardContent.trim() || aiCollaborationDraft.taskGoal.trim();
    if (!content) {
      setAICollaborationStatus(zhCN.ai.collaborationDispatchGoalRequired);
      return null;
    }
    const title = buildAICollaborationTitle(
      aiCollaborationDraft.blackboardTitle,
      aiCollaborationDraft.blackboardContent,
      aiCollaborationDraft.taskTitle,
      aiCollaborationDraft.taskGoal,
    );
    const request: BlackboardItemCreateRequest = {
      kind: 'goal',
      title,
      content,
      status: 'open',
      priority: aiCollaborationDraft.taskPriority.trim() || undefined,
      source: aiCollaborationDraft.blackboardSource.trim() || aiCollaborationDraft.taskSource.trim() || 'AI 工作台协作投递',
      filePath: aiCollaborationDraft.filePath.trim() || undefined,
    };
    setAICollaborationBusy('blackboard');
    setAICollaborationStatus(zhCN.ai.collaborationDispatchCreatingBlackboard);
    try {
      const item = await createBlackboardItem(request);
      setAICollaborationLastBlackboard(item);
      setAICollaborationDraft(current => ({ ...current, blackboardItemId: item.id }));
      setAICollaborationStatus(`${zhCN.ai.collaborationDispatchBlackboardCreated}: ${item.id}`);
      await refresh();
      return item;
    } catch (error) {
      setAICollaborationStatus(`${zhCN.ai.collaborationDispatchFailed}: ${formatErrorMessage(error)}`);
      return null;
    } finally {
      setAICollaborationBusy('');
    }
  }

  async function createAICollaborationAgentTask() {
    const blackboardContent = aiCollaborationDraft.blackboardContent.trim() || aiCollaborationDraft.taskGoal.trim();
    const taskGoal = aiCollaborationDraft.taskGoal.trim() || blackboardContent;
    if (!blackboardContent || !taskGoal) {
      setAICollaborationStatus(zhCN.ai.collaborationDispatchGoalRequired);
      return;
    }
    const blackboardTitle = buildAICollaborationTitle(
      aiCollaborationDraft.blackboardTitle,
      aiCollaborationDraft.blackboardContent,
      aiCollaborationDraft.taskTitle,
      aiCollaborationDraft.taskGoal,
    );
    const taskTitle = buildAICollaborationTitle(
      aiCollaborationDraft.taskTitle,
      aiCollaborationDraft.taskGoal,
      aiCollaborationDraft.blackboardTitle,
      aiCollaborationDraft.blackboardContent,
    );
    const linkedBlackboardItemId = aiCollaborationDraft.blackboardItemId.trim();
    setAICollaborationBusy('agent');
    try {
      const matchingBlackboard = aiCollaborationLastBlackboard
        && aiCollaborationLastBlackboard.title === blackboardTitle
        && aiCollaborationLastBlackboard.content === blackboardContent
        ? aiCollaborationLastBlackboard
        : null;
      let blackboardItem = matchingBlackboard;
      if (!blackboardItem && !linkedBlackboardItemId) {
        setAICollaborationStatus(zhCN.ai.collaborationDispatchCreatingBlackboard);
        blackboardItem = await createBlackboardItem({
          kind: 'goal',
          title: blackboardTitle,
          content: blackboardContent,
          status: 'open',
          priority: aiCollaborationDraft.taskPriority.trim() || undefined,
          source: aiCollaborationDraft.blackboardSource.trim() || aiCollaborationDraft.taskSource.trim() || 'AI 工作台协作投递',
          filePath: aiCollaborationDraft.filePath.trim() || undefined,
        });
        setAICollaborationLastBlackboard(blackboardItem);
        setAICollaborationDraft(current => ({ ...current, blackboardItemId: blackboardItem?.id ?? current.blackboardItemId }));
      }
      setAICollaborationStatus(zhCN.ai.collaborationDispatchCreatingAgentTask);
      const request: AgentTaskCreateRequest = {
        title: taskTitle,
        goal: taskGoal,
        role: aiCollaborationDraft.taskRole.trim(),
        agentId: aiCollaborationDraft.taskAgentId.trim() || undefined,
        priority: aiCollaborationDraft.taskPriority.trim() || undefined,
        source: aiCollaborationDraft.taskSource.trim() || aiCollaborationDraft.blackboardSource.trim() || 'AI 工作台协作投递',
        blackboardItemId: linkedBlackboardItemId || blackboardItem?.id,
        filePath: aiCollaborationDraft.filePath.trim() || undefined,
      };
      const task = await createAgentTask(request);
      setAICollaborationLastTask(task);
      setAICollaborationStatus(`${zhCN.ai.collaborationDispatchAgentTaskCreated}: ${task.id}`);
      await refresh();
    } catch (error) {
      setAICollaborationStatus(`${zhCN.ai.collaborationDispatchFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAICollaborationBusy('');
    }
  }

  async function startNewAIConversation() {
    if (abortAIChatStreamControllerRef.current && !abortAIChatStreamControllerRef.current.signal.aborted) {
      setAISessionStatus(zhCN.ai.streamAlreadyRunning);
      return;
    }
    setAISessionBusyId('new');
    setAISessionStatus(zhCN.ai.sessionStartingNew);
    try {
      const response = await startNewAIConversationSession();
      setAIConversation(response.conversation);
      setAISessions(response.sessions);
      setAIDraft('');
      setAIStreamEvents([]);
      setAILiveResponse('');
      setAIStatus(aiConversationLoadedStatus(response.conversation));
      setAISessionStatus(`${zhCN.ai.sessionStarted}: ${response.session.path || response.session.id}`);
      void refresh();
    } catch (error) {
      setAISessionStatus(`${zhCN.ai.sessionOperationFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAISessionBusyId('');
    }
  }

  async function restoreArchivedAIConversation(sessionId: string) {
    const normalized = sessionId.trim();
    if (!normalized) {
      setAISessionStatus(zhCN.ai.sessionMissing);
      return;
    }
    if (abortAIChatStreamControllerRef.current && !abortAIChatStreamControllerRef.current.signal.aborted) {
      setAISessionStatus(zhCN.ai.streamAlreadyRunning);
      return;
    }
    setAISessionBusyId(normalized);
    setAISessionStatus(`${zhCN.ai.sessionRestoring}: ${normalized}`);
    try {
      const response = await restoreAIConversationSession(normalized);
      setAIConversation(response.conversation);
      setAISessions(response.sessions);
      setAIStreamEvents([]);
      setAILiveResponse('');
      setAIStatus(aiConversationLoadedStatus(response.conversation));
      setAISessionStatus(`${zhCN.ai.sessionRestored}: ${response.session.path || response.session.id}`);
      void refresh();
    } catch (error) {
      setAISessionStatus(`${zhCN.ai.sessionOperationFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAISessionBusyId('');
    }
  }

  async function runAIConversationSessionSearch() {
    const query = aiSessionSearchQuery.trim();
    if (!query) {
      setAISessionSearchStatus(zhCN.ai.sessionSearchQueryRequired);
      setAISessionSearchResults([]);
      return;
    }
    setAISessionSearchBusy(true);
    setAISessionSearchStatus(`${zhCN.ai.sessionSearching}: ${query}`);
    try {
      const results = await searchAIConversationSessions(query);
      setAISessionSearchResults(results);
      setAISessionSearchStatus(`${zhCN.ai.sessionSearchComplete}: ${results.length} ${zhCN.ai.sessionSearchResultCount}`);
    } catch (error) {
      setAISessionSearchStatus(`${zhCN.ai.sessionSearchFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAISessionSearchBusy(false);
    }
  }

  async function exportArchivedAIConversation(sessionId: string, format: string, includeContextReferences: boolean) {
    const normalized = sessionId.trim();
    if (!normalized) {
      setAISessionStatus(zhCN.ai.sessionMissing);
      return;
    }
    setAISessionExportBusyId(normalized);
    setAISessionExportResult(null);
    setAISessionExportPath('');
    setAISessionStatus(`${zhCN.ai.sessionExporting}: ${normalized}`);
    try {
      const result = await exportAIConversationSession({
        sessionId: normalized,
        format,
        includeContextReferences,
      });
      setAISessionExportResult(result);
      setAISessionExportPath(result.path);
      setAISessionStatus(`${zhCN.ai.sessionExported}: ${result.path}`);
      await refresh();
    } catch (error) {
      setAISessionStatus(`${zhCN.ai.sessionExportFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAISessionExportBusyId('');
    }
  }

  async function openAIConversationExportFile(path: string) {
    const filePath = path.trim();
    if (!filePath) {
      return;
    }
    setMode('mission');
    await openWorkspaceFile({ id: filePath, label: filePath, meta: zhCN.ai.sessionExported, filePath });
  }

  function currentAIContextReferences(): AIContextReference[] {
    const references: AIContextReference[] = [];
    const seen = new Set<string>();
    const add = (reference: AIContextReference) => {
      if (!reference.id || !reference.kind || !reference.label) {
        return;
      }
      const key = `${reference.kind}:${reference.id}:${reference.path ?? ''}`;
      if (seen.has(key)) {
        return;
      }
      seen.add(key);
      references.push(reference);
    };
    if (openFile?.path) {
      add({
        id: openFile.path,
        kind: 'file',
        label: zhCN.ai.currentFileContext,
        path: openFile.path,
        source: 'ide.selection',
      });
    }
    if (selectedExecutionId) {
      const execution = ideData.executionSteps.find(item => item.id === selectedExecutionId);
      add({
        id: selectedExecutionId,
        kind: 'execution',
        label: execution?.label ? `${zhCN.ai.currentExecutionContext}: ${execution.label}` : zhCN.ai.currentExecutionContext,
        path: execution?.logPath,
        source: 'ide.selection',
      });
    }
    if (selectedNode?.id) {
      add({
        id: selectedNode.id,
        kind: 'graphNode',
        label: `${zhCN.ai.currentGraphContext}: ${selectedNode.label}`,
        path: selectedNode.path,
        source: 'ide.selection',
      });
    }
    if (selectedReplayEvent?.id) {
      add({
        id: selectedReplayEvent.id,
        kind: 'replayEvent',
        label: `${zhCN.ai.currentReplayContext}: ${selectedReplayEvent.event}`,
        path: selectedReplayEvent.filePath,
        source: 'ide.selection',
      });
    }
    const selectedFinding = ideData.reportFindings.find(finding => finding.id === selectedReportFindingId);
    if (selectedFinding) {
      add({
        id: selectedFinding.id,
        kind: 'reportFinding',
        label: `${zhCN.ai.currentReportContext}: ${selectedFinding.title}`,
        path: selectedFinding.filePath || selectedFinding.path,
        source: 'ide.selection',
      });
    }
    return references;
  }

  async function sendAIMessage() {
    if (abortAIChatStreamControllerRef.current && !abortAIChatStreamControllerRef.current.signal.aborted) {
      setAIStatus(zhCN.ai.streamAlreadyRunning);
      return;
    }
    const message = aiDraft.trim();
    if (!message) {
      setAIStatus(zhCN.ai.emptyMessage);
      return;
    }
    const contextReferences = currentAIContextReferences();
    const abortController = new AbortController();
    abortAIChatStreamControllerRef.current = abortController;
    setAISending(true);
    setAIStreamStopping(false);
    setAIStreamEvents([]);
    setAILiveResponse('');
    setAIStatus(zhCN.ai.streaming);
    try {
      const response = await streamAIChatMessage(message, contextReferences, streamEvent => {
        setAIStreamEvents(current => mergeAIStreamEvents(current, streamEvent));
        appendAIStreamDelta(streamEvent);
        if (streamEvent.conversation) {
          setAIConversation(streamEvent.conversation);
        }
        if (streamEvent.response?.conversation) {
          setAIConversation(streamEvent.response.conversation);
          setAILiveResponse('');
        }
        const liveStatus = formatAIStreamLiveStatus(streamEvent);
        setAIStatus(liveStatus ? `${zhCN.ai.streaming}: ${liveStatus}` : zhCN.ai.streaming);
      }, { signal: abortController.signal });
      setAIConversation(response.conversation);
      setAIStreamEvents(current => mergeAIStreamActionResults(current, response));
      setAIStreamStopping(false);
      setAILiveResponse('');
      setAIDraft('');
      const responseMeta = [response.provider, response.model].filter(Boolean).join(' · ');
      setAIStatus(responseMeta ? `${zhCN.ai.replyReceived}: ${responseMeta}` : zhCN.ai.replyReceived);
      void refreshAIConversationSessions();
    } catch (error) {
      if (abortController.signal.aborted) {
        setAIStreamStopping(false);
        setAIStatus(zhCN.ai.streamStopped);
        return;
      }
      if (shouldFallbackAIChatStream(error)) {
        setAIStatus(zhCN.ai.streamFallback);
        try {
          const response = await sendAIChatMessage(message, contextReferences);
          setAIConversation(response.conversation);
          setAILiveResponse('');
          setAIDraft('');
          const responseMeta = [response.provider, response.model].filter(Boolean).join(' · ');
          setAIStatus(responseMeta ? `${zhCN.ai.replyReceived}: ${responseMeta}` : zhCN.ai.replyReceived);
          void refreshAIConversationSessions();
        } catch (fallbackError) {
          setAIStatus(`${zhCN.ai.sendFailed}: ${formatErrorMessage(fallbackError)}`);
        }
      } else {
        setAIStatus(`${zhCN.ai.sendFailed}: ${formatErrorMessage(error)}`);
      }
    } finally {
      if (abortAIChatStreamControllerRef.current === abortController) {
        abortAIChatStreamControllerRef.current = null;
      }
      setAIStreamStopping(false);
      setAISending(false);
    }
  }

  function stopAIChatStreaming() {
    const controller = abortAIChatStreamControllerRef.current;
    if (!controller || controller.signal.aborted) {
      setAIStatus(zhCN.ai.streamStopped);
      setAISending(false);
      setAIStreamStopping(false);
      return;
    }
    setAIStreamStopping(true);
    setAIStatus(zhCN.ai.stoppingStreaming);
    abortAIChatStreamControllerRef.current?.abort();
  }

  function appendAIStreamDelta(streamEvent: AIChatStreamEvent) {
    const delta = streamEvent.textDelta ?? streamEvent.contentDelta ?? streamEvent.delta ?? '';
    if (delta === '') {
      return;
    }
    setAILiveResponse(current => `${current}${delta}`);
  }

  async function refreshAIActions() {
    setAIActionStatus(zhCN.aiActions.loading);
    try {
      const actions = await fetchAIActions();
      setAIActions(actions);
      setAIActionStatus(actions.length > 0 ? `${zhCN.aiActions.loaded}: ${actions.length}` : zhCN.aiActions.empty);
    } catch (error) {
      setAIActions([]);
      setAIActionResult(null);
      setAIActionStatus(`${zhCN.aiActions.loadFailed}: ${formatErrorMessage(error)}`);
    }
  }

  async function runSelectedAIAction(action: AIAction) {
    const executionInputError = aiExecutionInputError(action, aiActionInputs);
    if (executionInputError) {
      setAIActionStatus(executionInputError);
      setAIActionResult(null);
      return;
    }
    const request = buildAIActionRequest(action, aiActionInputs);
    if (action.kind === 'command' && !request) {
      setAIActionStatus(zhCN.aiActions.commandRequired);
      setAIActionResult(null);
      return;
    }
    if (isGoalAIAction(action) && !request) {
      setAIActionStatus(zhCN.aiActions.goalDecomposeRequired);
      setAIActionResult(null);
      return;
    }
    if (action.id === 'workspace.search' && !request) {
      setAIActionStatus(zhCN.aiActions.queryRequired);
      setAIActionResult(null);
      return;
    }
    if (action.id === 'workspace.rename_file' && !request) {
      setAIActionStatus(zhCN.aiActions.targetPathRequired);
      setAIActionResult(null);
      return;
    }
    if (isEvidenceAIAction(action) && !request) {
      setAIActionStatus(zhCN.aiActions.evidenceIngestRequired);
      setAIActionResult(null);
      return;
    }
    if (isWorkspaceFileAIAction(action) && !request) {
      setAIActionStatus(zhCN.aiActions.pathRequired);
      setAIActionResult(null);
      return;
    }
    if (action.id === 'report.create_finding' && !request) {
      setAIActionStatus(zhCN.aiActions.reportFindingRequired);
      setAIActionResult(null);
      return;
    }
    if (isBlackboardAIAction(action) && !request) {
      setAIActionStatus(zhCN.aiActions.blackboardWriteRequired);
      setAIActionResult(null);
      return;
    }
    if (isAgentAIAction(action) && !request) {
      setAIActionStatus(
        action.id === 'agent.profiles.create'
          ? zhCN.aiActions.agentProfileCreateRequired
          : action.id === 'agent.profiles.update' || action.id === 'agent.profiles.delete'
            ? zhCN.aiActions.agentProfileIdRequired
            : action.id === 'agent.tasks.run'
              ? zhCN.aiActions.agentProviderRunRequired
              : zhCN.aiActions.agentCreateRequired,
      );
      setAIActionResult(null);
      return;
    }
    if (isHarnessAIAction(action) && !request) {
      setAIActionStatus(
        action.id === 'harness.run'
          ? zhCN.aiActions.harnessRunRequired
          : action.id === 'harness.cases.from_failure'
            ? zhCN.aiActions.harnessFromFailureRequired
            : action.id === 'harness.cases.from_eventlog'
              ? zhCN.aiActions.harnessFromEventlogRequired
              : action.id === 'harness.cases.from_workspace_snapshot'
                ? zhCN.aiActions.harnessFromWorkspaceSnapshotRequired
                : action.id === 'harness.cases.from_environment_snapshot'
                  ? zhCN.aiActions.harnessFromEnvironmentSnapshotRequired
                  : action.id === 'harness.cases.from_ai_conversation'
                    ? zhCN.aiActions.harnessFromAIConversationRequired
                  : zhCN.aiActions.harnessCreateRequired,
      );
      setAIActionResult(null);
      return;
    }
    if (isSisyphusAIAction(action) && !request) {
      setAIActionStatus(zhCN.aiActions.sisyphusRequired);
      setAIActionResult(null);
      return;
    }
    if (isFrontierAIAction(action) && !request) {
      setAIActionStatus(
        action.id === 'frontier.loop'
          ? zhCN.aiActions.frontierLoopRequired
          : action.id === 'frontier.autopilot'
          ? zhCN.aiActions.frontierAutopilotRequired
          : action.id === 'frontier.step'
          ? zhCN.aiActions.frontierStepRequired
          : action.id === 'frontier.execute_next'
            ? zhCN.aiActions.frontierExecuteNextRequired
            : zhCN.aiActions.frontierPrioritizeRequired,
      );
      setAIActionResult(null);
      return;
    }
    if (isOrchestratorAIAction(action) && !request) {
      setAIActionStatus(
        action.id === 'orchestrator.observe'
          ? zhCN.aiActions.orchestratorObserveRequired
          : action.id === 'orchestrator.step'
            ? zhCN.aiActions.orchestratorStepRequired
            : action.id === 'orchestrator.loop'
              ? zhCN.aiActions.orchestratorLoopRequired
              : action.id === 'orchestrator.auto_advance'
                ? zhCN.aiActions.orchestratorAutoAdvanceRequired
                : action.id === 'orchestrator.advance'
                  ? zhCN.aiActions.orchestratorAdvanceRequired
                  : zhCN.aiActions.orchestratorRunRequired,
      );
      setAIActionResult(null);
      return;
    }
    if (isPlannerAIAction(action) && !request) {
      setAIActionStatus(
        action.id === 'planner.advance'
          ? zhCN.aiActions.plannerAdvanceRequired
          : action.id === 'planner.step'
            ? zhCN.aiActions.plannerStepRequired
          : action.id === 'planner.observe'
            ? zhCN.aiActions.plannerObserveRequired
          : action.id === 'planner.execute'
            ? zhCN.aiActions.plannerExecuteRequired
            : zhCN.aiActions.plannerDispatchRequired,
      );
      setAIActionResult(null);
      return;
    }
    if (isPromptAIAction(action) && !request) {
      setAIActionStatus(
        action.id === 'prompt.harness.run'
          ? zhCN.aiActions.promptHarnessRequired
          : action.id === 'prompt.harness.compare'
            ? zhCN.aiActions.promptHarnessCompareRequired
            : action.id === 'prompt.harness.batch_compare'
              ? zhCN.aiActions.promptHarnessBatchCompareRequired
              : action.id === 'prompt.harness.from_ai_conversation'
                ? zhCN.aiActions.promptHarnessFromAIConversationRequired
              : action.id === 'prompt.harness.promote_best'
                ? zhCN.aiActions.promptHarnessPromoteRequired
              : action.id === 'prompt.registry.diff'
                ? zhCN.aiActions.promptDiffRequired
                : zhCN.aiActions.promptUpdateRequired,
      );
      setAIActionResult(null);
      return;
    }
    if (isToolResultAIAction(action) && !request) {
      setAIActionStatus(zhCN.aiActions.toolResultParseRequired);
      setAIActionResult(null);
      return;
    }
    if (!request) {
      setAIActionStatus(zhCN.aiActions.structuredInputRequired);
      setAIActionResult(null);
      return;
    }
    setAIActionRunningId(action.id);
    setAIActionResult(null);
    setAIActionStatus(`${zhCN.aiActions.running}: ${action.label}`);
    try {
      const result = await runAIAction(request);
      setAIActionResult(result);
      setAIConversation(result.conversation);
      if (result.execution) {
        setSelectedExecutionId(result.execution.id);
        setExecutionStatus(`${zhCN.execution.selected}: ${result.execution.id}`);
      }
      setAIActionStatus(`${zhCN.aiActions.result}: ${result.result.summary || aiActionResultLabel(result.result)}`);
      if (isRuntimeWorkerAIAction(action)) {
        if (result.result.runtimeWorkerState) {
          setRuntimeWorkerState(result.result.runtimeWorkerState);
          setRuntimeWorkerLoadState('ready');
        }
        setAIActionInputs(current => ({
          ...current,
          [aiActionInputKey(action.id, 'transportAuthToken')]: '',
        }));
        void refreshRuntimeWorkerState();
      }
      try {
        await refresh();
      } catch (refreshError) {
        setAIActionStatus(`${zhCN.aiActions.resultRefreshFailed}: ${formatErrorMessage(refreshError)}`);
      }
      if (isExecutionAIAction(action) && result.execution) {
        await refreshSelectedExecutionDetails(result.execution.id);
      }
      if (shouldRefreshFrontierStateForAIAction(action)) {
        if (result.result.frontierDependencies) {
          setFrontierDependencies(result.result.frontierDependencies);
          setFrontierDependenciesStatus(`${zhCN.ai.frontierDependenciesLoaded}: ${result.result.frontierDependencies.count} ${zhCN.ai.frontierDependenciesClusterCount}`);
        } else {
          void refreshFrontierDependencies(frontierQueueQuery);
        }
        if (result.frontierQueue) {
          setFrontierQueue(result.frontierQueue);
          setFrontierQueueStatus(`${zhCN.ai.frontierQueueLoaded}: ${result.frontierQueue.count} ${zhCN.ai.frontierQueueItemCount}`);
        } else {
          void refreshFrontierQueue(frontierQueueQuery);
        }
        void refreshFrontierMonitor(frontierQueueQuery);
      }
      window.setTimeout(() => void refresh(), 1000);
      void refreshAIConversation();
    } catch (error) {
      setAIActionResult(null);
      setAIActionStatus(`${zhCN.aiActions.runFailed}: ${formatErrorMessage(error)}`);
    } finally {
      setAIActionRunningId('');
    }
  }

  function updateFrontierQueueQuery(patch: Partial<FrontierQueueQuery>) {
    setFrontierQueueQuery(current => ({ ...current, ...patch }));
  }

  function updateAIFailureStrategyDraft(patch: Partial<AIFailureStrategyDraft>) {
    setAIFailureStrategyDraft(current => ({ ...current, ...patch }));
  }

  async function refreshFrontierQueue(query: FrontierQueueQuery = frontierQueueQuery): Promise<FrontierQueue | null> {
    setFrontierQueueBusy('refresh');
    setFrontierQueueStatus(zhCN.ai.frontierQueueLoading);
    try {
      const queue = await loadFrontierQueue(normalizeFrontierQueueQuery(query));
      setFrontierQueue(queue);
      setFrontierQueueStatus(`${zhCN.ai.frontierQueueLoaded}: ${queue.count} ${zhCN.ai.frontierQueueItemCount}`);
      return queue;
    } catch (error) {
      setFrontierQueueStatus(`${zhCN.ai.frontierQueueLoadFailed}: ${formatErrorMessage(error)}`);
      return null;
    } finally {
      setFrontierQueueBusy('');
    }
  }

