  function compactHarnessDraft(draft: HarnessCaseCreateRequest): HarnessCaseCreateRequest | null {
    const title = draft.title.trim();
    const goal = draft.goal.trim();
    const command = draft.command.trim();
    const expectedResult = draft.expectedResult.trim();
    const kind = draft.kind?.trim();
    const agentTaskId = draft.agentTaskId?.trim();
    const isAgentProviderTask = kind === 'agent_provider_task';
    if (!title || !goal || !expectedResult || (!command && !isAgentProviderTask) || (isAgentProviderTask && !agentTaskId)) {
      return null;
    }
    const maxTokensValue = String(draft.maxTokens ?? '').trim();
    const maxTokens = Number(maxTokensValue);
    const optionalFields = {
      kind,
      promptId: draft.promptId?.trim(),
      promptVersionId: draft.promptVersionId?.trim() || draft.versionId?.trim(),
      agentRole: draft.agentRole?.trim(),
      source: draft.source?.trim(),
      filePath: draft.filePath?.trim(),
      replayRunId: draft.replayRunId?.trim(),
      snapshotId: draft.snapshotId?.trim(),
      snapshotPath: draft.snapshotPath?.trim(),
      agentTaskId,
      blackboardItemId: draft.blackboardItemId?.trim(),
      providerName: draft.providerName?.trim(),
      model: draft.model?.trim(),
      maxTokens: Number.isInteger(maxTokens) && maxTokens > 0 ? maxTokens : undefined,
    };
    return { title, goal, command, expectedResult, ...optionalFields };
  }

  async function createHarnessCaseDraft(draft: HarnessCaseCreateRequest) {
    const request = compactHarnessDraft(draft);
    if (!request) {
      setHarnessStatus(zhCN.harness.requiredFields);
      return;
    }
    setHarnessStatus(zhCN.harness.creating);
    try {
      const created = await createHarnessCase(request);
      setHarnessStatus(`${zhCN.harness.created}: ${created.id}`);
      setHarnessDraft({
        title: '',
        goal: '',
        kind: '',
        command: '',
        expectedResult: '',
        promptId: '',
        promptVersionId: '',
        agentRole: '',
        source: '',
        filePath: '',
        replayRunId: '',
        snapshotId: '',
        snapshotPath: '',
        agentTaskId: '',
        blackboardItemId: '',
        providerName: '',
        model: '',
      });
      await refreshHarness();
    } catch (error) {
      setHarnessStatus(`${zhCN.harness.createFailed}: ${formatErrorMessage(error)}`);
    }
  }

