  async function runManifestToolAction(action: ToolAction): Promise<ExecutionStep | null> {
    if (!action.id) {
      return null;
    }
    const draft = toolActionLaunchDraft(action, toolActionDrafts);
    if (toolActionRunDisabled(action, draft)) {
      setToolLaunchStatus(zhCN.toolLaunch.targetRequired);
      return null;
    }
    const request = toolActionRunRequest(action, draft);
    setToolLaunchStatus(`${zhCN.toolLaunch.starting}: ${action.label}`);
    try {
      const result = await runToolchainAction(action.id, request);
      setToolLaunchStatus(`${zhCN.toolLaunch.started}: ${result.execution.id}`);
      await inspectExecution(result.execution.id);
      await refresh();
      window.setTimeout(() => void refresh(), 1000);
      return result.execution;
    } catch {
      setToolLaunchStatus(zhCN.toolLaunch.failed);
      return null;
    }
  }

