function ActivityBar({ mode, onModeChange }: { mode: IDEMode; onModeChange: (mode: IDEMode) => void }) {
  const primaryModes = modes.filter(item => item.id !== 'settings');
  const settingsMode = modes.find(item => item.id === 'settings');
  const renderModeButton = (item: { id: IDEMode; icon: LucideIcon }) => {
    const Icon = item.icon;
    return (
      <button
        key={item.id}
        type="button"
        className={mode === item.id ? 'activity-button active' : 'activity-button'}
        onClick={() => onModeChange(item.id)}
        title={zhCN.modes[item.id]}
        aria-label={zhCN.modes[item.id]}
      >
        <Icon size={19} />
      </button>
    );
  };
  return (
    <nav className="activity-bar" aria-label={zhCN.shell.activityLabel}>
      <div className="activity-primary">{primaryModes.map(renderModeButton)}</div>
      <div className="activity-utility">{settingsMode && renderModeButton(settingsMode)}</div>
    </nav>
  );
}

function WorkspaceExplorer({
  items,
  workspace,
  workspacePath,
  status,
  searchQuery,
  searchResults,
  searchState,
  onSearchQueryChange,
  onRunSearch,
  onRefresh,
  onOpenFile,
  onOpenSearchResult,
}: {
  items: WorkspaceItem[];
  workspace: string;
  workspacePath: string;
  status: IDEData['status'];
  searchQuery: string;
  searchResults: WorkspaceSearchResult[];
  searchState: WorkspaceSearchState;
  onSearchQueryChange: (value: string) => void;
  onRunSearch: () => void;
  onRefresh: () => void;
  onOpenFile: (item: WorkspaceItem) => void;
  onOpenSearchResult: (result: WorkspaceSearchResult) => void;
}) {
  const workspaceLabel = workspacePathLabel(workspace);
  const workspaceConnected = workspacePath.trim() !== '';
  return (
    <aside className="workspace-explorer">
      <div className="panel-heading">
        <span>{zhCN.shell.workspace}</span>
        <div className="explorer-heading-actions">
          <Search size={14} />
          <button type="button" onClick={onRefresh} aria-label={zhCN.ai.refresh} title={zhCN.ai.refresh}>
            <RefreshCw size={13} />
          </button>
        </div>
      </div>
      <div className="workspace-title" data-state={workspaceConnected ? 'connected' : 'disconnected'}>
        <ChevronDown size={13} />
        <FolderOpen size={14} />
        <span title={workspacePath || workspace}>{workspaceLabel}</span>
      </div>
      <div className="workspace-search">
        <input
          value={searchQuery}
          onChange={event => onSearchQueryChange(event.target.value)}
          onKeyDown={event => { if (event.key === 'Enter' && searchState !== 'loading') onRunSearch(); }}
          placeholder={zhCN.search.placeholder}
          aria-label={zhCN.search.placeholder}
          aria-invalid={searchState === 'invalid'}
        />
        <button type="button" onClick={onRunSearch} disabled={searchState === 'loading'} aria-label={zhCN.shell.search} title={zhCN.shell.search}>
          <Search size={14} />
        </button>
      </div>
      {searchState !== 'idle' && (
        <div className="search-results" aria-live="polite" aria-busy={searchState === 'loading'}>
          <span>
            {searchState === 'success' && searchResults.length > 0
              ? `${zhCN.search.results} · ${searchResults.length} ${zhCN.search.resultCount}`
              : zhCN.search.results}
          </span>
          {searchState === 'invalid' && <small>{zhCN.search.queryRequired}</small>}
          {searchState === 'loading' && <small>{zhCN.search.loading}</small>}
          {searchState === 'error' && <small role="alert">{zhCN.search.failed}</small>}
          {searchState === 'success' && searchResults.length === 0 && <small>{zhCN.search.empty}</small>}
          {searchResults.map(result => (
            <button key={`${result.path}:${result.line}`} type="button" onClick={() => onOpenSearchResult(result)}>
              <strong title={`${result.path}:${result.line}`}>{result.path}:{result.line}</strong>
              <small title={result.text || zhCN.search.empty}>{result.text || zhCN.search.empty}</small>
            </button>
          ))}
        </div>
      )}
      <div className="tree-list">
        {items.length === 0 && <EmptyState text={zhCN.explorer.emptyFiles} />}
        {items.map(item => {
          const isDirectory = item.kind === 'directory';
          const depth = workspaceItemDepth(item.label);
          const metadataLabel = workspaceItemMetadataLabel(item);
          const rowContent = (
            <>
              {isDirectory ? <ChevronDown className="tree-chevron" size={12} /> : <span className="tree-chevron" />}
              {isDirectory ? <FolderOpen className="tree-icon directory" size={14} /> : <FileText className="tree-icon" size={14} />}
              <span className="tree-label" title={item.label}>{workspacePathLabel(item.label)}</span>
            </>
          );
          const className = item.active ? 'tree-row active' : 'tree-row';
          const style = { '--tree-depth': Math.min(depth, 6) } as CSSProperties;
          return isDirectory ? (
            <div key={item.id} className={`${className} directory`} style={style} title={`${item.label}\n${metadataLabel}`}>{rowContent}</div>
          ) : (
            <button key={item.id} type="button" className={className} style={style} onClick={() => onOpenFile(item)} title={`${item.label}\n${metadataLabel}`} aria-label={`${item.label}. ${metadataLabel}`}>{rowContent}</button>
          );
        })}
      </div>
      <details className="explorer-status">
        <summary>
          <span className="explorer-status-heading"><ShieldCheck size={14} /><span>{zhCN.explorer.preflight}</span></span>
          <ChevronRight className="explorer-status-chevron" size={13} />
        </summary>
        <div className="explorer-status-body">
          <div className="check-row"><CircleDot size={12} /> <span>{zhCN.shell.statusBackend}</span><strong>{status.backend}</strong></div>
          <div className="check-row"><CircleDot size={12} /> <span>{zhCN.shell.statusToolchain}</span><strong>{status.toolchain}</strong></div>
        </div>
      </details>
    </aside>
  );
}

function workspacePathLabel(path: string): string {
  const normalized = path.replace(/\\/g, '/').replace(/\/$/, '');
  return normalized.split('/').filter(Boolean).pop() || path || zhCN.explorer.rootFallback;
}

function workspaceItemDepth(path: string): number {
  const normalized = path.replace(/\\/g, '/').replace(/^\.\//, '');
  return Math.max(0, normalized.split('/').filter(Boolean).length - 1);
}

function workspaceItemMetadataLabel(item: WorkspaceItem): string {
  return [
    `${zhCN.explorer.fileKind}: ${item.meta}`,
    item.size !== undefined ? `${zhCN.explorer.fileSize}: ${formatWorkspaceFileSize(item.size)}` : '',
    item.modifiedAt !== undefined ? `${zhCN.explorer.fileModifiedAt}: ${formatDetailTime(item.modifiedAt)}` : '',
  ].filter(Boolean).join('；');
}

function MissionWorkbench({
  data,
  selectedNode,
  openFile,
  fileDraft,
  fileStatus,
  renameFilePath,
  newFilePath,
  newFileContent,
  commandDraft,
  missionNameDraft,
  missionGoalDraft,
  missionCommandDraft,
  missionStatus,
  executionStatus,
  executionLog,
  executionArtifacts,
  executionArtifactsExecutionId,
  selectedExecutionId,
  executionDetailBusy,
  toolActionDrafts,
  toolLaunchStatus,
  onMissionDraftChange,
  onSaveMission,
  onStartMission,
  onFileDraftChange,
  onSaveFile,
  onRenameFilePathChange,
  onRenameFile,
  onDeleteFile,
  onShowFileInFolder,
  onNewFilePathChange,
  onNewFileContentChange,
  onCreateFile,
  onCommandDraftChange,
  onRunCommand,
  onToolActionDraftChange,
  onRunToolAction,
  onSelectExecution,
  onStopExecution,
  onRetryExecution,
  onLoadExecutionLogs,
  onLoadExecutionArtifacts,
  onOpenExecutionFile,
  onFocusGraphNode,
  onFocusReplayEvent,
  onFocusReportFinding,
}: {
  data: IDEData;
  selectedNode?: GraphNode;
  openFile: WorkspaceFileContent | null;
  fileDraft: string;
  fileStatus: string;
  renameFilePath: string;
  newFilePath: string;
  newFileContent: string;
  commandDraft: string;
  missionNameDraft: string;
  missionGoalDraft: string;
  missionCommandDraft: string;
  missionStatus: string;
  executionStatus: string;
  executionLog: ExecutionLog | null;
  executionArtifacts: ExecutionArtifact[];
  executionArtifactsExecutionId: string;
  selectedExecutionId: string;
  executionDetailBusy: ExecutionDetailBusy;
  toolActionDrafts: ToolActionLaunchDrafts;
  toolLaunchStatus: string;
  onMissionDraftChange: (field: keyof Pick<MissionState, 'name' | 'goal' | 'command'>, value: string) => void;
  onSaveMission: () => void;
  onStartMission: () => void;
  onFileDraftChange: (value: string) => void;
  onSaveFile: () => void;
  onRenameFilePathChange: (value: string) => void;
  onRenameFile: () => void;
  onDeleteFile: () => void;
  onShowFileInFolder: () => void;
  onNewFilePathChange: (value: string) => void;
  onNewFileContentChange: (value: string) => void;
  onCreateFile: () => void;
  onCommandDraftChange: (value: string) => void;
  onRunCommand: () => void;
  onToolActionDraftChange: (action: ToolAction, draft: ToolActionLaunchDraft) => void;
  onRunToolAction: (action: ToolAction) => void;
  onSelectExecution: (id: string) => void;
  onStopExecution: (id: string) => void;
  onRetryExecution: (id: string) => void;
  onLoadExecutionLogs: (id: string) => void;
  onLoadExecutionArtifacts: (id: string) => void;
  onOpenExecutionFile: (filePath: string) => void;
  onFocusGraphNode: (nodeId: string) => void;
  onFocusReplayEvent: (eventId: string) => void;
  onFocusReportFinding: (findingId: string) => void;
}) {
  return (
    <section className="mission-workbench">
      <div className="workbench-header">
        <div>
          <p className="eyeline">{zhCN.mission.eyeline}</p>
          <h1>{zhCN.mission.title}</h1>
        </div>
        <button type="button" className="primary-action" onClick={onRunCommand} disabled={commandDraft.trim() === ''}>
          <Radar size={16} />
          {zhCN.mission.runCommand}
        </button>
      </div>
      <div className="mission-grid">
        <div className="conversation-panel">
          <PanelTitle icon={Command} title={zhCN.mission.conversation} meta={zhCN.mission.conversationMeta} />
          <MissionLaunch
            name={missionNameDraft}
            goal={missionGoalDraft}
            command={missionCommandDraft}
            status={missionStatus}
            onDraftChange={onMissionDraftChange}
            onSaveMission={onSaveMission}
            onStartMission={onStartMission}
          />
          <ToolLaunchPanel
            toolActions={data.toolActions}
            toolActionDrafts={toolActionDrafts}
            status={toolLaunchStatus}
            onDraftChange={onToolActionDraftChange}
            onRunToolAction={onRunToolAction}
          />
          <div className="message-list">
            <EmptyState text={zhCN.mission.noMessages} />
          </div>
          <div className="composer">
            <span>{zhCN.mission.composerPrefix} &gt;</span>
            <input value={commandDraft} onChange={event => onCommandDraftChange(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') onRunCommand(); }} placeholder={zhCN.mission.composerPlaceholder} aria-label={zhCN.mission.composerPlaceholder} />
            <button type="button" onClick={onRunCommand} disabled={commandDraft.trim() === ''}>{zhCN.mission.runCommand}</button>
          </div>
        </div>
        <div className="mission-side">
          <FileEditor
            file={openFile}
            draft={fileDraft}
            status={fileStatus}
            renameFilePath={renameFilePath}
            newFilePath={newFilePath}
            newFileContent={newFileContent}
            onDraftChange={onFileDraftChange}
            onSave={onSaveFile}
            onRenameFilePathChange={onRenameFilePathChange}
            onRename={onRenameFile}
            onDelete={onDeleteFile}
            onShowInFolder={onShowFileInFolder}
            onNewFilePathChange={onNewFilePathChange}
            onNewFileContentChange={onNewFileContentChange}
            onCreateFile={onCreateFile}
          />
          <ToolExecution
            steps={data.executionSteps}
            nodes={data.graphNodes}
            events={data.replayEvents}
            findings={data.reportFindings}
            status={executionStatus}
            log={executionLog}
            artifacts={executionArtifacts}
            artifactsExecutionId={executionArtifactsExecutionId}
            selectedExecutionId={selectedExecutionId}
            detailBusy={executionDetailBusy}
            onSelect={onSelectExecution}
            onStop={onStopExecution}
            onRetry={onRetryExecution}
            onLoadLogs={onLoadExecutionLogs}
            onLoadArtifacts={onLoadExecutionArtifacts}
            onOpenExecutionFile={onOpenExecutionFile}
            onFocusGraphNode={onFocusGraphNode}
            onFocusReplayEvent={onFocusReplayEvent}
            onFocusReportFinding={onFocusReportFinding}
          />
          <NodeSummary node={selectedNode} />
        </div>
      </div>
    </section>
  );
}

function AIWorkbench({
  conversation,
  status,
  draft,
  sending,
  streamEvents,
  liveResponse,
  streamStopping,
  sessions,
  sessionStatus,
  sessionBusyId,
  sessionSearchQuery,
  sessionSearchResults,
  sessionSearchStatus,
  sessionSearchBusy,
  sessionExportBusyId,
  sessionExportResult,
  sessionExportPath,
  actions,
  actionStatus,
  actionInputs,
  actionResult,
  actionRunningId,
  promptRegistry,
  executions,
  frontierQueue,
  frontierQueueQuery,
  frontierQueueStatus,
  frontierQueueBusy,
  frontierDependencies,
  frontierDependenciesStatus,
  frontierDependenciesBusy,
  frontierMonitor,
  frontierMonitorStatus,
  frontierMonitorBusy,
  strategySelectionStatus,
  strategySelectionBusy,
  failureStrategyDraft,
  failureStrategyStatus,
  failureStrategyBusy,
  collaborationDraft,
  collaborationStatus,
  collaborationBusy,
  collaborationLastBlackboard,
  collaborationLastTask,
  agentTaskLifecycleBusy,
  agentTaskLifecycleStatus,
  agentTaskEventBusy,
  agentTaskEventStatus,
  blackboardUpdateBusy,
  blackboardUpdateStatus,
  plannerState,
  onDraftChange,
  onRefreshConversation,
  onSendAIMessage,
  onStopAIMessage,
  onRefreshSessions,
  onStartNewSession,
  onRestoreSession,
  onSessionSearchQueryChange,
  onSearchSessions,
  onExportSession,
  onOpenSessionExportPath,
  onRefreshActions,
  onActionInputChange,
  onActionInputsChange,
  onRunAction,
  onFrontierQueueQueryChange,
  onRefreshFrontierQueue,
  onRunFrontierQueueAction,
  onRunFollowupAction,
  onRefreshFrontierDependencies,
  onRunFrontierDependency,
  onRefreshFrontierMonitor,
  onRunStrategySelection,
  onFailureStrategyDraftChange,
  onRunFailureStrategySisyphus,
  onRunFailureStrategyFollowup,
  onOpenReportActionFile,
  onOpenContextReference,
  onCollaborationDraftChange,
  onCreateCollaborationBlackboard,
  onCreateCollaborationAgentTask,
  onUpdateBlackboardItem,
  onUpdateAgentTaskLifecycle,
  onCreateAgentTaskEvent,
  onRefreshCollaboration,
  onOpenAgentTaskFile,
  blackboard,
  agentState,
  orchestratorState,
}: {
  conversation: AIConversation | null;
  status: string;
  draft: string;
  sending: boolean;
  streamEvents: AIChatStreamEvent[];
  liveResponse: string;
  streamStopping: boolean;
  sessions: AIConversationSessionSummary[];
  sessionStatus: string;
  sessionBusyId: string;
  sessionSearchQuery: string;
  sessionSearchResults: AIConversationSearchResult[];
  sessionSearchStatus: string;
  sessionSearchBusy: boolean;
  sessionExportBusyId: string;
  sessionExportResult: AIConversationExportResult | null;
  sessionExportPath: string;
  actions: AIAction[];
  actionStatus: string;
  actionInputs: Record<string, string>;
  actionResult: AIActionRunResponse | null;
  actionRunningId: string;
  promptRegistry: PromptRegistry | null;
  executions: ExecutionStep[];
  frontierQueue: FrontierQueue | null;
  frontierQueueQuery: FrontierQueueQuery;
  frontierQueueStatus: string;
  frontierQueueBusy: string;
  frontierDependencies: FrontierDependencySelection | null;
  frontierDependenciesStatus: string;
  frontierDependenciesBusy: boolean;
  frontierMonitor: FrontierMonitor | null;
  frontierMonitorStatus: string;
  frontierMonitorBusy: boolean;
  strategySelectionStatus: string;
  strategySelectionBusy: boolean;
  failureStrategyDraft: AIFailureStrategyDraft;
  failureStrategyStatus: string;
  failureStrategyBusy: AIFailureStrategyActionID | '';
  collaborationDraft: AICollaborationDispatchDraft;
  collaborationStatus: string;
  collaborationBusy: 'blackboard' | 'agent' | '';
  collaborationLastBlackboard: BlackboardItem | null;
  collaborationLastTask: AgentTask | null;
  agentTaskLifecycleBusy: AgentTaskLifecycleBusy | null;
  agentTaskLifecycleStatus: string;
  agentTaskEventBusy: AgentTaskEventBusy | null;
  agentTaskEventStatus: string;
  blackboardUpdateBusy: BlackboardUpdateBusy | null;
  blackboardUpdateStatus: string;
  plannerState: PlannerState;
  onDraftChange: (value: string) => void;
  onRefreshConversation: () => void;
  onSendAIMessage: () => void;
  onStopAIMessage: () => void;
  onRefreshSessions: () => void;
  onStartNewSession: () => void;
  onRestoreSession: (sessionId: string) => void;
  onSessionSearchQueryChange: (value: string) => void;
  onSearchSessions: () => void;
  onExportSession: (sessionId: string, format: string, includeContextReferences: boolean) => void;
  onOpenSessionExportPath: (path: string) => void;
  onRefreshActions: () => void;
  onActionInputChange: (actionID: string, value: string) => void;
  onActionInputsChange: (values: Record<string, string>) => void;
  onRunAction: (action: AIAction) => void;
  onFrontierQueueQueryChange: (patch: Partial<FrontierQueueQuery>) => void;
  onRefreshFrontierQueue: () => void;
  onRunFrontierQueueAction: (actionId: 'frontier.execute_next' | 'frontier.autopilot', item?: FrontierPriorityItem) => void;
  onRunFollowupAction: AIActionFollowupRunner;
  onRefreshFrontierDependencies: () => void;
  onRunFrontierDependency: (cluster: FrontierDependencyCluster) => void;
  onRefreshFrontierMonitor: () => void;
  onRunStrategySelection: () => void;
  onFailureStrategyDraftChange: (patch: Partial<AIFailureStrategyDraft>) => void;
  onRunFailureStrategySisyphus: (input: AIActionRunInput) => void;
  onRunFailureStrategyFollowup: (actionId: 'frontier.autopilot' | 'harness.cases.from_failure', input: AIActionRunInput) => void;
  onOpenReportActionFile: (filePath: string) => void;
  onOpenContextReference: (reference: AIContextReference) => void;
  onCollaborationDraftChange: (patch: Partial<AICollaborationDispatchDraft>) => void;
  onCreateCollaborationBlackboard: () => void;
  onCreateCollaborationAgentTask: () => void;
  onUpdateBlackboardItem: (item: BlackboardItem, request: BlackboardItemUpdateRequest) => void;
  onUpdateAgentTaskLifecycle: (task: AgentTask, status: AgentTaskLifecycleStatus) => void;
  onCreateAgentTaskEvent: (task: AgentTask, action: AgentTaskEventAction, input: AgentTaskEventSubmitInput) => void;
  onRefreshCollaboration: () => void;
  onOpenAgentTaskFile: (filePath: string) => void;
  blackboard: BlackboardState;
  agentState: AgentState;
  orchestratorState: OrchestratorState;
}) {
  const usage = conversation?.usage;
  const routing = conversation?.routing;
  const providerReady = Boolean(conversation?.provider || conversation?.model || routing?.provider || routing?.model || routing?.finalProvider || routing?.finalModel);
  const statusIsError = status.includes(zhCN.ai.sendFailed) || status.includes(zhCN.ai.loadFailed) || status.includes(zhCN.ai.providerMissing);
  const historyRuns = useMemo(() => buildAIHistoryRuns(conversation), [conversation]);
  const [selectedHistoryRunId, setSelectedHistoryRunId] = useState<string | null>(null);
  const selectedHistoryRun = historyRuns.find(item => item.id === selectedHistoryRunId);
  useEffect(() => {
    if (selectedHistoryRunId && !historyRuns.some(item => item.id === selectedHistoryRunId)) {
      setSelectedHistoryRunId(null);
    }
  }, [historyRuns, selectedHistoryRunId]);
  const focusedMessageIds = new Set(selectedHistoryRun?.messageIds ?? []);
  const displayedMessages = conversation?.messages.filter((message, index) => (
    !selectedHistoryRun || focusedMessageIds.has(aiMessageStableId(message, index))
  )) ?? [];
  const displayedActionTrace = conversation?.actionTrace.filter(item => (
    !selectedHistoryRun || (item.messageId !== undefined && focusedMessageIds.has(item.messageId))
  )) ?? [];
  const fileChanges = useMemo(() => {
    const activeChanges = buildAIFileChangeSet(displayedActionTrace, streamEvents, actionResult);
    const persistedChanges = buildAIConversationFileChanges(conversation);
    return mergeAIFileChangeSets(activeChanges, persistedChanges);
  }, [conversation, displayedActionTrace, streamEvents, actionResult]);
  const [selectedAIFileChangeKey, setSelectedAIFileChangeKey] = useState('');
  const selectedDiffChange = useMemo(
    () => fileChanges.find(change => change.key === selectedAIFileChangeKey) ?? fileChanges.find(change => change.patch) ?? fileChanges[0],
    [fileChanges, selectedAIFileChangeKey],
  );
  useEffect(() => {
    if (selectedDiffChange && selectedAIFileChangeKey !== selectedDiffChange.key) {
      setSelectedAIFileChangeKey(selectedDiffChange.key);
      return;
    }
    if (!selectedDiffChange && selectedAIFileChangeKey) {
      setSelectedAIFileChangeKey('');
    }
  }, [selectedDiffChange, selectedAIFileChangeKey]);
  const [capabilitiesOpen, setCapabilitiesOpen] = useState(false);
  const modelLabel = [conversation?.provider, conversation?.model].filter(Boolean).join(' / ');
  const conversationMeta = formatAITime(conversation?.updatedAt);
  const contextReferenceCount = conversation?.contextReferences.length ?? 0;

  return (
    <section className={capabilitiesOpen ? 'ai-workbench capabilities-open' : 'ai-workbench'} data-ai-workbench="true" data-workbench-mode="ai" aria-label={zhCN.ai.title}>
      <header className="ai-workbench-bar">
        <div className="ai-workbench-tab">
          <BrainCircuit size={15} />
          <strong>{zhCN.ai.conversation}</strong>
          <small>{zhCN.ai.assistantName}</small>
        </div>
        <div className="ai-workbench-state">
          {status && (
            <div className={statusIsError ? 'ai-status error' : 'ai-status'} role={statusIsError ? 'alert' : 'status'} aria-live={statusIsError ? 'assertive' : 'polite'}>
              <CircleDot size={11} />
              <span>{status}</span>
            </div>
          )}
          {conversationMeta && <time dateTime={conversation?.updatedAt}>{conversationMeta}</time>}
        </div>
        <div className="ai-workbench-actions">
          <button type="button" onClick={onStartNewSession} disabled={sending} aria-label={zhCN.ai.sessionNew} title={zhCN.ai.sessionNew}>
            <MessageSquarePlus size={14} />
          </button>
          <button type="button" onClick={onRefreshConversation} aria-label={zhCN.ai.refresh} title={zhCN.ai.refresh}>
            <RefreshCw size={14} />
          </button>
          <button
            type="button"
            className={capabilitiesOpen ? 'active' : ''}
            onClick={() => setCapabilitiesOpen(current => !current)}
            aria-expanded={capabilitiesOpen}
            aria-controls="ai-capability-drawer"
            title={zhCN.ai.capabilityDrawer}
          >
            {capabilitiesOpen ? <PanelRightClose size={14} /> : <PanelRightOpen size={14} />}
            <span className="ai-capability-label">{zhCN.ai.capabilityDrawer}</span>
          </button>
        </div>
      </header>
      <div className="ai-layout">
        <section className="ai-conversation-panel">
          {selectedHistoryRun && (
            <div className="ai-history-focus-banner">
              <span>{zhCN.ai.historyFocused}: {selectedHistoryRun.title}</span>
              <button type="button" onClick={() => setSelectedHistoryRunId(null)}>
                <X size={14} />
                {zhCN.ai.historyShowAll}
              </button>
            </div>
          )}
          <div className="ai-message-list" role="log" aria-live="polite" aria-relevant="additions text" aria-busy={sending}>
            {!conversation && <AIConversationEmptyState text={zhCN.ai.conversationMissing} onStartNew={onStartNewSession} />}
            {conversation && conversation.messages.length === 0 && <AIConversationEmptyState text={zhCN.ai.noMessages} onStartNew={onStartNewSession} />}
            {selectedHistoryRun && displayedMessages.length === 0 && <EmptyState text={zhCN.ai.historyNoFocusedMessages} />}
            {displayedMessages.map((message, index) => (
              <AIMessageRow
                key={`${message.role}-${message.createdAt ?? index}`}
                message={message}
                onOpenReference={onOpenContextReference}
                onRunFollowupAction={onRunFollowupAction}
                actionRunningId={actionRunningId}
              />
            ))}
            {(sending || liveResponse.trim() !== '') && (
              <AIStreamingResponseRow content={liveResponse} />
            )}
          </div>
          <div className="ai-composer">
            <div className="ai-composer-surface">
              <label>
                <span className="visually-hidden">{zhCN.ai.inputLabel}</span>
                <textarea
                  value={draft}
                  onChange={event => onDraftChange(event.target.value)}
                  onKeyDown={event => {
                    if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {
                      onSendAIMessage();
                    }
                  }}
                  placeholder={zhCN.ai.inputPlaceholder}
                  aria-label={zhCN.ai.inputLabel}
                />
              </label>
              <div className="ai-composer-footer">
                <div className="ai-composer-context">
                  {contextReferenceCount > 0 && (
                    <span title={`${contextReferenceCount} ${zhCN.ai.contextReferenceCount}`}>
                      <Paperclip size={13} />
                      {contextReferenceCount} {zhCN.ai.contextReferenceCount}
                    </span>
                  )}
                  {modelLabel && (
                    <span title={modelLabel}>
                      <BrainCircuit size={13} />
                      {modelLabel}
                    </span>
                  )}
                </div>
                {sending ? (
                  <button type="button" className="ai-stop-stream-button" onClick={onStopAIMessage}>
                    <X size={16} />
                    {streamStopping ? zhCN.ai.stoppingStreaming : zhCN.ai.stopStreaming}
                  </button>
                ) : (
                  <button type="button" className="primary-action" onClick={onSendAIMessage} disabled={draft.trim() === ''}>
                    <SendHorizontal size={16} />
                    {zhCN.ai.send}
                  </button>
                )}
              </div>
            </div>
          </div>
        </section>
        {capabilitiesOpen && (
          <button
            type="button"
            className="ai-capability-backdrop"
            onClick={() => setCapabilitiesOpen(false)}
            aria-label={zhCN.ai.closeCapabilityDrawer}
          />
        )}
        <aside id="ai-capability-drawer" className="ai-side-panel" aria-hidden={!capabilitiesOpen}>
          <div className="ai-capability-drawer-header">
            <div>
              <BrainCircuit size={15} />
              <strong>{zhCN.ai.capabilityDrawer}</strong>
            </div>
            <button type="button" onClick={() => setCapabilitiesOpen(false)} aria-label={zhCN.ai.closeCapabilityDrawer} title={zhCN.ai.closeCapabilityDrawer}>
              <X size={15} />
            </button>
          </div>
          <AIActionPanel
            actions={actions}
            agentProfiles={agentState.profiles}
            status={actionStatus}
            inputs={actionInputs}
            result={actionResult}
            runningActionId={actionRunningId}
            onInputChange={onActionInputChange}
            onInputsChange={onActionInputsChange}
            onRunAction={onRunAction}
            onRefreshActions={onRefreshActions}
            onOpenReportActionFile={onOpenReportActionFile}
            onOpenContextReference={onOpenContextReference}
            onRunFollowupAction={onRunFollowupAction}
            plannerState={plannerState}
          />
          <AIActionTracePanel
            items={displayedActionTrace}
            onOpenReference={onOpenContextReference}
            onRunFollowupAction={onRunFollowupAction}
            actionRunningId={actionRunningId}
          />
          <AIFileChangeSetPanel
            changes={fileChanges}
            selectedChangeKey={selectedAIFileChangeKey}
            selectedDiffChange={selectedDiffChange}
            onSelectDiff={setSelectedAIFileChangeKey}
            onOpenFile={onOpenReportActionFile}
          />
          <AIFrontierQueuePanel
            queue={frontierQueue}
            query={frontierQueueQuery}
            status={frontierQueueStatus}
            busy={frontierQueueBusy}
            onQueryChange={onFrontierQueueQueryChange}
            onRefresh={onRefreshFrontierQueue}
            onRunAction={onRunFrontierQueueAction}
            onOpenFile={onOpenReportActionFile}
            onOpenReference={onOpenContextReference}
          />
          <AIFailureStrategyPanel
            executions={executions}
            draft={failureStrategyDraft}
            status={failureStrategyStatus}
            busy={failureStrategyBusy}
            actionResult={actionResult}
            promptRegistry={promptRegistry}
            frontierQueue={frontierQueue}
            blackboard={blackboard}
            agentState={agentState}
            onDraftChange={onFailureStrategyDraftChange}
            onRunFailureStrategySisyphus={onRunFailureStrategySisyphus}
            onRunFailureStrategyFollowup={onRunFailureStrategyFollowup}
            onOpenFile={onOpenReportActionFile}
            onOpenReference={onOpenContextReference}
          />
          <AIStrategyStatePanel
            blackboard={blackboard}
            agentState={agentState}
            frontierQueue={frontierQueue}
            frontierQueueQuery={frontierQueueQuery}
            status={strategySelectionStatus}
            busy={strategySelectionBusy}
            onRunStrategySelection={onRunStrategySelection}
            onOpenReference={onOpenContextReference}
          />
          <AICollaborationTopologyPanel
            blackboard={blackboard}
            agentState={agentState}
            frontierQueue={frontierQueue}
            frontierQueueQuery={frontierQueueQuery}
            conversation={conversation}
            frontierQueueBusy={frontierQueueBusy}
            strategySelectionBusy={strategySelectionBusy}
            actionRunningId={actionRunningId}
            onRefreshFrontierQueue={onRefreshFrontierQueue}
            onRunStrategySelection={onRunStrategySelection}
            onRunFrontierQueueAction={onRunFrontierQueueAction}
            onRunFollowupAction={onRunFollowupAction}
            onOpenReference={onOpenContextReference}
          />
          <AIFrontierDependenciesPanel
            dependencies={frontierDependencies}
            status={frontierDependenciesStatus}
            busy={frontierDependenciesBusy}
            onRefresh={onRefreshFrontierDependencies}
            onRunDependency={onRunFrontierDependency}
            onOpenReference={onOpenContextReference}
          />
          <AIFrontierMonitorPanel
            monitor={frontierMonitor}
            status={frontierMonitorStatus}
            busy={frontierMonitorBusy}
            onRefresh={onRefreshFrontierMonitor}
            onOpenFile={onOpenReportActionFile}
            onOpenReference={onOpenContextReference}
          />
          <AICollaborationDispatchPanel
            draft={collaborationDraft}
            profiles={agentState.profiles}
            status={collaborationStatus}
            busy={collaborationBusy}
            lastBlackboard={collaborationLastBlackboard}
            lastTask={collaborationLastTask}
            onDraftChange={onCollaborationDraftChange}
            onCreateBlackboard={onCreateCollaborationBlackboard}
            onCreateAgentTask={onCreateCollaborationAgentTask}
            blackboardUpdateBusy={blackboardUpdateBusy}
            onUpdateBlackboardItem={onUpdateBlackboardItem}
            onOpenReference={onOpenContextReference}
          />
          <AICollaborationContextPanel
            blackboard={blackboard}
            agentState={agentState}
            orchestratorState={orchestratorState}
            plannerState={plannerState}
            updateBusy={blackboardUpdateBusy}
            updateStatus={blackboardUpdateStatus}
            onUpdateBlackboardItem={onUpdateBlackboardItem}
            onOpenReference={onOpenContextReference}
          />
          <AIAgentTaskQueuePanel
            agentState={agentState}
            onRefresh={onRefreshCollaboration}
            onOpenReference={onOpenContextReference}
            lifecycleBusy={agentTaskLifecycleBusy}
            lifecycleStatus={agentTaskLifecycleStatus}
            onUpdateLifecycle={onUpdateAgentTaskLifecycle}
            eventBusy={agentTaskEventBusy}
            eventStatus={agentTaskEventStatus}
            onCreateEvent={onCreateAgentTaskEvent}
            onOpenFile={onOpenAgentTaskFile}
          />
          <AIAgentTaskEventsOverviewPanel
            agentState={agentState}
            onOpenReference={onOpenContextReference}
          />
          <AIStreamEventsPanel
            events={streamEvents}
            sending={sending}
            onOpenReportActionFile={onOpenReportActionFile}
            onOpenContextReference={onOpenContextReference}
            onRunFollowupAction={onRunFollowupAction}
            actionRunningId={actionRunningId}
          />
          <AIRuntimeMonitorPanel runtime={conversation?.runtime} sending={sending} />
          <AIConversationSessionsPanel
            sessions={sessions}
            status={sessionStatus}
            busyId={sessionBusyId}
            searchQuery={sessionSearchQuery}
            searchResults={sessionSearchResults}
            searchStatus={sessionSearchStatus}
            searchBusy={sessionSearchBusy}
            exportBusyId={sessionExportBusyId}
            exportResult={sessionExportResult}
            exportPath={sessionExportPath}
            onRefresh={onRefreshSessions}
            onStartNew={onStartNewSession}
            onRestore={onRestoreSession}
            onSearchQueryChange={onSessionSearchQueryChange}
            onSearch={onSearchSessions}
            onExport={onExportSession}
            onOpenExportPath={onOpenSessionExportPath}
          />
          <AIHistoryPanel
            items={historyRuns}
            selectedRunId={selectedHistoryRunId}
            sending={sending}
            onSelectRun={setSelectedHistoryRunId}
            onClearSelection={() => setSelectedHistoryRunId(null)}
          />
          <section className="ai-meta-panel">
            <PanelTitle icon={Activity} title={zhCN.ai.metadata} meta={providerReady ? zhCN.ai.providerConfigured : zhCN.ai.providerMissing} />
            {!providerReady && (
              <div className="ai-provider-warning">
                <AlertCircle size={15} />
                <span>{zhCN.ai.providerMissing}</span>
              </div>
            )}
            <DetailGrid rows={[
              [zhCN.ai.provider, conversation?.provider],
              [zhCN.ai.model, conversation?.model],
              [zhCN.ai.updatedAt, formatAIInstant(conversation?.updatedAt)],
              [zhCN.ai.promptTokens, usage?.promptTokens],
              [zhCN.ai.completionTokens, usage?.completionTokens],
              [zhCN.ai.totalTokens, usage?.totalTokens],
            ]} />
            <AIProviderRoutingPanel routing={routing} provider={conversation?.provider} model={conversation?.model} usage={usage} />
          </section>
          <AIContextList references={conversation?.contextReferences ?? []} onOpenReference={onOpenContextReference} />
        </aside>
      </div>
    </section>
  );
}

type AICollaborationTarget = {
  reference: AIContextReference;
  status?: string;
  meta?: string;
  updatedAt?: number;
  blackboardItem?: BlackboardItem;
};

function AICollaborationDispatchPanel({
  draft,
  profiles,
  status,
  busy,
  lastBlackboard,
  lastTask,
  onDraftChange,
  onCreateBlackboard,
  onCreateAgentTask,
  blackboardUpdateBusy,
  onUpdateBlackboardItem,
  onOpenReference,
}: {
  draft: AICollaborationDispatchDraft;
  profiles: AgentProfile[];
  status: string;
  busy: 'blackboard' | 'agent' | '';
  lastBlackboard: BlackboardItem | null;
  lastTask: AgentTask | null;
  onDraftChange: (patch: Partial<AICollaborationDispatchDraft>) => void;
  onCreateBlackboard: () => void;
  onCreateAgentTask: () => void;
  blackboardUpdateBusy: BlackboardUpdateBusy | null;
  onUpdateBlackboardItem: (item: BlackboardItem, request: BlackboardItemUpdateRequest) => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const goalMissing = draft.blackboardContent.trim() === '' && draft.taskGoal.trim() === '';
  const disabled = busy !== '';
  const openBlackboardReference = (item: BlackboardItem) => onOpenReference({
    id: item.id,
    kind: 'blackboard',
    label: item.title,
    title: item.title,
    path: item.filePath,
    source: zhCN.ai.collaborationDispatch,
  });
  const openAgentTaskReference = (task: AgentTask) => onOpenReference({
    id: task.id,
    kind: 'agentTask',
    label: task.title,
    title: task.title,
    path: task.filePath,
    source: zhCN.ai.collaborationDispatch,
  });
  return (
    <section className="ai-collaboration-dispatch-panel ai-collaboration-dispatch" data-ai-collaboration-dispatch="true">
      <PanelTitle icon={GitBranch} title={zhCN.ai.collaborationDispatch} meta={zhCN.ai.collaborationDispatchMeta} />
      <div className="ai-collaboration-dispatch-form">
        <label className="ai-collaboration-dispatch-goal">
          <span>{zhCN.ai.collaborationDispatchGoalLabel}</span>
          <textarea
            name="blackboard-content"
            data-ai-collaboration-dispatch-field="blackboard-content"
            value={draft.blackboardContent}
            onChange={event => onDraftChange({ blackboardContent: event.target.value })}
            placeholder={zhCN.ai.collaborationDispatchGoalPlaceholder}
            aria-label={zhCN.ai.collaborationDispatchGoalLabel}
          />
        </label>
        <div className="ai-collaboration-dispatch-fields">
          <label>
            <span>{zhCN.aiActions.blackboardTitleInput}</span>
            <input
              name="blackboard-title"
              data-ai-collaboration-dispatch-field="blackboard-title"
              value={draft.blackboardTitle}
              onChange={event => onDraftChange({ blackboardTitle: event.target.value })}
              placeholder={zhCN.aiActions.blackboardTitlePlaceholder}
              aria-label={zhCN.aiActions.blackboardTitleInput}
            />
          </label>
          <label>
            <span>{zhCN.aiActions.blackboardSourceInput}</span>
            <input
              name="blackboard-source"
              data-ai-collaboration-dispatch-field="blackboard-source"
              value={draft.blackboardSource}
              onChange={event => onDraftChange({ blackboardSource: event.target.value })}
              placeholder={zhCN.aiActions.blackboardSourcePlaceholder}
              aria-label={zhCN.aiActions.blackboardSourceInput}
            />
          </label>
          <label>
            <span>{zhCN.aiActions.agentTitleInput}</span>
            <input
              name="task-title"
              data-ai-collaboration-dispatch-field="task-title"
              value={draft.taskTitle}
              onChange={event => onDraftChange({ taskTitle: event.target.value })}
              placeholder={zhCN.aiActions.agentTitlePlaceholder}
              aria-label={zhCN.aiActions.agentTitleInput}
            />
          </label>
          <label className="ai-collaboration-dispatch-wide">
            <span>{zhCN.aiActions.agentGoalInput}</span>
            <textarea
              name="task-goal"
              data-ai-collaboration-dispatch-field="task-goal"
              value={draft.taskGoal}
              onChange={event => onDraftChange({ taskGoal: event.target.value })}
              placeholder={zhCN.aiActions.agentGoalPlaceholder}
              aria-label={zhCN.aiActions.agentGoalInput}
            />
          </label>
          <label>
            <span>{zhCN.agents.selectProfile}</span>
            <select
              name="task-agent-id"
              data-ai-collaboration-dispatch-field="task-agent-id"
              value={draft.taskAgentId}
              onChange={event => {
                const taskAgentId = event.target.value;
                const selectedProfile = profiles.find(profile => profile.id === taskAgentId);
                onDraftChange({ taskAgentId, taskRole: selectedProfile?.role ?? draft.taskRole });
              }}
              aria-label={zhCN.agents.selectProfile}
            >
              <option value="">{zhCN.agents.noProfileSelected}</option>
              {profiles.map(profile => (
                <option key={profile.id} value={profile.id}>{profile.name} · {profile.role}</option>
              ))}
            </select>
          </label>
          <label>
            <span>{zhCN.aiActions.agentRoleInput}</span>
            <input
              name="task-role"
              data-ai-collaboration-dispatch-field="task-role"
              value={draft.taskRole}
              onChange={event => onDraftChange({ taskRole: event.target.value })}
              placeholder={zhCN.aiActions.agentRolePlaceholder}
              aria-label={zhCN.aiActions.agentRoleInput}
            />
          </label>
          <label>
            <span>{zhCN.aiActions.agentPriorityInput}</span>
            <input
              name="task-priority"
              data-ai-collaboration-dispatch-field="task-priority"
              value={draft.taskPriority}
              onChange={event => onDraftChange({ taskPriority: event.target.value })}
              placeholder={zhCN.aiActions.agentPriorityPlaceholder}
              aria-label={zhCN.aiActions.agentPriorityInput}
            />
          </label>
          <label>
            <span>{zhCN.aiActions.agentSourceInput}</span>
            <input
              name="task-source"
              data-ai-collaboration-dispatch-field="task-source"
              value={draft.taskSource}
              onChange={event => onDraftChange({ taskSource: event.target.value })}
              placeholder={zhCN.aiActions.agentSourcePlaceholder}
              aria-label={zhCN.aiActions.agentSourceInput}
            />
          </label>
          <label className="ai-collaboration-dispatch-wide">
            <span>{zhCN.aiActions.agentBlackboardInput}</span>
            <input
              name="blackboardItemId"
              data-ai-collaboration-dispatch-field="blackboardItemId"
              value={draft.blackboardItemId}
              onChange={event => onDraftChange({ blackboardItemId: event.target.value })}
              placeholder={zhCN.aiActions.agentBlackboardPlaceholder}
              aria-label={zhCN.aiActions.agentBlackboardInput}
            />
          </label>
          <label className="ai-collaboration-dispatch-wide">
            <span>{zhCN.aiActions.agentFilePathInput}</span>
            <input
              name="task-file-path"
              data-ai-collaboration-dispatch-field="task-file-path"
              value={draft.filePath}
              onChange={event => onDraftChange({ filePath: event.target.value })}
              placeholder={zhCN.aiActions.agentFilePathPlaceholder}
              aria-label={zhCN.aiActions.agentFilePathInput}
            />
          </label>
        </div>
        <div className="ai-collaboration-dispatch-actions">
          <span className="ai-collaboration-dispatch-queue-label">{zhCN.ai.agentTaskQueue}</span>
          <button
            type="button"
            data-smoke-action="create-blackboard"
            data-collaboration-dispatch-action="create-blackboard"
            onClick={onCreateBlackboard}
            disabled={disabled || goalMissing}
          >
            <ClipboardList size={14} />
            {busy === 'blackboard' ? zhCN.ai.collaborationDispatchCreatingBlackboard : zhCN.ai.collaborationDispatchCreateBlackboard}
          </button>
          <button
            type="button"
            className="primary-action"
            data-smoke-action="create-agent-task"
            data-collaboration-dispatch-action="create-agent-task"
            onClick={onCreateAgentTask}
            disabled={disabled || goalMissing}
          >
            <UsersRound size={14} />
            {busy === 'agent' ? zhCN.ai.collaborationDispatchCreatingAgentTask : zhCN.ai.collaborationDispatchCreateAgentTask}
          </button>
        </div>
        {(status || goalMissing) && (
          <div className="ai-collaboration-dispatch-status">
            <AlertCircle size={14} />
            <span>{status || zhCN.ai.collaborationDispatchGoalRequired}</span>
          </div>
        )}
        {(lastBlackboard || lastTask) && (
          <div className="ai-collaboration-dispatch-result">
            {lastBlackboard && (
              <article>
                <div className="ai-collaboration-dispatch-result-head">
                  <strong>{zhCN.ai.collaborationDispatchBlackboardCreated}</strong>
                  <button type="button" onClick={() => openBlackboardReference(lastBlackboard)}>
                    <ChevronRight size={14} />
                    {zhCN.ai.jumpToReference}
                  </button>
                </div>
                <p>{lastBlackboard.title}</p>
                <DetailGrid rows={[
                  [zhCN.blackboard.id, lastBlackboard.id],
                  [zhCN.blackboard.updateStatusLine, blackboardStatusLabel(lastBlackboard.status)],
                  [zhCN.blackboard.kind, blackboardKindLabel(lastBlackboard.kind)],
                  [zhCN.blackboard.priority, blackboardPriorityLabel(lastBlackboard.priority)],
                  [zhCN.blackboard.source, lastBlackboard.source],
                ]} />
                <BlackboardItemUpdateControls
                  item={lastBlackboard}
                  busy={blackboardUpdateBusy}
                  onUpdate={onUpdateBlackboardItem}
                />
              </article>
            )}
            {lastTask && (
              <article>
                <div className="ai-collaboration-dispatch-result-head">
                  <strong>{zhCN.ai.collaborationDispatchAgentTaskCreated}</strong>
                  <button type="button" onClick={() => openAgentTaskReference(lastTask)}>
                    <ChevronRight size={14} />
                    {zhCN.ai.jumpToReference}
                  </button>
                </div>
                <p>{lastTask.title}</p>
                <DetailGrid rows={[
                  [zhCN.agents.id, lastTask.id],
                  [zhCN.agents.status, agentStatusLabel(lastTask.status)],
                  [zhCN.agents.role, lastTask.role],
                  [zhCN.agents.blackboardItemId, lastTask.blackboardItemId],
                ]} />
              </article>
            )}
          </div>
        )}
      </div>
    </section>
  );
}

function AIAgentTaskQueuePanel({
  agentState,
  onRefresh,
  onOpenReference,
  lifecycleBusy,
  lifecycleStatus,
  onUpdateLifecycle,
  eventBusy,
  eventStatus,
  onCreateEvent,
  onOpenFile,
}: {
  agentState: AgentState;
  onRefresh: () => void;
  onOpenReference: (reference: AIContextReference) => void;
  lifecycleBusy: AgentTaskLifecycleBusy | null;
  lifecycleStatus: string;
  onUpdateLifecycle: (task: AgentTask, status: AgentTaskLifecycleStatus) => void;
  eventBusy: AgentTaskEventBusy | null;
  eventStatus: string;
  onCreateEvent: (task: AgentTask, action: AgentTaskEventAction, input: AgentTaskEventSubmitInput) => void;
  onOpenFile: (filePath: string) => void;
}) {
  const latestTasks = [...agentState.tasks]
    .sort((left, right) => (right.updatedAt || right.createdAt) - (left.updatedAt || left.createdAt))
    .slice(0, 6);
  return (
    <section className="ai-agent-task-queue-panel" data-ai-agent-task-queue="true">
      <PanelTitle icon={UsersRound} title={zhCN.ai.agentTaskQueue} meta={agentState.path || zhCN.ai.agentTaskQueueMeta} />
      <div className="ai-agent-task-queue-toolbar">
        <DetailGrid rows={[
          [zhCN.agents.total, agentState.tasks.length],
          [zhCN.agents.queued, agentState.counts.queued],
          [zhCN.agents.inProgress, agentState.counts.inProgress],
          [zhCN.agents.completed, agentState.counts.completed],
          [zhCN.agents.failed, agentState.counts.failed],
        ]} />
        <button type="button" onClick={onRefresh}>
          <RefreshCw size={14} />
          {zhCN.ai.agentTaskQueueRefresh}
        </button>
      </div>
      {lifecycleStatus && (
        <div className="ai-collaboration-dispatch-status">
          <CircleDot size={13} />
          <span>{lifecycleStatus}</span>
        </div>
      )}
      {eventStatus && (
        <div className="ai-collaboration-dispatch-status">
          <CircleDot size={13} />
          <span>{eventStatus}</span>
        </div>
      )}
      <div className="ai-agent-task-queue-list">
        {latestTasks.length === 0 && <EmptyState text={zhCN.ai.agentTaskQueueEmpty} />}
        {latestTasks.map(task => {
          const events = latestAgentTaskEvents(agentState.events, task.id, 3);
          return (
            <article
              key={task.id}
              data-agent-task-id={task.id}
              data-ai-agent-task-id={task.id}
              data-agent-task-title={task.title}
            >
              <div className="ai-agent-task-queue-head">
                <div>
                  <strong>{task.title}</strong>
                  <span>{zhCN.ai.agentTaskQueueStatus}: {agentStatusLabel(task.status)}</span>
                </div>
                <button
                  type="button"
                  onClick={() => onOpenReference({
                    id: task.id,
                    kind: 'agentTask',
                    label: task.title,
                    title: task.title,
                    path: task.filePath,
                    source: zhCN.ai.agentTaskQueue,
                  })}
                >
                  <ChevronRight size={14} />
                  {zhCN.ai.jumpToReference}
                </button>
              </div>
              <p>{task.goal}</p>
              <DetailGrid rows={[
                [zhCN.agents.id, task.id],
                [zhCN.agents.role, task.role],
                [zhCN.agents.agentId, task.agentId],
                [zhCN.agents.priority, agentPriorityLabel(task.priority)],
                [zhCN.agents.source, task.source],
                [zhCN.agents.blackboardItemId, task.blackboardItemId],
                [zhCN.agents.filePath, task.filePath],
                [zhCN.agents.updatedAt, formatDetailTime(task.updatedAt)],
              ]} />
              {task.filePath && (
                <div className="row-actions detail-actions">
                  <button type="button" onClick={() => onOpenFile(task.filePath as string)}>{zhCN.agents.openFile}</button>
                </div>
              )}
              <AgentTaskResultDetails task={task} onOpenFile={onOpenFile} />
              <AgentTaskEventList events={events} />
              <AgentTaskEventControls task={task} busy={eventBusy} onCreateEvent={onCreateEvent} />
              <AgentTaskLifecycleActions task={task} busy={lifecycleBusy} onUpdateLifecycle={onUpdateLifecycle} />
            </article>
          );
        })}
      </div>
    </section>
  );
}

function AIAgentTaskEventsOverviewPanel({
  agentState,
  onOpenReference,
}: {
  agentState: AgentState;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const latestEvents = [...agentState.events]
    .sort((left, right) => right.createdAt - left.createdAt)
    .slice(0, 8);
  const taskById = new Map(agentState.tasks.map(task => [task.id, task]));
  return (
    <section className="ai-agent-task-events-panel" data-ai-agent-task-events="true">
      <PanelTitle icon={UserCheck} title={zhCN.ai.agentTaskEvents} meta={agentState.eventPath || zhCN.ai.agentTaskEventsMeta} />
      <DetailGrid rows={[
        [zhCN.ai.agentTaskEventCreating, zhCN.ai.agentTaskClaim],
        [zhCN.ai.agentTaskEventCreated, zhCN.ai.agentTaskEventLog],
        [zhCN.ai.agentTaskEventFailed, zhCN.ai.agentTaskEventsMeta],
      ]} />
      {latestEvents.length === 0 && <EmptyState text={zhCN.ai.agentTaskEventsEmpty} />}
      {latestEvents.length > 0 && (
        <div className="ai-agent-task-events-list">
          {latestEvents.map(event => {
            const task = taskById.get(event.taskId);
            return (
              <article key={event.id} className="ai-agent-task-event-row">
                <div className="ai-agent-task-queue-head">
                  <div>
                    <strong>{event.title || agentTaskEventKindLabel(event.kind)}</strong>
                    <span>{task?.title || event.taskId}</span>
                  </div>
                  <span>{formatDetailTime(event.createdAt)}</span>
                </div>
                {event.summary && <p>{zhCN.ai.agentTaskEventSummary}: {event.summary}</p>}
                {event.detail && <p>{zhCN.ai.agentTaskEventDetail}: {event.detail}</p>}
                <DetailGrid rows={[
                  [zhCN.agents.eventKind, agentTaskEventKindLabel(event.kind)],
                  [zhCN.agents.status, event.status ? agentStatusLabel(event.status) : undefined],
                  [zhCN.agents.agentId, event.agentId],
                  [zhCN.agents.executionId, event.executionId],
                  [zhCN.agents.artifactPath, event.artifactPath],
                  [zhCN.agents.source, event.source],
                ]} />
                <div className="row-actions detail-actions">
                  <button
                    type="button"
                    onClick={() => onOpenReference({
                      id: event.taskId,
                      kind: 'agentTask',
                      label: task?.title || event.taskId,
                      title: task?.title || event.taskId,
                      path: event.filePath || task?.filePath,
                      source: zhCN.ai.agentTaskEvents,
                    })}
                  >
                    <ChevronRight size={14} />
                    {zhCN.ai.jumpToReference}
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}

function AICollaborationContextPanel({
  blackboard,
  agentState,
  orchestratorState,
  plannerState,
  updateBusy,
  updateStatus,
  onUpdateBlackboardItem,
  onOpenReference,
}: {
  blackboard: BlackboardState;
  agentState: AgentState;
  orchestratorState: OrchestratorState;
  plannerState: PlannerState;
  updateBusy: BlackboardUpdateBusy | null;
  updateStatus: string;
  onUpdateBlackboardItem: (item: BlackboardItem, request: BlackboardItemUpdateRequest) => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const safeOrchestratorState = normalizeOrchestratorState(orchestratorState);
  const latestTargets = buildAICollaborationContextEntries(blackboard, agentState, safeOrchestratorState, plannerState).slice(0, 8);
  const hasContext = hasAICollaborationContext(blackboard, agentState, safeOrchestratorState, plannerState, latestTargets);
  const openBlackboardItems = blackboard.items.filter(item => item.status === 'open' || item.status === 'inProgress' || item.status === 'in_progress').length;
  const activeAgentTasks = (agentState.counts.queued ?? 0) + (agentState.counts.inProgress ?? 0);
  const activeOrchestratorRuns = (safeOrchestratorState.counts.running ?? 0) + (safeOrchestratorState.counts.queued ?? 0);
  const activePlannerPlans = (plannerState.counts.queued ?? 0) + (plannerState.counts.running ?? 0) + (plannerState.counts.ready ?? 0);
  return (
    <section className="ai-collaboration-panel ai-collaboration-context" data-ai-collaboration-context="true">
      <PanelTitle icon={UsersRound} title={zhCN.ai.collaborationContext} meta={zhCN.ai.collaborationContextMeta} />
      {!hasContext && <EmptyState text={zhCN.ai.collaborationContextEmpty} />}
      {hasContext && (
        <>
          <DetailGrid rows={[
            [zhCN.ai.collaborationBlackboard, blackboard.items.length],
            [zhCN.ai.collaborationOpenBlackboard, openBlackboardItems],
            [zhCN.ai.collaborationAgentTasks, agentState.tasks.length],
            [zhCN.ai.collaborationActiveAgents, activeAgentTasks],
            [zhCN.ai.collaborationOrchestrator, formatAICollaborationOrchestratorSummary(safeOrchestratorState)],
            [zhCN.ai.collaborationActiveOrchestrations, activeOrchestratorRuns],
            [zhCN.ai.collaborationPlanner, plannerState.plans.length],
            [zhCN.ai.collaborationActivePlans, activePlannerPlans],
          ]} />
          <div className="ai-collaboration-paths">
            <DetailGrid rows={[
              [zhCN.ai.collaborationSourcePath, formatAICollaborationSourcePaths(blackboard, agentState, safeOrchestratorState, plannerState)],
            ]} />
          </div>
        </>
      )}
      <div className="ai-collaboration-latest">
        <strong>{zhCN.ai.collaborationLatestReferences}</strong>
        {updateStatus && (
          <div className="ai-collaboration-dispatch-status" data-blackboard-update-status="true">
            <AlertCircle size={14} />
            <span>{updateStatus}</span>
          </div>
        )}
        {latestTargets.length === 0 && <EmptyState text={zhCN.ai.collaborationReferencesEmpty} />}
        {latestTargets.map(target => (
          <article
            key={`${target.reference.kind}:${target.reference.id}:${target.reference.path ?? ''}`}
            data-blackboard-item-id={target.blackboardItem?.id}
          >
            <div className="ai-collaboration-head">
              <span>{aiReferenceKindLabel(target.reference.kind)}</span>
              <button type="button" onClick={() => onOpenReference(target.reference)}>
                <ChevronRight size={14} />
                {zhCN.ai.jumpToReference}
              </button>
            </div>
            <strong>{target.reference.label}</strong>
            <DetailGrid rows={[
              [zhCN.ai.referenceId, traceDisplayValue(target.reference.id, backendValueNotProvided)],
              [zhCN.ai.collaborationItemStatus, formatAICollaborationStatus(target.reference.kind, target.status)],
              [zhCN.ai.collaborationItemMeta, target.meta],
              [zhCN.ai.collaborationUpdatedAt, target.updatedAt ? formatDetailTime(target.updatedAt) : undefined],
            ]} />
            {target.blackboardItem && (
              <BlackboardItemUpdateControls
                item={target.blackboardItem}
                busy={updateBusy}
                onUpdate={onUpdateBlackboardItem}
              />
            )}
          </article>
        ))}
      </div>
    </section>
  );
}

function hasAICollaborationContext(
  blackboard: BlackboardState,
  agentState: AgentState,
  orchestratorState: OrchestratorState,
  plannerState: PlannerState,
  entries: AICollaborationTarget[],
): boolean {
  return Boolean(
    entries.length > 0
      || blackboard.path
      || agentState.path
      || orchestratorState.path
      || orchestratorState.observationPath
      || orchestratorState.advancePath
      || plannerState.path
      || Object.keys(agentState.counts).length > 0
      || Object.keys(orchestratorState.counts).length > 0
      || Object.keys(plannerState.counts).length > 0,
  );
}

function normalizeOrchestratorState(orchestratorState: OrchestratorState | undefined | null): OrchestratorState {
  return {
    path: orchestratorState?.path ?? '',
    observationPath: orchestratorState?.observationPath ?? '',
    advancePath: orchestratorState?.advancePath ?? '',
    runs: Array.isArray(orchestratorState?.runs) ? orchestratorState.runs : [],
    observations: Array.isArray(orchestratorState?.observations) ? orchestratorState.observations : [],
    advances: Array.isArray(orchestratorState?.advances) ? orchestratorState.advances : [],
    counts: orchestratorState?.counts ?? {},
  };
}

function formatAICollaborationOrchestratorSummary(orchestratorState: OrchestratorState): string {
  return `${orchestratorState.runs.length} ${zhCN.ai.collaborationOrchestratorRuns} · ${orchestratorState.observations.length} ${zhCN.ai.collaborationOrchestratorObservations} · ${orchestratorState.advances.length} ${zhCN.ai.collaborationOrchestratorAdvances}`;
}

function formatAICollaborationSourcePaths(
  blackboard: BlackboardState,
  agentState: AgentState,
  orchestratorState: OrchestratorState,
  plannerState: PlannerState,
): string | undefined {
  const paths = [
    blackboard.path,
    agentState.path,
    orchestratorState.path,
    orchestratorState.observationPath,
    orchestratorState.advancePath,
    plannerState.path,
  ].filter(path => path.trim() !== '');
  return paths.length > 0 ? paths.join(' · ') : undefined;
}

function buildAICollaborationContextEntries(
  blackboard: BlackboardState,
  agentState: AgentState,
  orchestratorState: OrchestratorState,
  plannerState: PlannerState,
): AICollaborationTarget[] {
  const blackboardTargets = blackboard.items.map(item => ({
    reference: {
      id: item.id,
      label: item.title,
      kind: 'blackboard',
      title: item.title,
      path: item.filePath,
      source: zhCN.blackboard.title,
    },
    status: item.status,
    meta: [blackboardKindLabel(item.kind), blackboardPriorityLabel(item.priority), blackboardRelationMeta(item)].filter(Boolean).join(' · '),
    updatedAt: item.updatedAt || item.createdAt,
    blackboardItem: item,
  }));
  const agentTargets = agentState.tasks.map(task => ({
    reference: {
      id: task.id,
      label: task.title,
      kind: 'agentTask',
      title: task.title,
      path: task.filePath,
      source: zhCN.agents.title,
    },
    status: task.status,
    meta: [task.role, agentPriorityLabel(task.priority)].filter(Boolean).join(' · '),
    updatedAt: task.updatedAt || task.createdAt,
  }));
  const orchestratorRunTargets = orchestratorState.runs.map(run => ({
    reference: {
      id: run.id,
      label: run.title,
      kind: 'orchestratorRun',
      title: run.title,
      path: run.filePath,
      source: zhCN.aiActions.orchestratorRunResult,
    },
    status: run.status,
    meta: [run.strategy, run.executionId].filter(Boolean).join(' · '),
    updatedAt: run.updatedAt || run.createdAt,
  }));
  const orchestratorObservationTargets = orchestratorState.observations.map(observation => ({
    reference: {
      id: observation.id,
      label: observation.summary || observation.executionId || observation.id,
      kind: 'orchestratorObservation',
      title: observation.summary,
      path: observation.logPath,
      source: zhCN.aiActions.orchestratorObservationResult,
    },
    status: observation.status,
    meta: [observation.runId, observation.executionId].filter(Boolean).join(' · '),
    updatedAt: observation.updatedAt || observation.createdAt,
  }));
  const orchestratorAdvanceTargets = orchestratorState.advances.map(advance => ({
    reference: {
      id: advance.id,
      label: advance.title,
      kind: 'orchestratorAdvance',
      title: advance.title,
      path: advance.filePath,
      source: zhCN.aiActions.orchestratorAdvanceResult,
    },
    status: advance.status,
    meta: [advance.runId, advance.executionId].filter(Boolean).join(' · '),
    updatedAt: advance.updatedAt || advance.createdAt,
  }));
  const plannerTargets = plannerState.plans.map(plan => ({
    reference: {
      id: plan.id,
      label: plan.title,
      kind: 'plannerPlan',
      title: plan.title,
      path: plan.filePath,
      source: zhCN.aiActions.plannerPlanResult,
    },
    status: plan.status,
    meta: [plan.nextActionTitle, plan.executionId].filter(Boolean).join(' · '),
    updatedAt: plan.updatedAt || plan.observedAt || plan.executedAt || plan.createdAt,
  }));
  return [
    ...blackboardTargets,
    ...agentTargets,
    ...orchestratorRunTargets,
    ...orchestratorObservationTargets,
    ...orchestratorAdvanceTargets,
    ...plannerTargets,
  ].sort((left, right) => (right.updatedAt ?? 0) - (left.updatedAt ?? 0));
}

function formatAICollaborationStatus(kind?: string, status?: string): string | undefined {
  if (!status) {
    return undefined;
  }
  if (kind === 'blackboard') {
    return blackboardStatusLabel(status);
  }
  if (kind === 'agentTask' || kind === 'agent') {
    return agentStatusLabel(status);
  }
  const runtimeLabel = aiRuntimeStatusLabel(status);
  return runtimeLabel || localizedStatusLabel(status);
}

function blackboardRelationMeta(item: Pick<BlackboardItem, 'dependencyIds' | 'dependentIds'>): string {
  const dependencyCount = (item.dependencyIds ?? []).filter(Boolean).length;
  const dependentCount = (item.dependentIds ?? []).filter(Boolean).length;
  return [
    dependencyCount > 0 ? `${dependencyCount} ${zhCN.blackboard.dependencies}` : '',
    dependentCount > 0 ? `${dependentCount} ${zhCN.blackboard.dependents}` : '',
  ].filter(Boolean).join(' · ');
}

function AIStreamEventsPanel({ events, sending, onOpenReportActionFile, onOpenContextReference, onRunFollowupAction, actionRunningId }: {
  events: AIChatStreamEvent[];
  sending: boolean;
  onOpenReportActionFile: (filePath: string) => void;
  onOpenContextReference: (reference: AIContextReference) => void;
  onRunFollowupAction: AIActionFollowupRunner;
  actionRunningId: string;
}) {
  const meta = sending ? zhCN.ai.streamEventsAccumulating : `${zhCN.ai.streamEventsMeta} · ${events.length}`;
  const settlingHarness = actionRunningId === 'harness.cases.from_ai_conversation';
  return (
    <section className="ai-stream-panel">
      <PanelTitle icon={Activity} title={zhCN.ai.streamEvents} meta={meta} />
      {events.length === 0 && <EmptyState text={zhCN.ai.streamEventsEmpty} />}
      {events.length > 0 && (
        <div className="ai-stream-event-list">
          {events.map((event, index) => {
            const phase = aiRuntimePhaseLabel(event.phase ?? event.runtime?.phase);
            const status = aiRuntimeStatusLabel(event.status ?? event.runtime?.status);
            const nativeToolStatusValue = event.status ?? event.runtime?.lastActionStatus ?? event.runtime?.status;
            const nativeToolStatus = aiActionTraceStatusLabel(nativeToolStatusValue);
            const nativeToolRows = ([
              [zhCN.ai.providerToolName, event.toolName],
              [zhCN.ai.mappedAction, formatAINativeToolMappedAction(event)],
              [zhCN.ai.streamEventToolCallId, event.toolCallId],
            ] satisfies Array<[string, string | undefined]>).filter(([, value]) => Boolean(value));
            const providerModel = [event.provider ?? event.runtime?.provider, event.model ?? event.runtime?.model].filter(Boolean).join(' · ') || undefined;
            const message = visibleAIText(event.message) ?? '';
            const textDelta = visibleAIText(event.textDelta ?? event.contentDelta ?? event.delta);
            const eventMessageId = event.actionResult?.message.id;
            const eventActionTraceId = event.actionResult?.conversation.actionTrace.find(item => item.messageId === eventMessageId)?.id;
            const eventHarnessInput = buildAIConversationHarnessFollowupInput({
              aiMessageIds: [eventMessageId],
              toolCallIds: [event.toolCallId],
              actionTraceIds: [eventActionTraceId],
              source: 'desktop.ai.stream_event',
            });
            const canSettleEvent = Boolean(!event.actionResult && (event.toolCallId || event.actionId));
            const rows = ([
              [zhCN.ai.streamEventPhase, phase],
              [zhCN.ai.streamEventMessage, message],
              [zhCN.ai.streamEventTextDelta, textDelta],
              [zhCN.ai.streamEventTokenIndex, event.tokenIndex],
              [zhCN.ai.streamEventToolCallId, event.toolCallId],
              [zhCN.ai.providerToolName, event.toolName],
              [zhCN.ai.streamEventActionId, event.actionId ?? event.runtime?.lastActionId],
              [zhCN.ai.streamEventActionKind, aiStreamActionKindLabel(event.actionKind ?? event.runtime?.lastActionKind)],
              [zhCN.ai.streamEventActionLabel, event.actionLabel],
              [zhCN.ai.streamEventBatch, formatAIStreamBatch(event)],
              [zhCN.ai.streamEventElapsed, formatAIElapsedMs(event.elapsedMs)],
              [zhCN.ai.streamEventResultKind, aiStreamResultKindLabel(event.resultKind)],
              [zhCN.ai.streamEventResultSummary, visibleAIText(event.resultSummary)],
              [zhCN.ai.streamEventReferenceCount, event.referenceCount ?? event.contextReferences?.length],
              [zhCN.ai.streamEventProviderModel, providerModel],
              [zhCN.ai.streamEventIndex, event.index],
              [zhCN.ai.streamEventRuntime, formatAIStreamRuntime(event.runtime)],
            ] satisfies Array<[string, string | number | undefined]>).filter(([, value]) => value !== undefined && String(value).trim() !== '');
            return (
              <article className="ai-stream-event-row" key={`${event.event}-${event.toolCallId ?? event.index ?? index}-${event.actionId ?? ''}-${event.message ?? ''}`}>
                <div className="ai-stream-event-head">
                  <span className="ai-stream-event-index">{formatAIStreamEventIndex(event, index)}</span>
                  <strong>{aiStreamEventTypeLabel(event.event)}</strong>
                  {(event.status || event.runtime?.status) && (
                    <span className="ai-action-trace-status" data-status={aiActionTraceStatusTone(event.status ?? event.runtime?.status)}>
                      {status}
                    </span>
                  )}
                </div>
                {event.nativeToolCall && (
                  <div
                    className="ai-native-tool-call"
                    data-native-tool-call="true"
                    data-status={aiActionTraceStatusTone(nativeToolStatusValue)}
                    aria-label={zhCN.ai.nativeToolCall}
                  >
                    <div className="ai-action-trace-head">
                      <Wrench size={13} aria-hidden="true" />
                      <strong>{zhCN.ai.nativeToolCall}</strong>
                      <span className="ai-action-trace-status" data-status={aiActionTraceStatusTone(nativeToolStatusValue)}>
                        {nativeToolStatus}
                      </span>
                    </div>
                    {nativeToolRows.length > 0 && (
                      <dl className="ai-stream-event-meta">
                        {nativeToolRows.map(([label, value]) => (
                          <div key={`${label}-${value}`}>
                            <dt>{label}</dt>
                            <dd>{value}</dd>
                          </div>
                        ))}
                      </dl>
                    )}
                  </div>
                )}
                {rows.length > 0 && (
                  <dl className="ai-stream-event-meta">
                    {rows.map(([label, value]) => (
                      <div key={`${label}-${String(value)}`}>
                        <dt>{label}</dt>
                        <dd>{value}</dd>
                      </div>
                    ))}
                  </dl>
                )}
                {canSettleEvent && (
                  <div className="row-actions detail-actions">
                    <button
                      type="button"
                      onClick={() => onRunFollowupAction('harness.cases.from_ai_conversation', eventHarnessInput)}
                      disabled={settlingHarness}
                    >
                      {settlingHarness ? zhCN.ai.settleAsHarnessRunning : zhCN.ai.settleAsHarness}
                    </button>
                  </div>
                )}
                {event.actionResult && (
                  <section className="ai-action-result ai-stream-event-action-result" data-ai-stream-event-action-result="true">
                    <strong>{zhCN.aiActions.result}</strong>
                    {renderAIActionResult(event.actionResult, onOpenReportActionFile, onOpenContextReference, onRunFollowupAction, actionRunningId, eventHarnessInput)}
                  </section>
                )}
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}

function AIHistoryPanel({
  items,
  selectedRunId,
  sending,
  onSelectRun,
  onClearSelection,
}: {
  items: AIConversationRunSummary[];
  selectedRunId: string | null;
  sending: boolean;
  onSelectRun: (runId: string) => void;
  onClearSelection: () => void;
}) {
  return (
    <section className="ai-history-panel">
      <PanelTitle icon={Clock3} title={zhCN.ai.history} meta={`${zhCN.ai.historyMeta} · ${items.length} ${zhCN.ai.runHistoryCount}`} />
      {selectedRunId && (
        <div className="ai-history-toolbar">
          <span>{zhCN.ai.historyFocused}</span>
          <button type="button" onClick={onClearSelection}>
            <X size={14} />
            {zhCN.ai.historyShowAll}
          </button>
        </div>
      )}
      {items.length === 0 && <EmptyState text={zhCN.ai.historyEmpty} />}
      {items.length > 0 && (
        <div className="ai-history-list">
          {items.map((item, visibleIndex) => {
            const active = sending && visibleIndex === 0;
            const statusLabel = active ? zhCN.ai.runtimeRequesting : aiRuntimeStatusLabel(item.status);
            const statusTone = active ? 'running' : aiActionTraceStatusTone(item.status);
            const providerModel = historyRunProviderModel(item);
            const selected = selectedRunId === item.id;
            return (
              <button
                type="button"
                className="ai-history-row"
                data-selected={selected ? 'true' : 'false'}
                key={item.id}
                onClick={() => onSelectRun(item.id)}
              >
                <span className="ai-history-head">
                  <span className="ai-action-trace-index">#{item.index}</span>
                  <strong>{item.title}</strong>
                  <span className="ai-action-trace-status" data-status={statusTone}>
                    {statusLabel ?? zhCN.ai.runtimeStatuses.unknown}
                  </span>
                </span>
                <span className="ai-history-goal">{item.latestSummary || zhCN.ai.runHistoryNoSummary}</span>
                <span className="ai-history-meta">
                  <span>
                    <span>{zhCN.ai.historyLatestGoal}</span>
                    <span>{item.title}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.runHistoryStartedAt}</span>
                    <span>{traceDisplayValue(formatAIInstant(item.startedAt))}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.historyUpdatedAt}</span>
                    <span>{traceDisplayValue(formatAIInstant(item.updatedAt))}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.runHistoryMessages}</span>
                    <span>{formatNumber(item.messageCount)}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.historyActionCount}</span>
                    <span>{formatNumber(item.actionCount)}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.runHistoryToolResults}</span>
                    <span>{formatNumber(item.toolResultCount)}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.runHistoryProviderCalls}</span>
                    <span>{formatNumber(item.providerCallCount)}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.runHistoryProviderModel}</span>
                    <span>{traceDisplayValue(providerModel)}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.runHistoryTokens}</span>
                    <span>{item.totalTokens !== undefined ? formatNumber(item.totalTokens) : zhCN.ai.actionTraceValueMissing}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.runHistoryCost}</span>
                    <span>{formatCostUSD(item.costUsd) || zhCN.ai.actionTraceValueMissing}</span>
                  </span>
                  <span>
                    <span>{zhCN.ai.runHistoryReferences}</span>
                    <span>{formatNumber(item.references.length)}</span>
                  </span>
                </span>
                <span className="ai-history-select-label">{selected ? zhCN.ai.historySelected : zhCN.ai.historyFocusRun}</span>
              </button>
            );
          })}
        </div>
      )}
    </section>
  );
}

function AIConversationSessionsPanel({
  sessions,
  status,
  busyId,
  searchQuery,
  searchResults,
  searchStatus,
  searchBusy,
  exportBusyId,
  exportResult,
  exportPath,
  onRefresh,
  onStartNew,
  onRestore,
  onSearchQueryChange,
  onSearch,
  onExport,
  onOpenExportPath,
}: {
  sessions: AIConversationSessionSummary[];
  status: string;
  busyId: string;
  searchQuery: string;
  searchResults: AIConversationSearchResult[];
  searchStatus: string;
  searchBusy: boolean;
  exportBusyId: string;
  exportResult: AIConversationExportResult | null;
  exportPath: string;
  onRefresh: () => void;
  onStartNew: () => void;
  onRestore: (sessionId: string) => void;
  onSearchQueryChange: (value: string) => void;
  onSearch: () => void;
  onExport: (sessionId: string, format: string, includeContextReferences: boolean) => void;
  onOpenExportPath: (path: string) => void;
}) {
  const [exportFormat, setExportFormat] = useState('markdown');
  const [includeContextReferences, setIncludeContextReferences] = useState(true);
  const currentSessions = sessions.filter(session => session.current);
  const archivedSessions = sessions.filter(session => !session.current);
  const runExport = (sessionId: string) => onExport(sessionId, exportFormat, includeContextReferences);
  return (
    <section className="ai-sessions-panel">
      <PanelTitle icon={Clock3} title={zhCN.ai.sessionsExportSearch} meta={`${zhCN.ai.sessionsMeta} · ${sessions.length} ${zhCN.ai.sessionsCount}`} />
      <div className="ai-sessions-toolbar">
        <button type="button" onClick={onRefresh}>
          <RefreshCw size={14} />
          {zhCN.ai.sessionRefresh}
        </button>
        <button type="button" onClick={onStartNew} disabled={busyId !== ''}>
          <FolderPlus size={14} />
          {busyId === 'new' ? zhCN.ai.sessionStartingNew : zhCN.ai.sessionNew}
        </button>
      </div>
      <AIConversationSessionSearchExportPanel
        searchQuery={searchQuery}
        searchBusy={searchBusy}
        exportFormat={exportFormat}
        includeContextReferences={includeContextReferences}
        onSearchQueryChange={onSearchQueryChange}
        onSearch={onSearch}
        onExportFormatChange={setExportFormat}
        onIncludeContextReferencesChange={setIncludeContextReferences}
      />
      {status && (
        <div className="ai-session-status">
          <span>{status}</span>
        </div>
      )}
      {searchStatus && (
        <div className="ai-session-status">
          <span>{searchStatus}</span>
        </div>
      )}
      {exportResult && (
        <div className="ai-session-export-result">
          <strong>{zhCN.ai.sessionExportResult}</strong>
          <button
            type="button"
            className="ai-session-export-path"
            data-ai-session-export-path="true"
            onClick={() => onOpenExportPath(exportPath || exportResult.path)}
          >
            <FileText size={14} />
            <span>{exportPath || exportResult.path}</span>
          </button>
          <DetailGrid rows={[
            [zhCN.ai.sessionSearchSession, exportResult.sessionId],
            [zhCN.ai.sessionExportPath, exportPath || exportResult.path],
            [zhCN.ai.sessionExportFormat, exportResult.format],
            [zhCN.ai.sessionMessages, formatNumber(exportResult.messageCount)],
            [zhCN.ai.sessionExportedAt, formatAIInstant(exportResult.exportedAt)],
            [zhCN.ai.sessionExportSummary, exportResult.summary],
          ]} />
        </div>
      )}
      <AIConversationSearchResults
        results={searchResults}
        searched={searchStatus !== ''}
        exportBusyId={exportBusyId}
        onExport={runExport}
      />
      {sessions.length === 0 && <EmptyState text={zhCN.ai.sessionsEmpty} />}
      {currentSessions.length > 0 && (
        <AIConversationSessionGroup
          title={zhCN.ai.sessionsCurrent}
          sessions={currentSessions}
          busyId={busyId}
          exportBusyId={exportBusyId}
          onRestore={onRestore}
          onExport={runExport}
        />
      )}
      {archivedSessions.length > 0 && (
        <AIConversationSessionGroup
          title={zhCN.ai.sessionsArchive}
          sessions={archivedSessions}
          busyId={busyId}
          exportBusyId={exportBusyId}
          onRestore={onRestore}
          onExport={runExport}
        />
      )}
    </section>
  );
}

function AIConversationSessionSearchExportPanel({
  searchQuery,
  searchBusy,
  exportFormat,
  includeContextReferences,
  onSearchQueryChange,
  onSearch,
  onExportFormatChange,
  onIncludeContextReferencesChange,
}: {
  searchQuery: string;
  searchBusy: boolean;
  exportFormat: string;
  includeContextReferences: boolean;
  onSearchQueryChange: (value: string) => void;
  onSearch: () => void;
  onExportFormatChange: (value: string) => void;
  onIncludeContextReferencesChange: (value: boolean) => void;
}) {
  return (
    <div className="ai-session-search-export">
      <form
        className="ai-session-search"
        data-ai-session-search="true"
        onSubmit={event => {
          event.preventDefault();
          onSearch();
        }}
      >
        <label>
          <span>{zhCN.ai.sessionSearch}</span>
          <input
            value={searchQuery}
            onChange={event => onSearchQueryChange(event.target.value)}
            placeholder={zhCN.ai.sessionSearchPlaceholder}
            aria-label={zhCN.ai.sessionSearch}
          />
        </label>
        <button type="submit" disabled={searchBusy || searchQuery.trim() === ''}>
          <Search size={14} />
          {searchBusy ? zhCN.ai.sessionSearchingShort : zhCN.ai.sessionSearchAction}
        </button>
      </form>
      <div className="ai-session-export-options">
        <label>
          <span>{zhCN.ai.sessionExportFormat}</span>
          <select value={exportFormat} onChange={event => onExportFormatChange(event.target.value)}>
            <option value="markdown">{zhCN.ai.sessionExportFormatMarkdown}</option>
            <option value="json">{zhCN.ai.sessionExportFormatJSON}</option>
          </select>
        </label>
        <label className="ai-session-export-checkbox">
          <input
            type="checkbox"
            checked={includeContextReferences}
            onChange={event => onIncludeContextReferencesChange(event.target.checked)}
          />
          <span>{zhCN.ai.sessionExportIncludeContext}</span>
        </label>
      </div>
    </div>
  );
}

function AIConversationSearchResults({
  results,
  searched,
  exportBusyId,
  onExport,
}: {
  results: AIConversationSearchResult[];
  searched: boolean;
  exportBusyId: string;
  onExport: (sessionId: string) => void;
}) {
  if (!searched) {
    return null;
  }
  return (
    <div className="ai-session-search-results">
      <div className="ai-session-search-results-head">
        <h4>{zhCN.ai.sessionSearchResult}</h4>
        <span>{results.length} {zhCN.ai.sessionSearchResultCount}</span>
      </div>
      {results.length === 0 && <EmptyState text={zhCN.ai.sessionSearchEmpty} />}
      {results.map(result => {
        const snippet = visibleAIText(result.snippet || result.contentSnippet) || zhCN.ai.searchSnippetMissing;
        const providerModel = [result.provider, result.model].filter(Boolean).join(' · ') || undefined;
        return (
          <article className="ai-session-search-result" data-ai-session-search-result="true" key={`${result.sessionId}-${result.messageId}`}>
            <div className="ai-session-head">
              <strong>{result.sessionPath || result.sessionId}</strong>
              <span>{aiActionTraceRoleLabel(result.role)}</span>
            </div>
            <p>{snippet}</p>
            <DetailGrid rows={[
              [zhCN.ai.sessionSearchSession, result.sessionId],
              [zhCN.ai.sessionSearchRole, aiActionTraceRoleLabel(result.role)],
              [zhCN.ai.sessionSearchPath, result.path],
              [zhCN.ai.sessionSearchTime, formatAIInstant(result.createdAt)],
              [zhCN.ai.sessionProviderModel, providerModel],
              [zhCN.ai.sessionSearchContextRefs, formatNumber(result.contextReferenceCount)],
            ]} />
            <div className="ai-session-actions">
              <button
                type="button"
                data-ai-session-export="true"
                onClick={() => onExport(result.sessionId)}
                disabled={exportBusyId !== '' && exportBusyId !== result.sessionId}
              >
                <Save size={14} />
                {exportBusyId === result.sessionId ? zhCN.ai.sessionExportingShort : zhCN.ai.sessionExport}
              </button>
            </div>
          </article>
        );
      })}
    </div>
  );
}

