function AIActionPanel({
  actions,
  agentProfiles,
  status,
  inputs,
  result,
  runningActionId,
  plannerState,
  onInputChange,
  onInputsChange,
  onRunAction,
  onRefreshActions,
  onOpenReportActionFile,
  onOpenContextReference,
  onRunFollowupAction,
}: {
  actions: AIAction[];
  agentProfiles: AgentProfile[];
  status: string;
  inputs: Record<string, string>;
  result: AIActionRunResponse | null;
  runningActionId: string;
  plannerState: PlannerState;
  onInputChange: (actionID: string, value: string) => void;
  onInputsChange: (values: Record<string, string>) => void;
  onRunAction: (action: AIAction) => void;
  onRefreshActions: () => void;
  onOpenReportActionFile: (filePath: string) => void;
  onOpenContextReference: (reference: AIContextReference) => void;
  onRunFollowupAction: AIActionFollowupRunner;
}) {
  const statusIsError = [
    zhCN.aiActions.loadFailed,
    zhCN.aiActions.runFailed,
    zhCN.aiActions.resultRefreshFailed,
    zhCN.aiActions.actionMissing,
  ].some(errorPrefix => status.startsWith(errorPrefix));
  const [actionQuery, setActionQuery] = useState('');
  const normalizedActionQuery = actionQuery.trim().toLocaleLowerCase('zh-CN');
  const visibleActions = useMemo(() => {
    if (!normalizedActionQuery) {
      return actions;
    }
    return actions.filter(action => (
      [action.id, action.kind, action.label, action.description, action.packId, action.packName, action.commandText]
        .filter((value): value is string => Boolean(value))
        .join('\n')
        .toLocaleLowerCase('zh-CN')
        .includes(normalizedActionQuery)
    ));
  }, [actions, normalizedActionQuery]);
  return (
    <section className="ai-action-panel">
      <PanelTitle icon={TerminalSquare} title={zhCN.aiActions.title} meta={status || zhCN.aiActions.meta} />
      <div className="ai-action-toolbar">
        <label className="ai-action-search">
          <Search size={14} aria-hidden="true" />
          <input
            type="search"
            value={actionQuery}
            onChange={event => setActionQuery(event.target.value)}
            placeholder={zhCN.aiActions.searchPlaceholder}
            aria-label={zhCN.aiActions.searchLabel}
          />
          <small>{visibleActions.length}/{actions.length}</small>
        </label>
        <button type="button" onClick={onRefreshActions} aria-label={zhCN.ai.refresh} title={zhCN.ai.refresh}>
          <RefreshCw size={14} />
        </button>
      </div>
      {statusIsError && (
        <div className="ai-status error">
          <AlertCircle size={15} />
          <span>{status}</span>
        </div>
      )}
      <AIPlannerProjection state={plannerState} />
      {actions.length === 0 && <EmptyState text={status || zhCN.aiActions.empty} />}
      {actions.length > 0 && visibleActions.length === 0 && <EmptyState text={zhCN.aiActions.searchEmpty} />}
      {visibleActions.map(action => {
        const running = runningActionId === action.id;
        const runDisabled = running || !buildAIActionRequest(action, inputs);
        return (
          <details key={action.id} className="ai-action-row" data-ai-action-id={action.id}>
            <summary>
              <span className="ai-action-summary-copy">
                <ChevronRight size={14} aria-hidden="true" />
                <strong>{action.label}</strong>
              </span>
              <small>{aiActionKindLabel(action)}</small>
            </summary>
            <div className="ai-action-row-content">
              <div className="ai-action-main">
                <code>{action.id}</code>
                <DetailGrid rows={[
                  [zhCN.aiActions.actionStatus, action.status ? localizedStatusLabel(action.status) : undefined],
                  [zhCN.aiActions.pack, action.packName || action.packId],
                  [zhCN.aiActions.commandText, action.commandText],
                ]} />
                {action.description && <p>{action.description}</p>}
                {action.capabilities && action.capabilities.length > 0 && <small>{formatToolCapabilities(action.capabilities)}</small>}
              </div>
              <div className="ai-action-form">
                {action.id === 'agent.profiles.update' ? (
                  <AIActionAgentProfileUpdateInput
                    action={action}
                    inputs={inputs}
                    agentProfiles={agentProfiles}
                    onInputChange={onInputChange}
                    onInputsChange={onInputsChange}
                    onRunAction={onRunAction}
                    runDisabled={runDisabled}
                  />
                ) : renderAIActionInput(action, inputs, onInputChange, onRunAction, runDisabled, agentProfiles)}
                <button type="button" onClick={() => onRunAction(action)} disabled={runDisabled}>
                  <Radar size={14} />
                  {running ? zhCN.aiActions.running : zhCN.aiActions.run}
                </button>
              </div>
            </div>
          </details>
        );
      })}
      {result && (
        <section className="ai-action-result">
          <strong>{zhCN.aiActions.result}</strong>
          {renderAIActionResult(result, onOpenReportActionFile, onOpenContextReference, onRunFollowupAction, runningActionId)}
        </section>
      )}
    </section>
  );
}

