const aiFileChangeActionIds = new Set([
  'workspace.write_file',
  'workspace.preview_patch',
  'workspace.apply_patch',
  'workspace.rename_file',
  'workspace.delete_file',
]);

function buildAIFileChangeSet(
  traces: AIActionTraceItem[],
  streamEvents: AIChatStreamEvent[],
  manualActionResult: AIActionRunResponse | null,
): AIFileChangeItem[] {
  const changes: AIFileChangeItem[] = [];
  const indexByKey = new Map<string, number>();
  const pushChange = (change: Omit<AIFileChangeItem, 'key'>) => {
    const path = change.path.trim();
    if (!path) {
      return;
    }
    const key = [
      change.actionId || change.operation || change.source,
      change.operation || '',
      path,
      change.targetPath || '',
    ].join(':');
    const item: AIFileChangeItem = { ...change, key, path };
    const existingIndex = indexByKey.get(key);
    if (existingIndex === undefined) {
      indexByKey.set(key, changes.length);
      changes.push(item);
      return;
    }
    const existing = changes[existingIndex];
    changes[existingIndex] = mergeAIFileChange(existing, item);
  };

  if (manualActionResult) {
    pushAIActionResultFileChanges(manualActionResult, 'result', pushChange);
  }
  streamEvents.forEach(event => {
    if (event.actionResult) {
      pushAIActionResultFileChanges(event.actionResult, 'stream', change => pushChange({
        ...change,
        status: change.status || event.status,
        createdAt: event.finishedAt || event.startedAt || change.createdAt,
        summary: change.summary || event.resultSummary,
      }));
    }
  });
  traces.forEach(trace => {
    if (!trace.actionId || !aiFileChangeActionIds.has(trace.actionId)) {
      return;
    }
    const fileReferences = trace.contextReferences.filter(reference => reference.path && (reference.kind === 'file' || reference.kind === 'searchResult' || reference.kind === 'fileDiff'));
    fileReferences.forEach(reference => pushChange({
      source: 'trace',
      actionId: trace.actionId,
      operation: trace.phase,
      status: trace.status,
      path: reference.path as string,
      summary: trace.summary || trace.title || reference.title,
      reference,
      createdAt: trace.createdAt,
    }));
  });
  return changes.slice(0, 12);
}

function buildAIConversationFileChanges(conversation: AIConversation | null): AIFileChangeItem[] {
  if (!conversation) {
    return [];
  }
  const changes: AIFileChangeItem[] = [];
  conversation.messages
    .filter(messageItem => messageItem.role === 'tool')
    .forEach(messageItem => {
      const actionId = aiToolMessageFileActionId(messageItem.content);
      if (!actionId) {
        return;
      }
      const operation = aiToolMessageFileOperation(messageItem.content);
      const fileReferences = (messageItem.contextReferences ?? [])
        .filter(reference => reference.path && (reference.kind === 'file' || reference.kind === 'searchResult' || reference.kind === 'fileDiff'));
      const path = aiToolMessageField(messageItem.content, '路径') || fileReferences[0]?.path || '';
      const targetPath = aiToolMessageField(messageItem.content, '目标路径');
      if (!path) {
        return;
      }
      changes.push({
        key: `${actionId}:${operation || ''}:${path}:${targetPath || ''}:${messageItem.createdAt ?? changes.length}`,
        source: 'trace',
        actionId,
        operation,
        status: messageItem.status,
        path,
        targetPath,
        summary: messageItem.content,
        patch: aiToolMessagePatch(messageItem.content),
        reference: fileReferences[0],
        createdAt: messageItem.createdAt,
      });
    });
  return changes.slice(0, 12);
}

function pushAIActionResultFileChanges(
  actionResult: AIActionRunResponse,
  source: AIFileChangeSource,
  pushChange: (change: Omit<AIFileChangeItem, 'key'>) => void,
) {
  const { action, result, execution } = actionResult;
  const toolMessage = actionResult.message;
  const structuredChanges = result.fileChanges ?? [];
  const structuredDiffs = result.fileDiffs ?? [];
  if (!aiFileChangeActionIds.has(action.id) && result.kind !== 'patch' && result.kind !== 'deleted_file' && structuredChanges.length === 0 && structuredDiffs.length === 0) {
    return;
  }
  structuredChanges.forEach(change => {
    const path = change.path || change.targetPath || '';
    if (!path) {
      return;
    }
    pushChange({
      source,
      actionId: change.actionId || action.id,
      operation: change.operation || result.operation,
      status: change.status || execution?.status || toolMessage.status,
      path,
      targetPath: change.targetPath,
      summary: change.summary || result.summary || toolMessage.content,
      patch: change.patch || change.diff,
      createdAt: change.createdAt || toolMessage.createdAt,
    });
  });
  structuredDiffs.forEach(diff => {
    const path = diff.path || '';
    if (!path) {
      return;
    }
    pushChange({
      source,
      actionId: diff.actionId || action.id,
      operation: diff.operation || result.operation,
      status: execution?.status || toolMessage.status,
      path,
      summary: diff.summary || result.summary || toolMessage.content,
      patch: diff.diff,
      createdAt: toolMessage.createdAt,
    });
  });
  const path = result.operation === 'rename_file' && result.path
    ? result.path
    : result.file?.path
    || result.targetPath
    || result.path
    || result.deletedFile?.path
    || '';
  if (!path) {
    return;
  }
  pushChange({
    source,
    actionId: action.id,
    operation: result.operation,
    status: execution?.status || toolMessage.status,
    path,
    targetPath: result.targetPath,
    summary: result.summary || toolMessage.content,
    patch: result.patch,
    createdAt: toolMessage.createdAt,
  });
}

function mergeAIFileChangeSets(left: AIFileChangeItem[], right: AIFileChangeItem[]): AIFileChangeItem[] {
  const merged: AIFileChangeItem[] = [];
  const indexByKey = new Map<string, number>();
  [...left, ...right].forEach(change => {
    const existingIndex = indexByKey.get(change.key);
    if (existingIndex === undefined) {
      indexByKey.set(change.key, merged.length);
      merged.push(change);
      return;
    }
    merged[existingIndex] = mergeAIFileChange(merged[existingIndex], change);
  });
  return merged.slice(0, 12);
}

function mergeAIFileChange(existing: AIFileChangeItem, next: AIFileChangeItem): AIFileChangeItem {
  return {
    ...existing,
    ...next,
    patch: next.patch || existing.patch,
    summary: next.summary || existing.summary,
    status: next.status || existing.status,
    createdAt: next.createdAt || existing.createdAt,
    reference: next.reference || existing.reference,
  };
}

function aiToolMessageFileActionId(content: string): string | undefined {
  if (content.includes('workspace.write_file')) {
    return 'workspace.write_file';
  }
  if (content.includes('workspace.apply_patch')) {
    return 'workspace.apply_patch';
  }
  if (content.includes('workspace.preview_patch')) {
    return 'workspace.preview_patch';
  }
  if (content.includes('workspace.rename_file')) {
    return 'workspace.rename_file';
  }
  if (content.includes('workspace.delete_file')) {
    return 'workspace.delete_file';
  }
  return undefined;
}

function aiToolMessageFileOperation(content: string): string | undefined {
  return aiToolMessageFileActionId(content)?.replace('workspace.', '');
}

function aiToolMessageField(content: string, label: string): string | undefined {
  const prefix = `${label}:`;
  const line = content.split('\n').find(item => item.startsWith(prefix));
  const value = line?.slice(prefix.length).trim();
  return value || undefined;
}

function aiToolMessagePatch(content: string): string | undefined {
  const lines = content.split('\n');
  const startIndex = lines.findIndex(line => line.startsWith('--- '));
  if (startIndex === -1) {
    return undefined;
  }
  return lines.slice(startIndex).join('\n').trimEnd();
}

function aiFileChangeStatusLabel(status?: string): string {
  return aiActionTraceStatusLabel(status);
}

function aiFileChangeOperationLabel(operation?: string, actionId?: string): string {
  const normalized = (operation || actionId || '').trim().toLowerCase();
  switch (normalized) {
    case 'write_file':
    case 'workspace.write_file':
      return zhCN.ai.fileChangeWrite;
    case 'preview_patch':
    case 'workspace.preview_patch':
      return zhCN.ai.fileChangePatchCheck;
    case 'apply_patch':
    case 'workspace.apply_patch':
      return zhCN.ai.fileChangeApply;
    case 'rename_file':
    case 'workspace.rename_file':
      return zhCN.ai.fileChangeRename;
    case 'delete_file':
    case 'workspace.delete_file':
      return zhCN.ai.fileChangeDelete;
    default:
      return zhCN.ai.fileChangeUnknownOperation;
  }
}

function aiFileChangeSourceLabel(source: AIFileChangeSource): string {
  switch (source) {
    case 'result':
      return zhCN.ai.fileChangeSourceResult;
    case 'stream':
      return zhCN.ai.fileChangeSourceStream;
    case 'trace':
      return zhCN.ai.fileChangeSourceTrace;
    default:
      return source;
  }
}

function AIActionTracePanel({
  items,
  onOpenReference,
  onRunFollowupAction,
  actionRunningId,
}: {
  items: AIActionTraceItem[];
  onOpenReference: (reference: AIContextReference) => void;
  onRunFollowupAction: AIActionFollowupRunner;
  actionRunningId: string;
}) {
  const settlingHarness = actionRunningId === 'harness.cases.from_ai_conversation';
  return (
    <section className="ai-action-trace-panel">
      <PanelTitle icon={GitBranch} title={zhCN.ai.actionTrace} meta={`${zhCN.ai.actionTraceMeta} · ${zhCN.ai.actionTraceToolCall} · ${items.length} ${zhCN.ai.actionTraceCount}`} />
      {items.length === 0 && <EmptyState text={zhCN.ai.noActionTrace} />}
      {items.length > 0 && (
        <div className="ai-action-trace-list">
          {items.map((item, index) => {
            const title = traceDisplayValue(visibleAIText(item.title) || item.actionId || item.toolName || item.actionKind, zhCN.ai.actionTraceUntitled);
            const summary = traceDisplayValue(visibleAIText(item.summary), zhCN.ai.actionTraceNoSummary);
            const status = aiActionTraceStatusLabel(item.status);
            const createdAt = formatAIInstant(item.createdAt);
            const traceIndex = traceDisplayValue(item.index, backendValueNotProvided);
            return (
              <article key={`${item.id ?? ''}:${item.messageId ?? ''}:${item.toolCallId ?? ''}:${item.actionId ?? ''}:${index}`} className="ai-action-trace-row">
                <div className="ai-action-trace-head">
                  <span className="ai-action-trace-index">{traceIndex}</span>
                  <strong>{title}</strong>
                  <span className="ai-action-trace-status" data-status={aiActionTraceStatusTone(item.status)}>{status}</span>
                </div>
                <p className="ai-action-trace-summary">{summary}</p>
                {item.nativeToolResultForwarded && (
                  <small className="ai-message-status" data-native-tool-result-forwarded="true">
                    {formatNativeToolResultForwarded(item.toolCallId)}
                  </small>
                )}
                <dl className="ai-action-trace-meta">
                  <div>
                    <dt>{zhCN.ai.referenceId}</dt>
                    <dd>{traceDisplayValue(item.id, backendValueNotProvided)}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTraceActionId}</dt>
                    <dd>{traceDisplayValue(item.actionId, backendValueNotProvided)}</dd>
                  </div>
                  {item.toolCallId && (
                    <div>
                      <dt>{zhCN.ai.streamEventToolCallId}</dt>
                      <dd>{item.toolCallId}</dd>
                    </div>
                  )}
                  {item.toolName && (
                    <div>
                      <dt>{zhCN.ai.providerToolName}</dt>
                      <dd>{item.toolName}</dd>
                    </div>
                  )}
                  {item.nativeToolCall && (
                    <div>
                      <dt>{zhCN.ai.toolCallMode}</dt>
                      <dd>{zhCN.ai.nativeToolCall}</dd>
                    </div>
                  )}
                  <div>
                    <dt>{zhCN.ai.actionTraceActionKind}</dt>
                    <dd>{aiActionTraceKindLabel(item.actionKind)}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTraceStatus}</dt>
                    <dd>{status}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTraceCreatedAt}</dt>
                    <dd>{traceDisplayValue(createdAt)}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTraceProvider}</dt>
                    <dd>{traceDisplayValue(item.provider)}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTraceModel}</dt>
                    <dd>{traceDisplayValue(item.model)}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTraceRole}</dt>
                    <dd>{aiActionTraceRoleLabel(item.role)}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTracePhase}</dt>
                    <dd>{aiActionTracePhaseLabel(item.phase)}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTraceMessage}</dt>
                    <dd>{traceDisplayValue(item.messageId, backendValueNotProvided)}</dd>
                  </div>
                  <div>
                    <dt>{zhCN.ai.actionTraceReferences}</dt>
                    <dd>{item.contextReferences.length} {zhCN.ai.actionTraceReferenceCount}</dd>
                  </div>
                </dl>
                {item.contextReferences.length > 0 && (
                  <AIReferenceActions references={item.contextReferences} onOpenReference={onOpenReference} compact />
                )}
                <div className="row-actions detail-actions">
                  <button
                    type="button"
                    onClick={() => onRunFollowupAction('harness.cases.from_ai_conversation', buildAIConversationHarnessFollowupInput({
                      aiMessageIds: [item.messageId],
                      toolCallIds: [item.toolCallId],
                      actionTraceIds: [item.id],
                      source: 'desktop.ai.action_trace',
                    }))}
                    disabled={settlingHarness}
                  >
                    {settlingHarness ? zhCN.ai.settleAsHarnessRunning : zhCN.ai.settleAsHarness}
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}

function AIFrontierQueuePanel({
  queue,
  query,
  status,
  busy,
  onQueryChange,
  onRefresh,
  onRunAction,
  onOpenFile,
  onOpenReference,
}: {
  queue: FrontierQueue | null;
  query: FrontierQueueQuery;
  status: string;
  busy: string;
  onQueryChange: (patch: Partial<FrontierQueueQuery>) => void;
  onRefresh: () => void;
  onRunAction: (actionId: 'frontier.execute_next' | 'frontier.autopilot', item?: FrontierPriorityItem) => void;
  onOpenFile: (filePath: string) => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const items = queue?.items ?? [];
  const summary = queue?.summary;
  const updateText = (field: 'goal' | 'status' | 'priority' | 'source' | 'q', value: string) => onQueryChange({ [field]: value });
  const updateReadyFilter = (readyFilter: FrontierQueueQuery['readyFilter']) => onQueryChange({ readyFilter });
  const updateNumber = (field: 'budget' | 'maxItems', value: string) => {
    const parsed = Number(value);
    onQueryChange({ [field]: Number.isFinite(parsed) && parsed > 0 ? parsed : undefined });
  };
  const readyFilter = query.readyFilter ?? 'all';
  const statusMeta = queue
    ? `${frontierQueueStatusLabel(queue.queueStatus)} · ${queue.count} ${zhCN.ai.frontierQueueItemCount}`
    : zhCN.ai.frontierQueueMeta;
  const latestBlackboardReferences: AIContextReference[] = (queue?.blackboardItems ?? []).slice(0, 3).map(item => ({
    id: item.id,
    kind: 'blackboard',
    label: item.title,
    title: item.title,
    path: item.filePath,
    source: zhCN.ai.frontierQueue,
  }));
  const latestAgentReferences: AIContextReference[] = (queue?.agentTasks ?? []).slice(0, 3).map(task => ({
    id: task.id,
    kind: 'agentTask',
    label: task.title,
    title: task.title,
    path: task.filePath,
    source: zhCN.ai.frontierQueue,
  }));
  return (
    <section className="ai-frontier-queue-panel" data-ai-frontier-queue="true">
      <PanelTitle icon={CircleDot} title={zhCN.ai.frontierQueue} meta={statusMeta} />
      <div className="ai-frontier-queue-form">
        <label className="ai-frontier-queue-wide">
          <span>{zhCN.ai.frontierQueueQueryGoal}</span>
          <input
            value={query.goal ?? ''}
            onChange={event => updateText('goal', event.target.value)}
            placeholder={zhCN.ai.frontierQueueQueryGoalPlaceholder}
            aria-label={zhCN.ai.frontierQueueQueryGoal}
            data-frontier-queue-query="goal"
          />
        </label>
        <label>
          <span>{zhCN.ai.frontierQueueQueryStatus}</span>
          <input value={query.status ?? ''} onChange={event => updateText('status', event.target.value)} aria-label={zhCN.ai.frontierQueueQueryStatus} data-frontier-queue-query="status" />
        </label>
        <label>
          <span>{zhCN.ai.frontierQueueQueryPriority}</span>
          <input value={query.priority ?? ''} onChange={event => updateText('priority', event.target.value)} aria-label={zhCN.ai.frontierQueueQueryPriority} data-frontier-queue-query="priority" />
        </label>
        <label>
          <span>{zhCN.ai.frontierQueueQuerySource}</span>
          <input value={query.source ?? ''} onChange={event => updateText('source', event.target.value)} aria-label={zhCN.ai.frontierQueueQuerySource} data-frontier-queue-query="source" />
        </label>
        <label>
          <span>{zhCN.ai.frontierQueueQueryKeyword}</span>
          <input value={query.q ?? ''} onChange={event => updateText('q', event.target.value)} aria-label={zhCN.ai.frontierQueueQueryKeyword} data-frontier-queue-query="q" />
        </label>
        <div className="ai-frontier-queue-mode" data-frontier-queue-ready-filter={readyFilter}>
          <span>{zhCN.ai.frontierQueueQueryMode}</span>
          <div>
            {([
              ['all', zhCN.ai.frontierQueueModeAll],
              ['ready', zhCN.ai.frontierQueueModeReady],
              ['blocked', zhCN.ai.frontierQueueModeBlocked],
            ] as Array<[NonNullable<FrontierQueueQuery['readyFilter']>, string]>).map(([value, label]) => (
              <button
                key={value}
                type="button"
                className={readyFilter === value ? 'selected' : undefined}
                onClick={() => updateReadyFilter(value)}
                data-frontier-queue-mode={value}
              >
                {label}
              </button>
            ))}
          </div>
        </div>
        <label>
          <span>{zhCN.ai.frontierQueueQueryBudget}</span>
          <input type="number" min="1" value={query.budget ?? ''} onChange={event => updateNumber('budget', event.target.value)} aria-label={zhCN.ai.frontierQueueQueryBudget} data-frontier-queue-query="budget" />
        </label>
        <label>
          <span>{zhCN.ai.frontierQueueQueryMaxItems}</span>
          <input type="number" min="1" value={query.maxItems ?? ''} onChange={event => updateNumber('maxItems', event.target.value)} aria-label={zhCN.ai.frontierQueueQueryMaxItems} data-frontier-queue-query="maxItems" />
        </label>
      </div>
      <div className="ai-frontier-queue-toolbar">
        <button type="button" onClick={onRefresh} disabled={busy !== ''} data-frontier-queue-action="refresh">
          <RefreshCw size={14} />
          {busy === 'refresh' ? zhCN.ai.frontierQueueLoading : zhCN.ai.frontierQueueRefresh}
        </button>
        <button type="button" className="primary-action" onClick={() => onRunAction('frontier.autopilot')} disabled={busy !== '' || items.length === 0} data-frontier-queue-action="autopilot">
          <Play size={14} />
          {busy === 'frontier.autopilot' ? zhCN.ai.frontierQueueAutopilotRunning : zhCN.ai.frontierQueueAutopilot}
        </button>
      </div>
      {status && (
        <div className="ai-frontier-queue-status" data-frontier-queue-status="true">
          <CircleDot size={13} />
          <span>{status}</span>
        </div>
      )}
      {queue && (
        <DetailGrid rows={[
          [zhCN.ai.frontierQueueSummary, summary?.summary],
          [zhCN.ai.frontierQueuePath, queue.path],
          [zhCN.aiActions.frontierQueueSource, queue.queueSource],
          [zhCN.aiActions.frontierQueueStatus, frontierQueueStatusLabel(queue.queueStatus)],
          [zhCN.ai.frontierQueueItemCount, queue.count],
          [zhCN.ai.frontierQueueOpenBlackboard, summary?.openBlackboard],
          [zhCN.ai.frontierQueueQueuedTasks, summary?.queuedTasks],
          [zhCN.ai.frontierQueueBudgetUsed, summary?.budgetUsed],
          [zhCN.ai.frontierQueueBudgetRemaining, summary?.budgetRemaining],
          [zhCN.ai.frontierQueueReadyCount, summary?.readyCount],
          [zhCN.ai.frontierQueueBlockedCount, summary?.blockedCount],
          [zhCN.ai.frontierQueueAgentState, queue.agentState?.path],
        ]} />
      )}
      <AIReferenceActions references={[...latestBlackboardReferences, ...latestAgentReferences]} onOpenReference={onOpenReference} compact />
      <div className="ai-frontier-queue-list">
        {items.length === 0 && <EmptyState text={zhCN.ai.frontierQueueEmpty} />}
        {items.map((item, index) => (
          <div
            key={item.id || `${zhCN.ai.frontierQueue}-${index}`}
            className="ai-frontier-queue-row"
            data-frontier-queue-item="true"
            data-frontier-queue-item-id={item.id}
            data-frontier-agent-task-id={item.agentTaskId}
            data-frontier-blackboard-item-id={item.blackboardItemId}
          >
            <div className="ai-frontier-queue-head">
              <div>
                <strong>{item.title || item.hypothesis || item.target || item.id || `${zhCN.ai.frontierQueue} ${index + 1}`}</strong>
                <span>{zhCN.aiActions.frontierScore}: {formatFrontierScore(item.score) ?? zhCN.details.empty}</span>
              </div>
              <div className="ai-frontier-queue-actions">
                {item.filePath && (
                  <button type="button" onClick={() => onOpenFile(item.filePath as string)}>
                    <FileText size={14} />
                    {zhCN.harness.openFile}
                  </button>
                )}
                <button type="button" onClick={() => onRunAction('frontier.execute_next', item)} disabled={busy !== ''} data-frontier-queue-action="execute-next">
                  <ChevronRight size={14} />
                  {busy === (item.id || 'frontier.execute_next') ? zhCN.ai.frontierQueueExecuteRunning : zhCN.ai.frontierQueueExecuteNext}
                </button>
              </div>
            </div>
            <AIFrontierQueueDependencyActions item={item} onOpenReference={onOpenReference} />
            <AIActionFrontierPriorityItem item={item} fallbackRank={index + 1} onOpenFile={onOpenFile} />
          </div>
        ))}
      </div>
    </section>
  );
}

function AIFailureStrategyPanel({
  executions,
  draft,
  status,
  busy,
  actionResult,
  promptRegistry,
  frontierQueue,
  blackboard,
  agentState,
  onDraftChange,
  onRunFailureStrategySisyphus,
  onRunFailureStrategyFollowup,
  onOpenFile,
  onOpenReference,
}: {
  executions: ExecutionStep[];
  draft: AIFailureStrategyDraft;
  status: string;
  busy: AIFailureStrategyActionID | '';
  actionResult: AIActionRunResponse | null;
  promptRegistry: PromptRegistry | null;
  frontierQueue: FrontierQueue | null;
  blackboard: BlackboardState;
  agentState: AgentState;
  onDraftChange: (patch: Partial<AIFailureStrategyDraft>) => void;
  onRunFailureStrategySisyphus: (input: AIActionRunInput) => void;
  onRunFailureStrategyFollowup: (actionId: 'frontier.autopilot' | 'harness.cases.from_failure', input: AIActionRunInput) => void;
  onOpenFile: (filePath: string) => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const failedExecutions = useMemo(
    () => executions
      .filter(isFailureStrategyExecution)
      .sort(compareExecutionsNewestFirst),
    [executions],
  );
  const selectableExecutions = failedExecutions.length > 0 ? failedExecutions : [...executions].sort(compareExecutionsNewestFirst);
  const selectedExecution = executions.find(item => item.id === draft.executionId) ?? failedExecutions[0];
  const selectedExecutionId = draft.executionId.trim() || selectedExecution?.id || '';

  useEffect(() => {
    if (draft.executionId || draft.transcript || !selectedExecution) {
      return;
    }
    onDraftChange(failureStrategyPatchFromExecution(selectedExecution));
  }, [draft.executionId, draft.transcript, onDraftChange, selectedExecution]);

  const sisyphusResult = actionResult?.result.kind === 'sisyphus_conclusion' ? actionResult.result : undefined;
  const primaryBlackboardItem = sisyphusResult?.blackboardItem
    ?? latestFailureStrategyBlackboardItem(blackboard.items);
  const primaryAgentTask = sisyphusResult?.agentTask
    ?? latestFailureStrategyAgentTask(agentState.tasks, primaryBlackboardItem?.id);
  const promptVersion = sisyphusResult?.promptVersion ?? activePromptRegistryVersion(promptRegistry, 'agent.strategy_mutator');
  const mutationHint = sisyphusResult?.outputSummary
    || primaryAgentTask?.goal
    || primaryBlackboardItem?.content;
  const goal = draft.goal.trim()
    || sisyphusResult?.goal
    || frontierQueue?.summary?.goal
    || primaryAgentTask?.goal
    || '';
  const hasFailureInput = Boolean(draft.executionId.trim() || draft.transcript.trim());
  const conclusionInput = cleanFailureStrategyInput({
    executionId: selectedExecutionId,
    transcript: draft.transcript.trim(),
    failureKind: draft.failureKind.trim(),
    failureMessage: draft.failureMessage.trim(),
    goal,
    title: draft.title.trim(),
    priority: draft.priority.trim(),
    source: draft.source.trim() || 'desktop.ai.failure_strategy.sisyphus',
  });
  const harnessInput = cleanFailureStrategyInput({
    executionId: selectedExecutionId,
    transcript: draft.transcript.trim(),
    title: draft.title.trim() || primaryBlackboardItem?.title || selectedExecution?.label,
    goal,
    source: 'desktop.ai.failure_strategy.harness',
    agentTaskId: primaryAgentTask?.id,
    blackboardItemId: primaryBlackboardItem?.id,
    promptVersionId: promptVersion?.id,
  });
  const autopilotInput = cleanFailureStrategyInput({
    goal,
    agentTaskId: primaryAgentTask?.id,
    blackboardItemId: primaryBlackboardItem?.id,
    source: 'desktop.ai.failure_strategy.frontier_autopilot',
  });
  const references = dedupeAIContextReferences([
    primaryBlackboardItem ? {
      id: primaryBlackboardItem.id,
      kind: 'blackboard',
      label: primaryBlackboardItem.title,
      title: primaryBlackboardItem.title,
      path: primaryBlackboardItem.filePath,
      source: zhCN.ai.failureStrategyTitle,
    } : undefined,
    primaryAgentTask ? {
      id: primaryAgentTask.id,
      kind: 'agentTask',
      label: primaryAgentTask.title,
      title: primaryAgentTask.title,
      path: primaryAgentTask.filePath,
      source: zhCN.ai.failureStrategyTitle,
    } : undefined,
  ].filter(Boolean) as AIContextReference[]);
  const executionCount = executions.length;
  const meta = `${failedExecutions.length}/${executionCount} ${zhCN.ai.failureStrategyFailedExecutions} · ${agentState.tasks.filter(isStrategyMutatorAgentTask).length} ${zhCN.ai.strategyMutatorTasks}`;

  return (
    <section className="ai-failure-strategy-panel" data-ai-failure-strategy-panel="true">
      <PanelTitle icon={AlertCircle} title={zhCN.ai.failureStrategyPanel} meta={meta} />
      <div className="ai-failure-strategy-form">
        <label className="ai-failure-strategy-wide">
          <span>{zhCN.ai.failureStrategyExecution}</span>
          <select
            value={draft.executionId || selectedExecution?.id || ''}
            onChange={event => {
              const execution = executions.find(item => item.id === event.target.value);
              onDraftChange(execution ? failureStrategyPatchFromExecution(execution) : { executionId: event.target.value });
            }}
            aria-label={zhCN.ai.failureStrategyExecution}
            data-ai-failure-execution-select="true"
          >
            <option value="">{zhCN.ai.failureStrategyExecutionPlaceholder}</option>
            {selectableExecutions.map(item => (
              <option key={item.id} value={item.id}>
                {failureStrategyExecutionOptionLabel(item)}
              </option>
            ))}
          </select>
        </label>
        <label>
          <span>{zhCN.aiActions.sisyphusFailureKindInput}</span>
          <input
            value={draft.failureKind}
            onChange={event => onDraftChange({ failureKind: event.target.value })}
            placeholder={zhCN.aiActions.sisyphusFailureKindPlaceholder}
            aria-label={zhCN.aiActions.sisyphusFailureKindInput}
          />
        </label>
        <label>
          <span>{zhCN.aiActions.sisyphusPriorityInput}</span>
          <input
            value={draft.priority}
            onChange={event => onDraftChange({ priority: event.target.value })}
            placeholder={zhCN.aiActions.sisyphusPriorityPlaceholder}
            aria-label={zhCN.aiActions.sisyphusPriorityInput}
          />
        </label>
        <label className="ai-failure-strategy-wide">
          <span>{zhCN.aiActions.sisyphusFailureMessageInput}</span>
          <textarea
            value={draft.failureMessage}
            onChange={event => onDraftChange({ failureMessage: event.target.value })}
            placeholder={zhCN.aiActions.sisyphusFailureMessagePlaceholder}
            aria-label={zhCN.aiActions.sisyphusFailureMessageInput}
          />
        </label>
        <label className="ai-failure-strategy-wide">
          <span>{zhCN.aiActions.sisyphusGoalInput}</span>
          <textarea
            value={draft.goal}
            onChange={event => onDraftChange({ goal: event.target.value })}
            placeholder={zhCN.ai.failureStrategyGoalPlaceholder}
            aria-label={zhCN.aiActions.sisyphusGoalInput}
          />
        </label>
        <label className="ai-failure-strategy-wide">
          <span>{zhCN.aiActions.sisyphusTranscriptInput}</span>
          <textarea
            value={draft.transcript}
            onChange={event => onDraftChange({ transcript: event.target.value })}
            placeholder={zhCN.ai.failureStrategyTranscriptPlaceholder}
            aria-label={zhCN.aiActions.sisyphusTranscriptInput}
          />
        </label>
      </div>
      <div className="ai-failure-strategy-toolbar">
        <button
          type="button"
          className="primary-action"
          onClick={() => onRunFailureStrategySisyphus(conclusionInput)}
          disabled={busy !== '' || !hasFailureInput}
          data-ai-failure-action="conclude"
        >
          <AlertCircle size={14} />
          {busy === 'sisyphus.conclude_failure' ? zhCN.ai.failureStrategyConcluding : zhCN.ai.failureStrategyConclude}
        </button>
        <button
          type="button"
          onClick={() => onRunFailureStrategyFollowup('harness.cases.from_failure', harnessInput)}
          disabled={busy !== '' || !hasFailureInput}
          data-ai-failure-action="harness-from-failure"
        >
          <ClipboardCheck size={14} />
          {busy === 'harness.cases.from_failure' ? zhCN.ai.failureStrategyHarnessRunning : zhCN.ai.failureStrategyHarnessFromFailure}
        </button>
        <button
          type="button"
          onClick={() => onRunFailureStrategyFollowup('frontier.autopilot', autopilotInput)}
          disabled={busy !== '' || !goal}
          data-ai-failure-action="frontier-autopilot"
        >
          <Radar size={14} />
          {busy === 'frontier.autopilot' ? zhCN.ai.failureStrategyAutopilotRunning : zhCN.ai.failureStrategyFrontierAutopilot}
        </button>
      </div>
      {status && (
        <div className="ai-failure-strategy-status" data-ai-failure-status="true">
          <CircleDot size={13} />
          <span>{status}</span>
        </div>
      )}
      <DetailGrid rows={[
        [zhCN.ai.failureStrategyTitle, goal],
        [zhCN.ai.failureStrategyStatus, status],
        [zhCN.ai.failureStrategySelectedExecution, selectedExecution?.id],
        [zhCN.aiActions.commandInput, selectedExecution?.command],
        [zhCN.aiActions.executionStatus, selectedExecution ? executionStatusLabel(selectedExecution.status, selectedExecution.rawStatus) : undefined],
        [zhCN.execution.exitCode, selectedExecution?.exitCode],
        [zhCN.ai.failureStrategyConcludeAction, 'sisyphus.conclude_failure'],
        [zhCN.ai.failureStrategyHarnessAction, 'harness.cases.from_failure'],
        [zhCN.ai.failureStrategyAutopilotAction, 'frontier.autopilot'],
        [zhCN.ai.failureStrategyBlackboard, primaryBlackboardItem?.id],
        [zhCN.ai.failureStrategyAgentTask, primaryAgentTask?.id],
        [zhCN.ai.failureStrategyPromptVersion, promptVersion?.id],
        [zhCN.ai.frontierQueueItemCount, frontierQueue?.count],
      ]} />
      <AIReferenceActions references={references} onOpenReference={onOpenReference} compact />
      <div className="ai-failure-strategy-evidence">
        {!primaryBlackboardItem && !primaryAgentTask && !promptVersion && !mutationHint && (
          <EmptyState text={zhCN.ai.failureStrategyEmpty} />
        )}
        {primaryBlackboardItem && (
          <article data-ai-failure-blackboard-id={primaryBlackboardItem.id}>
            <div className="ai-failure-strategy-head">
              <strong>{zhCN.ai.failureStrategyBlackboard}</strong>
              <span>{blackboardStatusLabel(primaryBlackboardItem.status)}</span>
            </div>
            <p>{primaryBlackboardItem.title}</p>
            <DetailGrid rows={[
              [zhCN.blackboard.id, primaryBlackboardItem.id],
              [zhCN.blackboard.kind, blackboardKindLabel(primaryBlackboardItem.kind)],
              [zhCN.blackboard.priority, blackboardPriorityLabel(primaryBlackboardItem.priority)],
              [zhCN.blackboard.source, primaryBlackboardItem.source],
              [zhCN.aiActions.executionId, primaryBlackboardItem.executionId],
            ]} />
            {primaryBlackboardItem.filePath && (
              <button type="button" onClick={() => onOpenFile(primaryBlackboardItem.filePath as string)}>{zhCN.harness.openFile}</button>
            )}
          </article>
        )}
        {primaryAgentTask && (
          <article data-ai-failure-agent-task-id={primaryAgentTask.id}>
            <div className="ai-failure-strategy-head">
              <strong>{zhCN.ai.failureStrategyAgentTask}</strong>
              <span>{agentStatusLabel(primaryAgentTask.status)}</span>
            </div>
            <p>{primaryAgentTask.title}</p>
            <DetailGrid rows={[
              [zhCN.agents.id, primaryAgentTask.id],
              [zhCN.agents.role, primaryAgentTask.role],
              [zhCN.agents.priority, agentPriorityLabel(primaryAgentTask.priority)],
              [zhCN.agents.source, primaryAgentTask.source],
              [zhCN.agents.blackboardItemId, primaryAgentTask.blackboardItemId],
              [zhCN.agents.executionId, primaryAgentTask.executionId],
            ]} />
            {primaryAgentTask.filePath && (
              <button type="button" onClick={() => onOpenFile(primaryAgentTask.filePath as string)}>{zhCN.harness.openFile}</button>
            )}
          </article>
        )}
        {promptVersion && (
          <article data-ai-failure-prompt-version={promptVersion.id}>
            <strong>{zhCN.ai.failureStrategyPromptVersion}</strong>
            <DetailGrid rows={[
              [zhCN.aiActions.promptVersion, promptVersion.id],
              [zhCN.aiActions.promptTitleInput, promptVersion.title],
              [zhCN.aiActions.promptProviderName, promptVersion.providerName],
              [zhCN.aiActions.promptProviderModel, promptVersion.model],
            ]} />
          </article>
        )}
        {mutationHint && (
          <article data-ai-failure-mutation-hint="true">
            <strong>{zhCN.ai.failureStrategyMutationHint}</strong>
            <pre>{aiDisplayText(mutationHint, '')}</pre>
          </article>
        )}
      </div>
    </section>
  );
}

function isFailureStrategyExecution(execution: ExecutionStep): boolean {
  return execution.status === 'failed' || execution.status === 'stopped' || (execution.exitCode !== undefined && execution.exitCode !== 0);
}

function compareExecutionsNewestFirst(left: ExecutionStep, right: ExecutionStep): number {
  const leftTime = left.completedAt ?? left.startedAt ?? 0;
  const rightTime = right.completedAt ?? right.startedAt ?? 0;
  if (rightTime !== leftTime) {
    return rightTime - leftTime;
  }
  return right.id.localeCompare(left.id);
}

function failureStrategyPatchFromExecution(execution: ExecutionStep): Partial<AIFailureStrategyDraft> {
  const exitCodeText = execution.exitCode === undefined ? '' : `${zhCN.execution.exitCode}: ${execution.exitCode}`;
  const statusText = executionStatusLabel(execution.status, execution.rawStatus);
  const failureMessage = [statusText, exitCodeText].filter(Boolean).join(' · ');
  return {
    executionId: execution.id,
    failureMessage,
  };
}

function failureStrategyExecutionOptionLabel(execution: ExecutionStep): string {
  const statusText = executionStatusLabel(execution.status, execution.rawStatus);
  const exitCodeText = execution.exitCode === undefined ? '' : `${zhCN.execution.exitCode} ${execution.exitCode}`;
  return [execution.label || execution.id, statusText, exitCodeText].filter(Boolean).join(' · ');
}

function cleanFailureStrategyInput(input: AIActionRunInput): AIActionRunInput {
  return Object.fromEntries(
    Object.entries(input).filter(([, value]) => {
      if (value === undefined || value === null) {
        return false;
      }
      if (typeof value === 'string') {
        return value.trim() !== '';
      }
      return true;
    }),
  ) as AIActionRunInput;
}

function activePromptRegistryVersion(registry: PromptRegistry | null, promptId: string) {
  const prompt = registry?.prompts.find(item => item.id === promptId);
  if (!prompt) {
    return undefined;
  }
  return prompt.versions.find(version => version.id === prompt.activeVersion);
}

function latestFailureStrategyBlackboardItem(items: BlackboardItem[]): BlackboardItem | undefined {
  return [...items]
    .filter(item => item.kind === 'failure' || item.source === 'sisyphus.conclude_failure' || item.content.includes('失败归纳事实'))
    .sort(compareBlackboardItemNewestFirst)[0];
}

function latestFailureStrategyAgentTask(tasks: AgentTask[], blackboardItemId?: string): AgentTask | undefined {
  if (blackboardItemId) {
    return [...tasks]
      .filter(task => task.blackboardItemId === blackboardItemId)
      .sort(compareAgentTaskNewestFirst)[0];
  }
  return [...tasks]
    .filter(task => isStrategyMutatorAgentTask(task) || task.source === 'sisyphus.conclude_failure')
    .sort(compareAgentTaskNewestFirst)[0];
}

function AIStrategyStatePanel({
  blackboard,
  agentState,
  frontierQueue,
  frontierQueueQuery,
  status,
  busy,
  onRunStrategySelection,
  onOpenReference,
}: {
  blackboard: BlackboardState;
  agentState: AgentState;
  frontierQueue: FrontierQueue | null;
  frontierQueueQuery: FrontierQueueQuery;
  status: string;
  busy: boolean;
  onRunStrategySelection: () => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const strategyItems = [...blackboard.items]
    .filter(isStrategyBlackboardItem)
    .sort(compareBlackboardItemNewestFirst);
  const strategyTasks = [...agentState.tasks]
    .filter(isStrategyAgentTask)
    .sort(compareAgentTaskNewestFirst);
  const latestItem = strategyItems[0];
  const latestTask = strategyTasks[0];
  const selectorCount = strategyTasks.filter(isStrategySelectorAgentTask).length;
  const mutatorCount = strategyTasks.filter(isStrategyMutatorAgentTask).length;
  const references: AIContextReference[] = [
    ...strategyItems.slice(0, 3).map(item => ({
      id: item.id,
      kind: 'blackboard',
      label: item.title,
      title: item.title,
      path: item.filePath,
      source: zhCN.ai.strategyPanel,
    })),
    ...strategyTasks.slice(0, 3).map(task => ({
      id: task.id,
      kind: 'agentTask',
      label: task.title,
      title: task.title,
      path: task.filePath,
      source: zhCN.ai.strategyPanel,
    })),
  ];
  const meta = `${strategyItems.length} ${zhCN.ai.strategySelections} · ${strategyTasks.length} ${zhCN.ai.strategyTasks}`;
  return (
    <section className="ai-strategy-panel" data-ai-strategy-panel="true">
      <PanelTitle icon={GitBranch} title={zhCN.ai.strategyPanel} meta={meta || zhCN.ai.strategyPanelMeta} />
      <div className="ai-strategy-toolbar">
        <button
          type="button"
          className="primary-action"
          onClick={onRunStrategySelection}
          disabled={busy}
          data-ai-strategy-action="select"
        >
          <GitBranch size={14} />
          {busy ? zhCN.ai.strategySelecting : zhCN.ai.strategySelect}
        </button>
      </div>
      {status && (
        <div className="ai-strategy-status" data-ai-strategy-status="true">
          <CircleDot size={13} />
          <span>{status}</span>
        </div>
      )}
      <DetailGrid rows={[
        [zhCN.ai.strategyPanelGoal, frontierQueueQuery.goal || frontierQueue?.summary?.goal],
        [zhCN.ai.strategyPanelQueueItems, frontierQueue?.count],
        [zhCN.ai.frontierQueueReadyCount, frontierQueue?.summary?.readyCount],
        [zhCN.ai.frontierQueueBlockedCount, frontierQueue?.summary?.blockedCount],
        [zhCN.ai.strategySelections, strategyItems.length],
        [zhCN.ai.strategyTasks, strategyTasks.length],
        [zhCN.ai.strategySelectorTasks, selectorCount],
        [zhCN.ai.strategyMutatorTasks, mutatorCount],
        [zhCN.ai.strategyLatestSelection, latestItem?.title],
        [zhCN.ai.strategyLatestTask, latestTask?.title],
      ]} />
      <AIReferenceActions references={references} onOpenReference={onOpenReference} compact />
      <div className="ai-strategy-list">
        {strategyItems.length === 0 && strategyTasks.length === 0 && <EmptyState text={zhCN.ai.strategyNoState} />}
        {strategyItems.slice(0, 3).map(item => (
          <article
            key={item.id}
            className="ai-strategy-row"
            data-ai-strategy-blackboard-id={item.id}
          >
            <div className="ai-strategy-head">
              <strong>{item.title}</strong>
              <span>{blackboardStatusLabel(item.status)}</span>
            </div>
            <p>{contentPreview(item.content)}</p>
            <DetailGrid rows={[
              [zhCN.blackboard.id, item.id],
              [zhCN.blackboard.kind, blackboardKindLabel(item.kind)],
              [zhCN.blackboard.priority, blackboardPriorityLabel(item.priority)],
              [zhCN.blackboard.source, item.source],
              [zhCN.blackboard.updatedAt, formatDetailTime(item.updatedAt)],
            ]} />
          </article>
        ))}
        {strategyTasks.slice(0, 3).map(task => (
          <article
            key={task.id}
            className="ai-strategy-row"
            data-ai-strategy-task-id={task.id}
            data-ai-strategy-role={task.role}
          >
            <div className="ai-strategy-head">
              <strong>{task.title}</strong>
              <span>{agentStatusLabel(task.status)}</span>
            </div>
            <p>{task.goal}</p>
            <DetailGrid rows={[
              [zhCN.agents.id, task.id],
              [zhCN.agents.role, task.role],
              [zhCN.agents.priority, agentPriorityLabel(task.priority)],
              [zhCN.agents.source, task.source],
              [zhCN.agents.blackboardItemId, task.blackboardItemId],
              [zhCN.agents.executionId, task.executionId],
              [zhCN.agents.updatedAt, formatDetailTime(task.updatedAt)],
            ]} />
          </article>
        ))}
      </div>
    </section>
  );
}

type AICollaborationTopologyNodeKind = 'blackboard' | 'agentTask' | 'frontier';

type AICollaborationTopologyNode = {
  key: string;
  id: string;
  kind: AICollaborationTopologyNodeKind;
  label: string;
  status?: string;
  meta?: string;
  source?: string;
  updatedAt?: number;
  reference: AIContextReference;
  blackboardItem?: BlackboardItem;
  agentTask?: AgentTask;
  frontierItem?: FrontierPriorityItem;
};

type AICollaborationTopologyEdge = {
  id: string;
  kind: string;
  label: string;
  sourceKey: string;
  sourceKind: AICollaborationTopologyNodeKind;
  sourceId: string;
  sourceLabel: string;
  targetKey: string;
  targetKind: AICollaborationTopologyNodeKind;
  targetId: string;
  targetLabel: string;
};

type AICollaborationTopology = {
  nodes: AICollaborationTopologyNode[];
  edges: AICollaborationTopologyEdge[];
  blackboardNodes: AICollaborationTopologyNode[];
  agentNodes: AICollaborationTopologyNode[];
  frontierNodes: AICollaborationTopologyNode[];
  readyFrontierNode?: AICollaborationTopologyNode;
};

function AICollaborationTopologyPanel({
  blackboard,
  agentState,
  frontierQueue,
  frontierQueueQuery,
  conversation,
  frontierQueueBusy,
  strategySelectionBusy,
  actionRunningId,
  onRefreshFrontierQueue,
  onRunStrategySelection,
  onRunFrontierQueueAction,
  onRunFollowupAction,
  onOpenReference,
}: {
  blackboard: BlackboardState;
  agentState: AgentState;
  frontierQueue: FrontierQueue | null;
  frontierQueueQuery: FrontierQueueQuery;
  conversation: AIConversation | null;
  frontierQueueBusy: string;
  strategySelectionBusy: boolean;
  actionRunningId: string;
  onRefreshFrontierQueue: () => void;
  onRunStrategySelection: () => void;
  onRunFrontierQueueAction: (actionId: 'frontier.execute_next' | 'frontier.autopilot', item?: FrontierPriorityItem) => void;
  onRunFollowupAction: AIActionFollowupRunner;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const topology = useMemo(() => buildAICollaborationTopology(blackboard, agentState, frontierQueue), [blackboard, agentState, frontierQueue]);
  const hasConversationTrace = (conversation?.messages.length ?? 0) > 0;
  const topologyGoal = frontierQueueQuery.goal
    || frontierQueue?.summary?.goal
    || topology.readyFrontierNode?.frontierItem?.hypothesis
    || topology.readyFrontierNode?.frontierItem?.title
    || undefined;
  const harnessInput: AIActionRunInput = {
    goal: topologyGoal,
    source: 'desktop.ai.collaboration_topology',
  };
  const visibleNodes = topology.nodes.slice(0, 12);
  const visibleEdges = topology.edges.slice(0, 12);
  return (
    <section className="ai-collaboration-topology-panel" data-ai-collaboration-topology="true">
      <PanelTitle
        icon={Network}
        title={zhCN.ai.collaborationTopology}
        meta={`${topology.nodes.length} ${zhCN.ai.collaborationTopologyNodes} · ${topology.edges.length} ${zhCN.ai.collaborationTopologyEdges}`}
      />
      <div className="ai-collaboration-topology-toolbar">
        <button type="button" onClick={onRefreshFrontierQueue} disabled={frontierQueueBusy !== ''} data-ai-topology-action="refresh">
          <RefreshCw size={14} />
          {frontierQueueBusy === 'refresh' ? zhCN.ai.frontierQueueLoading : zhCN.ai.collaborationTopologyRefresh}
        </button>
        <button type="button" className="primary-action" onClick={onRunStrategySelection} disabled={strategySelectionBusy} data-ai-topology-action="select-strategy">
          <GitBranch size={14} />
          {strategySelectionBusy ? zhCN.ai.strategySelecting : zhCN.ai.collaborationTopologySelectStrategy}
        </button>
        <button
          type="button"
          onClick={() => topology.readyFrontierNode?.frontierItem && onRunFrontierQueueAction('frontier.execute_next', topology.readyFrontierNode.frontierItem)}
          disabled={frontierQueueBusy !== '' || !topology.readyFrontierNode?.frontierItem}
          data-ai-topology-action="execute-next"
        >
          <ChevronRight size={14} />
          {frontierQueueBusy !== '' && frontierQueueBusy !== 'refresh' ? zhCN.ai.frontierQueueExecuteRunning : zhCN.ai.collaborationTopologyExecuteNext}
        </button>
        <button
          type="button"
          onClick={() => onRunFollowupAction('harness.cases.from_ai_conversation', harnessInput)}
          disabled={!hasConversationTrace || actionRunningId === 'harness.cases.from_ai_conversation'}
          data-ai-topology-action="settle-harness"
        >
          <ClipboardCheck size={14} />
          {actionRunningId === 'harness.cases.from_ai_conversation' ? zhCN.ai.collaborationTopologySettlingHarness : zhCN.ai.collaborationTopologySettleHarness}
        </button>
      </div>
      <DetailGrid rows={[
        [zhCN.ai.collaborationTopologyBlackboardNodes, topology.blackboardNodes.length],
        [zhCN.ai.collaborationTopologyAgentNodes, topology.agentNodes.length],
        [zhCN.ai.collaborationTopologyFrontierNodes, topology.frontierNodes.length],
        [zhCN.ai.frontierQueueReadyCount, frontierQueue?.summary?.readyCount],
        [zhCN.ai.frontierQueueBlockedCount, frontierQueue?.summary?.blockedCount],
        [zhCN.ai.collaborationTopologyHarnessSource, hasConversationTrace ? zhCN.ai.collaborationTopologyHarnessReady : zhCN.ai.collaborationTopologyHarnessMissing],
      ]} />
      <div className="ai-collaboration-topology-body">
        <div className="ai-collaboration-topology-nodes">
          <strong>{zhCN.ai.collaborationTopologyNodeList}</strong>
          {visibleNodes.length === 0 && <EmptyState text={zhCN.ai.collaborationTopologyEmpty} />}
          {visibleNodes.map(node => (
            <article
              key={node.key}
              data-ai-topology-node="true"
              data-ai-topology-node-kind={node.kind}
              data-ai-topology-node-id={node.id}
            >
              <div className="ai-collaboration-topology-head">
                <div>
                  <span>{collaborationTopologyNodeKindLabel(node.kind)}</span>
                  <strong>{node.label}</strong>
                </div>
                <button type="button" onClick={() => onOpenReference(node.reference)}>
                  <ChevronRight size={13} />
                  {zhCN.ai.jumpToReference}
                </button>
              </div>
              <DetailGrid rows={[
                [zhCN.ai.collaborationItemStatus, collaborationTopologyStatusLabel(node)],
                [zhCN.ai.collaborationItemMeta, node.meta],
                [zhCN.ai.collaborationSourcePath, node.source],
                [zhCN.ai.collaborationUpdatedAt, node.updatedAt ? formatDetailTime(node.updatedAt) : undefined],
              ]} />
              {node.kind === 'frontier' && isExplicitlyReadyFrontierItem(node.frontierItem) && (
                <button
                  type="button"
                  className="ai-collaboration-topology-inline-action"
                  onClick={() => onRunFrontierQueueAction('frontier.execute_next', node.frontierItem)}
                  disabled={frontierQueueBusy !== ''}
                  data-ai-topology-action="execute-node"
                >
                  <Play size={13} />
                  {zhCN.ai.frontierQueueExecuteNext}
                </button>
              )}
            </article>
          ))}
        </div>
        <div className="ai-collaboration-topology-edges">
          <strong>{zhCN.ai.collaborationTopologyEdgeList}</strong>
          {visibleEdges.length === 0 && <EmptyState text={zhCN.ai.collaborationTopologyEdgesEmpty} />}
          {visibleEdges.map(edge => (
            <article
              key={edge.id}
              data-ai-topology-edge="true"
              data-ai-topology-edge-kind={edge.kind}
              data-ai-topology-edge-source={edge.sourceId}
              data-ai-topology-edge-target={edge.targetId}
            >
              <div className="ai-collaboration-topology-edge-line">
                <span>{edge.label}</span>
                <strong>{edge.sourceLabel}</strong>
                <small>{zhCN.ai.collaborationTopologyEdgeArrow}</small>
                <strong>{edge.targetLabel}</strong>
              </div>
              <DetailGrid rows={[
                [zhCN.ai.collaborationTopologySourceNode, `${collaborationTopologyNodeKindLabel(edge.sourceKind)} · ${edge.sourceId}`],
                [zhCN.ai.collaborationTopologyTargetNode, `${collaborationTopologyNodeKindLabel(edge.targetKind)} · ${edge.targetId}`],
              ]} />
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

function buildAICollaborationTopology(blackboard: BlackboardState, agentState: AgentState, frontierQueue: FrontierQueue | null): AICollaborationTopology {
  const nodes: AICollaborationTopologyNode[] = [];
  const nodeByKey = new Map<string, AICollaborationTopologyNode>();
  const addNode = (node: AICollaborationTopologyNode) => {
    if (nodeByKey.has(node.key)) {
      return;
    }
    nodeByKey.set(node.key, node);
    nodes.push(node);
  };
  blackboard.items.forEach(item => {
    addNode({
      key: collaborationTopologyNodeKey('blackboard', item.id),
      id: item.id,
      kind: 'blackboard',
      label: item.title || item.id,
      status: item.status,
      meta: [blackboardKindLabel(item.kind), blackboardPriorityLabel(item.priority), blackboardRelationMeta(item)].filter(Boolean).join(' · '),
      source: item.source || item.filePath,
      updatedAt: item.updatedAt || item.createdAt,
      reference: {
        id: item.id,
        kind: 'blackboard',
        label: item.title || item.id,
        title: item.title,
        path: item.filePath,
        source: zhCN.ai.collaborationTopology,
      },
      blackboardItem: item,
    });
  });
  agentState.tasks.forEach(task => {
    addNode({
      key: collaborationTopologyNodeKey('agentTask', task.id),
      id: task.id,
      kind: 'agentTask',
      label: task.title || task.id,
      status: task.status,
      meta: [task.role, agentPriorityLabel(task.priority), task.blackboardItemId].filter(Boolean).join(' · '),
      source: task.source || task.filePath,
      updatedAt: task.updatedAt || task.createdAt,
      reference: {
        id: task.id,
        kind: 'agentTask',
        label: task.title || task.id,
        title: task.title,
        path: task.filePath,
        source: zhCN.ai.collaborationTopology,
      },
      agentTask: task,
    });
  });
  (frontierQueue?.items ?? []).forEach(item => {
    const id = item.id?.trim();
    if (!id) {
      return;
    }
    const label = item.title || item.hypothesis || item.target || id;
    addNode({
      key: collaborationTopologyNodeKey('frontier', id),
      id,
      kind: 'frontier',
      label,
      status: item.status || (item.ready === true ? 'ready' : item.ready === false ? 'blocked' : undefined),
      meta: [
        item.rank ? `${zhCN.aiActions.frontierRank} ${item.rank}` : undefined,
        formatFrontierScore(item.score) ? `${zhCN.aiActions.frontierScore} ${formatFrontierScore(item.score)}` : undefined,
        item.ready === true ? zhCN.ai.frontierQueueReady : item.ready === false ? zhCN.ai.frontierQueueBlocked : undefined,
        item.priority ? localizedPriorityLabel(item.priority) : undefined,
      ].filter(Boolean).join(' · '),
      source: item.source || item.sourceKind || item.filePath,
      reference: {
        id,
        kind: 'frontierDependency',
        label,
        title: label,
        path: item.filePath,
        source: zhCN.ai.collaborationTopology,
      },
      frontierItem: item,
    });
  });

  const edges: AICollaborationTopologyEdge[] = [];
  const edgeKeys = new Set<string>();
  const addEdge = (
    kind: string,
    label: string,
    sourceKind: AICollaborationTopologyNodeKind,
    sourceId: string | undefined,
    targetKind: AICollaborationTopologyNodeKind,
    targetId: string | undefined,
  ) => {
    const normalizedSourceId = sourceId?.trim();
    const normalizedTargetId = targetId?.trim();
    if (!normalizedSourceId || !normalizedTargetId || normalizedSourceId === normalizedTargetId) {
      return;
    }
    const sourceKey = collaborationTopologyNodeKey(sourceKind, normalizedSourceId);
    const targetKey = collaborationTopologyNodeKey(targetKind, normalizedTargetId);
    const edgeKey = `${kind}:${sourceKey}->${targetKey}`;
    if (edgeKeys.has(edgeKey)) {
      return;
    }
    edgeKeys.add(edgeKey);
    const sourceNode = nodeByKey.get(sourceKey);
    const targetNode = nodeByKey.get(targetKey);
    edges.push({
      id: edgeKey,
      kind,
      label,
      sourceKey,
      sourceKind,
      sourceId: normalizedSourceId,
      sourceLabel: sourceNode?.label || normalizedSourceId,
      targetKey,
      targetKind,
      targetId: normalizedTargetId,
      targetLabel: targetNode?.label || normalizedTargetId,
    });
  };

  blackboard.items.forEach(item => {
    (item.dependencyIds ?? []).forEach(dependencyId => addEdge('blackboard_dependency', zhCN.ai.collaborationTopologyDependencyEdge, 'blackboard', item.id, 'blackboard', dependencyId));
    (item.dependentIds ?? []).forEach(dependentId => addEdge('blackboard_dependent', zhCN.ai.collaborationTopologyDependentEdge, 'blackboard', item.id, 'blackboard', dependentId));
  });
  agentState.tasks.forEach(task => {
    addEdge('agent_blackboard', zhCN.ai.collaborationTopologyAgentBlackboardEdge, 'agentTask', task.id, 'blackboard', task.blackboardItemId);
  });
  (frontierQueue?.items ?? []).forEach(item => {
    const id = item.id?.trim();
    if (!id) {
      return;
    }
    addEdge('frontier_blackboard', zhCN.ai.collaborationTopologyFrontierBlackboardEdge, 'frontier', id, 'blackboard', item.blackboardItemId);
    addEdge('frontier_agent', zhCN.ai.collaborationTopologyFrontierAgentEdge, 'frontier', id, 'agentTask', item.agentTaskId);
    (item.dependencyIds ?? []).forEach(dependencyId => addEdge('frontier_dependency', zhCN.ai.collaborationTopologyDependencyEdge, 'frontier', id, 'blackboard', dependencyId));
    (item.blockedByIds ?? []).forEach(blockedById => addEdge('frontier_blocked_by', zhCN.ai.collaborationTopologyBlockedByEdge, 'frontier', id, 'blackboard', blockedById));
  });

  const blackboardNodes = nodes.filter(node => node.kind === 'blackboard');
  const agentNodes = nodes.filter(node => node.kind === 'agentTask');
  const frontierNodes = nodes.filter(node => node.kind === 'frontier');
  return {
    nodes: nodes.sort(compareAICollaborationTopologyNode),
    edges,
    blackboardNodes,
    agentNodes,
    frontierNodes,
    readyFrontierNode: frontierNodes.find(node => isExplicitlyReadyFrontierItem(node.frontierItem)),
  };
}

function isExplicitlyReadyFrontierItem(item?: FrontierPriorityItem): item is FrontierPriorityItem {
  if (!item || item.blockedReason) {
    return false;
  }
  return item.ready === true || normalizeRuntimeLabelKey(item.status) === 'ready';
}

function collaborationTopologyNodeKey(kind: AICollaborationTopologyNodeKind, id: string): string {
  return `${kind}:${id.trim()}`;
}

function compareAICollaborationTopologyNode(left: AICollaborationTopologyNode, right: AICollaborationTopologyNode): number {
  if (left.kind === 'frontier' && right.kind !== 'frontier') {
    return -1;
  }
  if (right.kind === 'frontier' && left.kind !== 'frontier') {
    return 1;
  }
  return (right.updatedAt ?? 0) - (left.updatedAt ?? 0);
}

function collaborationTopologyNodeKindLabel(kind: AICollaborationTopologyNodeKind): string {
  switch (kind) {
    case 'blackboard':
      return zhCN.ai.collaborationTopologyBlackboardNode;
    case 'agentTask':
      return zhCN.ai.collaborationTopologyAgentNode;
    case 'frontier':
      return zhCN.ai.collaborationTopologyFrontierNode;
  }
}

function collaborationTopologyStatusLabel(node: AICollaborationTopologyNode): string | undefined {
  if (!node.status) {
    return undefined;
  }
  if (node.kind === 'blackboard') {
    return blackboardStatusLabel(node.status);
  }
  if (node.kind === 'agentTask') {
    return agentStatusLabel(node.status);
  }
  return frontierQueueStatusLabel(node.status);
}

function AIFrontierDependenciesPanel({
  dependencies,
  status,
  busy,
  onRefresh,
  onRunDependency,
  onOpenReference,
}: {
  dependencies: FrontierDependencySelection | null;
  status: string;
  busy: boolean;
  onRefresh: () => void;
  onRunDependency: (cluster: FrontierDependencyCluster) => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const summary = dependencies?.summary;
  const clusters = dependencies?.clusters ?? [];
  const statusMeta = dependencies
    ? `${frontierDependencyStatusLabel(dependencies.status || summary?.status)} · ${dependencies.count} ${zhCN.ai.frontierDependenciesClusterCount}`
    : zhCN.ai.frontierDependenciesMeta;
  const references = [
    ...clusters.slice(0, 3).map(cluster => frontierDependencyReference('frontierDependency', cluster.dependencyId || cluster.id, cluster.dependencyTitle || cluster.dependencyId)),
    ...(dependencies?.blackboardItems ?? []).slice(0, 3).map(item => frontierDependencyReference('blackboard', item.id, item.title, item.filePath)),
    ...(dependencies?.agentTasks ?? []).slice(0, 3).map(task => frontierDependencyReference('agentTask', task.id, task.title, task.filePath)),
  ];
  return (
    <section className="ai-frontier-dependencies-panel" data-ai-frontier-dependencies="true">
      <PanelTitle icon={GitBranch} title={zhCN.ai.frontierDependencies} meta={statusMeta} />
      <div className="ai-frontier-dependencies-toolbar">
        <button type="button" onClick={onRefresh} disabled={busy} data-frontier-dependency-action="refresh">
          <RefreshCw size={14} />
          {busy ? zhCN.ai.frontierDependenciesLoading : zhCN.ai.frontierDependenciesRefresh}
        </button>
      </div>
      {status && (
        <div className="ai-frontier-dependencies-status" data-frontier-dependencies-status="true">
          <GitBranch size={13} />
          <span>{status}</span>
        </div>
      )}
      {!dependencies && <EmptyState text={status || zhCN.ai.frontierDependenciesMissing} />}
      {dependencies && (
        <>
          <DetailGrid rows={[
            [zhCN.ai.frontierDependenciesSummary, summary?.summary],
            [zhCN.ai.frontierDependenciesSource, dependencies.queueSource || summary?.source],
            [zhCN.ai.frontierDependenciesStatus, frontierDependencyStatusLabel(dependencies.status || summary?.status)],
            [zhCN.ai.frontierDependenciesQueueStatus, frontierQueueStatusLabel(summary?.queueStatus ?? dependencies.queue.queueStatus)],
            [zhCN.ai.frontierDependenciesQueueItems, summary?.queueItems],
            [zhCN.ai.frontierDependenciesBlockedItems, summary?.blockedItems],
            [zhCN.ai.frontierDependenciesClusterCount, summary?.clusterCount],
            [zhCN.ai.frontierDependenciesCandidateCount, summary?.candidateCount],
            [zhCN.ai.frontierDependenciesBlockedFrontierItems, summary?.blockedFrontierItemCount],
            [zhCN.ai.frontierDependenciesReadyCount, summary?.readyDependencyCount],
            [zhCN.ai.frontierDependenciesMissingCount, summary?.missingDependencyCount],
            [zhCN.ai.frontierDependenciesLinkedTasks, summary?.linkedAgentTaskCount],
            [zhCN.ai.frontierDependenciesUnlockValue, formatFrontierScore(summary?.unlockValue)],
          ]} />
          <AIReferenceActions references={references} onOpenReference={onOpenReference} compact />
          <div className="ai-frontier-dependencies-list">
            {clusters.length === 0 && <EmptyState text={zhCN.ai.frontierDependenciesEmpty} />}
            {clusters.map(cluster => (
              <article
                key={cluster.id || cluster.dependencyId}
                data-frontier-dependency-cluster-id={cluster.dependencyId}
                data-frontier-dependency-status={cluster.dependencyStatus}
              >
                <div className="ai-frontier-dependencies-head">
                  <div>
                    <strong>{cluster.dependencyTitle || cluster.dependencyId}</strong>
                    <span>{cluster.reason || cluster.suggestedGoal || zhCN.ai.frontierDependenciesClusterMeta}</span>
                  </div>
                  <div className="ai-frontier-dependencies-actions">
                    {cluster.dependencyId && (
                      <button
                        type="button"
                        onClick={() => onOpenReference(frontierDependencyReference('frontierDependency', cluster.dependencyId, cluster.dependencyTitle || cluster.suggestedGoal))}
                        data-frontier-dependency-reference-id={cluster.dependencyId}
                      >
                        <GitBranch size={13} />
                        {zhCN.ai.frontierDependenciesOpenDependency}
                      </button>
                    )}
                    {cluster.suggestedBlackboardItemId && (
                      <button
                        type="button"
                        onClick={() => onOpenReference(frontierDependencyReference('blackboard', cluster.suggestedBlackboardItemId as string, cluster.dependencyTitle))}
                        data-frontier-dependency-unblock-id={cluster.suggestedBlackboardItemId}
                      >
                        <GitBranch size={13} />
                        {zhCN.ai.frontierDependenciesOpenDependency}
                      </button>
                    )}
                    {cluster.suggestedAgentTaskId && (
                      <button
                        type="button"
                        onClick={() => onOpenReference(frontierDependencyReference('agentTask', cluster.suggestedAgentTaskId as string, cluster.dependencyTitle))}
                        data-frontier-dependency-unblock-id={cluster.suggestedAgentTaskId}
                      >
                        <UsersRound size={13} />
                        {zhCN.ai.frontierDependenciesOpenTask}
                      </button>
                    )}
                    <button
                      type="button"
                      className="primary-action"
                      onClick={() => onRunDependency(cluster)}
                      disabled={busy || (!cluster.suggestedAgentTaskId && !cluster.suggestedBlackboardItemId && !cluster.dependencyId)}
                      data-frontier-dependency-action="execute-next"
                      data-frontier-dependency-unblock-id={cluster.suggestedAgentTaskId || cluster.suggestedBlackboardItemId || cluster.dependencyId}
                    >
                      <ChevronRight size={13} />
                      {busy ? zhCN.ai.frontierDependenciesExecuteRunning : zhCN.ai.frontierDependenciesExecute}
                    </button>
                  </div>
                </div>
                <DetailGrid rows={[
                  [zhCN.ai.frontierDependenciesDependencyId, cluster.dependencyId],
                  [zhCN.ai.frontierDependenciesDependencyStatus, frontierDependencyItemStatusLabel(cluster)],
                  [zhCN.ai.frontierDependenciesUnlockCount, cluster.unlockCount],
                  [zhCN.ai.frontierDependenciesUnlockValue, formatFrontierScore(cluster.unlockValue)],
                  [zhCN.aiActions.frontierScore, formatFrontierScore(cluster.score)],
                  [zhCN.ai.frontierDependenciesSuggestedAction, cluster.suggestedActionId ? `${cluster.suggestedActionId} · ${cluster.suggestedAction || ''}` : cluster.suggestedAction],
                  [zhCN.ai.frontierDependenciesSuggestedGoal, cluster.suggestedGoal],
                ]} />
                <div className="ai-frontier-dependencies-blocked">
                  <span>{zhCN.ai.frontierDependenciesUnlocks}</span>
                  {cluster.blockedItems.length === 0 && <small>{zhCN.ai.frontierDependenciesNoBlockedItems}</small>}
                  {cluster.blockedItems.map(item => {
                    const id = item.blackboardItemId || item.sourceId || item.id || item.title || '';
                    return (
                      <button
                        key={id}
                        type="button"
                        onClick={() => id && onOpenReference(frontierDependencyReference(item.blackboardItemId ? 'blackboard' : 'frontierDependency', id, item.title || item.hypothesis))}
                        data-frontier-dependency-blocked-id={id}
                      >
                        <AlertCircle size={13} />
                        {item.title || item.hypothesis || id}
                      </button>
                    );
                  })}
                </div>
                {cluster.linkedAgentTasks.length > 0 && (
                  <div className="ai-frontier-dependencies-blocked">
                    <span>{zhCN.ai.frontierDependenciesLinkedTasks}</span>
                    {cluster.linkedAgentTasks.map(task => (
                      <button
                        key={task.id}
                        type="button"
                        onClick={() => onOpenReference(frontierDependencyReference('agentTask', task.id, task.title, task.filePath))}
                        data-frontier-dependency-task-id={task.id}
                      >
                        <UsersRound size={13} />
                        {task.title || task.id}
                      </button>
                    ))}
                  </div>
                )}
              </article>
            ))}
          </div>
        </>
      )}
    </section>
  );
}

function AIFrontierMonitorPanel({
  monitor,
  status,
  busy,
  onRefresh,
  onOpenFile,
  onOpenReference,
}: {
  monitor: FrontierMonitor | null;
  status: string;
  busy: boolean;
  onRefresh: () => void;
  onOpenFile: (filePath: string) => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const summary = monitor?.summary;
  const monitorState = frontierMonitorStatusLabel(summary?.status);
  const statusTone = frontierMonitorStatusTone(summary?.status);
  const queueReferences = [
    ...(monitor?.queue.blackboardItems ?? []).slice(0, 2).map(item => frontierMonitorReference('blackboard', item.id, item.title, item.filePath)),
    ...(monitor?.queue.agentTasks ?? []).slice(0, 2).map(task => frontierMonitorReference('agentTask', task.id, task.title, task.filePath)),
  ];
  return (
    <section className="ai-frontier-monitor-panel" data-ai-frontier-monitor="true">
      <PanelTitle icon={Activity} title={zhCN.ai.frontierMonitor} meta={summary?.summary || zhCN.ai.frontierMonitorMeta} />
      <div className="ai-frontier-monitor-toolbar">
        <button type="button" onClick={onRefresh} disabled={busy} data-frontier-monitor-action="refresh">
          <RefreshCw size={14} />
          {busy ? zhCN.ai.frontierMonitorLoading : zhCN.ai.frontierMonitorRefresh}
        </button>
      </div>
      {(status || summary) && (
        <div className="ai-frontier-monitor-status" data-status={statusTone} data-frontier-monitor-status="true">
          <span aria-hidden="true" />
          <strong>{monitorState}</strong>
          {status && <small>{status}</small>}
        </div>
      )}
      {!monitor && <EmptyState text={status || zhCN.ai.frontierMonitorMissing} />}
      {monitor && (
        <>
          <DetailGrid rows={[
            [zhCN.ai.frontierMonitorStatus, monitorState],
            [zhCN.ai.frontierMonitorSource, summary?.source],
            [zhCN.ai.frontierMonitorQueueStatus, frontierQueueStatusLabel(summary?.queueStatus ?? monitor.queue.queueStatus)],
            [zhCN.ai.frontierMonitorQueueItems, summary?.queueItems],
            [zhCN.ai.frontierMonitorReadyItems, summary?.readyItems],
            [zhCN.ai.frontierMonitorBlockedItems, summary?.blockedItems],
            [zhCN.ai.frontierMonitorActiveAgentTasks, summary?.activeAgentTasks],
            [zhCN.ai.frontierMonitorActivePlannerPlans, summary?.activePlannerPlans],
            [zhCN.ai.frontierMonitorRunningExecutions, summary?.runningExecutions],
            [zhCN.ai.frontierMonitorRecentEvents, summary?.recentEvents],
            [zhCN.ai.frontierMonitorLastUpdatedAt, formatDetailTime(summary?.lastUpdatedAt)],
          ]} />
          <AIReferenceActions references={queueReferences} onOpenReference={onOpenReference} compact />
          <div className="ai-frontier-monitor-sections">
            <AIFrontierMonitorTaskList tasks={monitor.activeAgentTasks} onOpenFile={onOpenFile} onOpenReference={onOpenReference} />
            <AIFrontierMonitorPlanList plans={monitor.activePlannerPlans} onOpenFile={onOpenFile} onOpenReference={onOpenReference} />
            <AIFrontierMonitorExecutionList executions={monitor.runningExecutions} onOpenFile={onOpenFile} onOpenReference={onOpenReference} />
            <AIFrontierMonitorEventList events={monitor.recentAgentEvents} onOpenFile={onOpenFile} onOpenReference={onOpenReference} />
          </div>
        </>
      )}
    </section>
  );
}

