function aiActionWorkspaceFileActions(actionResult: AIActionRunResponse['result']): AIActionWorkspaceFileAction[] {
  const actions: AIActionWorkspaceFileAction[] = [];
  const pushAction = (kind: string, label: string, path?: string, line?: number) => {
    const normalizedPath = (path ?? '').trim();
    if (!normalizedPath) {
      return;
    }
    const key = `${kind}:${normalizedPath}:${line ?? ''}`;
    if (actions.some(action => action.key === key)) {
      return;
    }
    actions.push({ key, kind, label, path: normalizedPath, line });
  };

  const directFilePath = actionResult.file?.path || (actionResult.kind === 'file' || actionResult.kind === 'patch' ? actionResult.path : undefined);
  pushAction(actionResult.patch ? 'patch-file' : 'workspace-file', actionResult.patch ? zhCN.aiActions.openPatchFile : zhCN.aiActions.openWorkspaceFile, directFilePath);
  pushAction('target-file', zhCN.aiActions.openTargetFile, actionResult.targetPath);
  pushAction('deleted-file', zhCN.aiActions.openDeletedFile, actionResult.deletedFile?.path);
  (actionResult.fileContents ?? [])
    .slice(0, 20)
    .forEach(file => pushAction('workspace-file', zhCN.aiActions.openWorkspaceFile, file.path));
  (actionResult.files ?? [])
    .filter(file => file.kind !== 'directory')
    .slice(0, 20)
    .forEach(file => pushAction('workspace-file', zhCN.aiActions.openWorkspaceFile, file.path));
  (actionResult.searchResults ?? [])
    .slice(0, 20)
    .forEach(hit => pushAction('search-result', zhCN.aiActions.openSearchResultFile, hit.path, hit.line));

  return actions;
}

function AIActionStructuredReferenceActions({
  references,
  onOpenReference,
  compact = true,
}: {
  references: AIContextReference[];
  onOpenReference: (reference: AIContextReference) => void;
  compact?: boolean;
}) {
  if (references.length === 0) {
    return null;
  }
  return (
    <div data-ai-action-result-references="true">
      <AIReferenceActions references={references} onOpenReference={onOpenReference} compact={compact} />
    </div>
  );
}

function aiActionResultReferences(result: AIActionRunResponse): AIContextReference[] {
  const references: AIContextReference[] = [...(result.message.contextReferences ?? [])];
  const actionResult = result.result;
  appendFileReference(references, actionResult.path, zhCN.aiActions.resultPath, 'report');
  appendFileReference(references, actionResult.targetPath, zhCN.aiActions.resultTargetPath, 'file');
  appendFileReference(references, actionResult.file?.path, zhCN.aiActions.openWorkspaceFile, 'file');
  appendFileReference(references, actionResult.deletedFile?.path, zhCN.aiActions.openDeletedFile, 'file');
  appendReportExportReferences(references, actionResult.reportExport);
  if (actionResult.evidenceItem) {
    appendEvidenceItemReferences(references, actionResult.evidenceItem);
  }
  (actionResult.evidenceItems ?? []).forEach(item => appendEvidenceItemReferences(references, item));
  if (actionResult.reportFinding) {
    appendReportFindingReferences(references, actionResult.reportFinding);
  }
  (actionResult.reportFindings ?? []).forEach(finding => appendReportFindingReferences(references, finding));
  if (result.execution) {
    appendExecutionReferences(references, result.execution);
  }
  (actionResult.executions ?? []).forEach(execution => appendExecutionReferences(references, execution));
  (actionResult.executionLogs ?? []).forEach(log => appendFileReference(references, log.path, zhCN.execution.openLogFile, 'executionLog', log.id));
  (actionResult.executionArtifacts ?? []).forEach(artifact => appendFileReference(references, artifact.filePath, zhCN.execution.openArtifactFile, 'artifact', artifact.path || artifact.name));
  if (actionResult.harnessResult) {
    appendHarnessResultReferences(references, actionResult.harnessResult);
  }
  (actionResult.harnessResults ?? []).forEach(item => appendHarnessResultReferences(references, item));
  if (actionResult.agentProviderRun) {
    references.push(...agentProviderRunReferences(actionResult.agentProviderRun));
  }
  actionResult.eventlogEvents?.runs.forEach(run => references.push(...referencesForEventlogRun(run)));
  actionResult.eventlogEvents?.events.forEach(event => references.push(...referencesForEventlogEvent(event)));
  appendPromptReferences(references, actionResult.prompt, actionResult.promptVersion, actionResult.promptRegistry?.path ?? actionResult.path);
  if (actionResult.promptComparison) {
    appendHarnessResultReferences(references, actionResult.promptComparison.baseResult);
    appendHarnessResultReferences(references, actionResult.promptComparison.targetResult);
  }
  actionResult.batchComparison?.results?.forEach(item => appendHarnessResultReferences(references, item));
  actionResult.batchComparison?.items.forEach(item => appendHarnessResultReferences(references, item.result));
  appendRuntimeWorkerResultReferences(references, actionResult);
  return dedupeAIContextReferences(references);
}

function appendRuntimeWorkerResultReferences(
  references: AIContextReference[],
  result: AIActionRunResponse['result'],
) {
  const workers = [
    ...(result.runtimeWorkerState?.workers ?? []),
    ...(result.runtimeWorkers ?? []),
  ];
  workers.forEach(worker => {
    appendFileReference(references, worker.path, `${zhCN.runtimeWorkers.path}: ${worker.workerId}`, 'file');
  });

  const orchestrations = mergeRuntimeWorkerOrchestrations([
    ...(result.runtimeWorkerState?.orchestrations ?? []),
    ...(result.runtimeWorkerOrchestrations ?? []),
  ], result.runtimeWorkerOrchestration);
  orchestrations.forEach(orchestration => {
    runtimeWorkerOrchestrationPaths(orchestration).forEach(item => {
      appendFileReference(references, item.path, `${item.label}: ${orchestration.runId}`, 'file');
    });
  });
}

function appendEvidenceItemReferences(references: AIContextReference[], item: EvidenceItem) {
  appendReference(references, 'evidence', item.id, item.title, item.filePath || item.path, item.summary, item.source);
  appendExecutionReference(references, item.executionId);
  appendFileReference(references, item.artifactPath, zhCN.execution.openArtifactFile, 'artifact');
  appendReference(references, 'graphNode', item.graphNodeId, zhCN.ai.referenceTargetGraph, undefined, item.title, item.source);
  appendReference(references, 'replayEvent', item.replayEventId, zhCN.ai.referenceTargetReplay, undefined, item.title, item.source);
  appendAIProvenanceReferences(references, item);
}

function referencesForEvidenceItem(item: EvidenceItem): AIContextReference[] {
  const references: AIContextReference[] = [];
  appendEvidenceItemReferences(references, item);
  return dedupeAIContextReferences(references);
}

function appendReportFindingReferences(references: AIContextReference[], finding: ReportFinding) {
  appendReference(references, 'reportFinding', finding.id, finding.title, finding.path, finding.endpoint, finding.source);
  appendFileReference(references, finding.filePath, zhCN.navigation.openEvidenceFile, 'evidence', finding.id);
  appendFileReference(references, finding.path, zhCN.aiActions.openResultFile, 'report', finding.id);
  appendExecutionReference(references, finding.executionId);
  appendReference(references, 'graphNode', finding.nodeId, zhCN.ai.referenceTargetGraph, undefined, finding.title, finding.source);
  appendReference(references, 'replayEvent', finding.replayEventId, zhCN.ai.referenceTargetReplay, undefined, finding.title, finding.source);
  appendAIProvenanceReferences(references, finding);
}

function appendAIProvenanceReferences(references: AIContextReference[], item: Pick<EvidenceItem | ReportFinding, 'agentTaskId' | 'blackboardItemId' | 'promptId' | 'promptVersionId' | 'aiMessageIds' | 'toolCallIds' | 'actionTraceIds' | 'source'>) {
  appendReference(references, 'agentTask', item.agentTaskId, zhCN.ai.referenceTargetAgent, undefined, item.agentTaskId, item.source);
  appendReference(references, 'blackboard', item.blackboardItemId, zhCN.ai.referenceTargetBlackboard, undefined, item.blackboardItemId, item.source);
  appendReference(references, 'prompt', item.promptId, zhCN.ai.referenceTargetPrompt, undefined, item.promptId, item.source);
  if (item.promptVersionId) {
    appendReference(references, 'promptVersion', `${item.promptId || ''}:${item.promptVersionId}`, zhCN.ai.referenceTargetPrompt, undefined, item.promptVersionId, item.source);
  }
  (item.aiMessageIds ?? []).forEach(id => appendReference(references, 'aiMessage', id, zhCN.ai.referenceTargetAIMessage, undefined, id, item.source));
  (item.toolCallIds ?? []).forEach(id => appendReference(references, 'aiActionTrace', id, zhCN.ai.referenceTargetToolCall, undefined, id, item.source));
  (item.actionTraceIds ?? []).forEach(id => appendReference(references, 'aiActionTrace', id, zhCN.ai.referenceTargetActionTrace, undefined, id, item.source));
}

function referencesForReportFinding(finding: ReportFinding): AIContextReference[] {
  const references: AIContextReference[] = [];
  appendReportFindingReferences(references, finding);
  return dedupeAIContextReferences(references);
}

function appendHarnessResultReferences(references: AIContextReference[], result?: HarnessResult) {
  if (!result) {
    return;
  }
  references.push(...result.references);
  appendReference(references, 'harnessResult', result.id, result.caseTitle, undefined, result.summary, 'harness.results');
  appendExecutionReference(references, result.executionId);
  appendFileReference(references, result.logPath, zhCN.harness.openLogFile, 'executionLog', result.id);
  appendFileReference(references, result.artifactDir, zhCN.harness.openArtifactDir, 'artifactDir', result.id);
  appendFileReference(references, result.filePath, zhCN.harness.openFile, 'file', result.id);
  appendFileReference(references, result.snapshotPath, zhCN.harness.snapshotPath, 'artifact', result.snapshotId || result.id);
  if (result.promptId || result.promptVersionId) {
    appendReference(
      references,
      result.promptVersionId ? 'promptVersion' : 'prompt',
      result.promptVersionId ? `${result.promptId || ''}:${result.promptVersionId}` : result.promptId,
      zhCN.aiActions.promptReferenceResult,
      undefined,
      result.promptVersionId || result.promptId,
      'harness.results',
    );
  }
}

function referencesForHarnessResult(result: HarnessResult): AIContextReference[] {
  const references: AIContextReference[] = [];
  appendHarnessResultReferences(references, result);
  return dedupeAIContextReferences(references);
}

function referencesForEventlogRun(run: EventlogRun): AIContextReference[] {
  const references: AIContextReference[] = [];
  appendReference(references, 'replayRun', run.id, zhCN.aiActions.eventlogRunInput, undefined, run.status, 'eventlog.query');
  return references;
}

function referencesForEventlogEvent(event: ReplayEvent): AIContextReference[] {
  const references: AIContextReference[] = [];
  appendReference(references, 'replayEvent', event.id, eventlogTypeLabel(event.event || event.type), undefined, event.detail, 'eventlog.query');
  appendReference(references, 'replayRun', event.runId, zhCN.aiActions.eventlogRunInput, undefined, event.type, 'eventlog.query');
  appendExecutionReference(references, event.executionId);
  appendFileReference(references, event.filePath, zhCN.harness.filePath, 'file', event.id);
  return dedupeAIContextReferences(references);
}

function appendPromptReferences(
  references: AIContextReference[],
  prompt?: PromptRegistry['prompts'][number],
  version?: PromptRegistry['prompts'][number]['versions'][number],
  registryPath?: string,
) {
  appendFileReference(references, registryPath, zhCN.aiActions.promptRegistryPath, 'file');
  if (prompt) {
    appendReference(references, 'prompt', prompt.id, prompt.title, undefined, prompt.kind, 'prompt.registry');
  }
  if (version) {
    appendReference(references, 'promptVersion', `${prompt?.id || ''}:${version.id}`, version.title, undefined, version.id, 'prompt.registry');
  }
}

function appendReportExportReferences(references: AIContextReference[], reportExport?: ReportExportResult) {
  appendFileReference(references, reportExport?.filePath, zhCN.aiActions.reportExportPath, 'report');
}

function appendExecutionReferences(references: AIContextReference[], execution: ExecutionStep) {
  appendExecutionReference(references, execution.id);
  appendFileReference(references, execution.logPath, zhCN.execution.openLogFile, 'executionLog', execution.id);
  appendFileReference(references, execution.artifactDir, zhCN.harness.openArtifactDir, 'artifactDir', execution.id);
}

function appendExecutionReference(references: AIContextReference[], executionId?: string) {
  appendReference(references, 'execution', executionId, zhCN.ai.referenceTargetExecution, undefined, executionId, 'ai.action_result');
}

function appendFileReference(
  references: AIContextReference[],
  path?: string,
  label = zhCN.ai.referenceTargetFile,
  kind = 'file',
  id?: string,
) {
  const normalizedPath = (path ?? '').trim();
  if (!normalizedPath) {
    return;
  }
  appendReference(references, kind, id || normalizedPath, label, normalizedPath, normalizedPath, 'ai.action_result');
}

function appendReference(
  references: AIContextReference[],
  kind: string,
  id?: string,
  label?: string,
  path?: string,
  title?: string,
  source?: string,
) {
  const normalizedId = (id ?? path ?? '').trim();
  if (!normalizedId) {
    return;
  }
  references.push({
    id: normalizedId,
    label: (label || title || normalizedId).trim(),
    kind,
    title,
    path,
    source,
  });
}

function dedupeAIContextReferences(references: AIContextReference[]): AIContextReference[] {
  const seen = new Set<string>();
  return references.filter(reference => {
    const key = `${reference.kind}:${reference.id}:${reference.path ?? ''}:${reference.line ?? ''}`;
    if (seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function AIActionPromptDiffResult({
  promptDiff,
}: {
  promptDiff?: AIActionRunResponse['result']['promptDiff'];
}) {
  if (!promptDiff) {
    return null;
  }
  return (
    <div className="ai-action-prompt-result">
      <strong>{zhCN.aiActions.promptDiffResult}</strong>
      <DetailGrid rows={[
        [zhCN.aiActions.promptID, promptDiff.promptId],
        [zhCN.aiActions.promptBaseVersion, promptDiff.baseVersionId],
        [zhCN.aiActions.promptTargetVersion, promptDiff.targetVersionId],
        [zhCN.aiActions.promptBaseTitle, promptDiff.baseTitle],
        [zhCN.aiActions.promptTargetTitle, promptDiff.targetTitle],
        [zhCN.aiActions.promptBaseContentExcerpt, contentPreview(promptDiff.baseContent)],
        [zhCN.aiActions.promptTargetContentExcerpt, contentPreview(promptDiff.targetContent)],
        [zhCN.aiActions.promptDiffChanged, promptDiff.changed ? zhCN.aiActions.promptDiffChangedYes : zhCN.aiActions.promptDiffChangedNo],
        [zhCN.aiActions.promptDiffAddedLines, promptDiff.addedLines],
        [zhCN.aiActions.promptDiffRemovedLines, promptDiff.removedLines],
      ]} />
      <div className="ai-action-patch-diff">
        <strong>{zhCN.aiActions.promptDiffContent}</strong>
        <pre>{aiDisplayText(promptDiff.diff, '')}</pre>
      </div>
    </div>
  );
}

