function AIActionAutoParsedEvidence({
  autoParsedEvidenceItems,
  autoParsedReportFindings,
  autoParsedEvidenceItemIds,
  autoParsedReportFindingIds,
  autoParsedEvidenceCount,
  autoParsedFindingCount,
  onOpenFile,
  onOpenReference,
}: {
  autoParsedEvidenceItems?: EvidenceItem[];
  autoParsedReportFindings?: ReportFinding[];
  autoParsedEvidenceItemIds?: string[];
  autoParsedReportFindingIds?: string[];
  autoParsedEvidenceCount?: number;
  autoParsedFindingCount?: number;
  onOpenFile: (filePath: string) => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const hasEvidence = autoParsedEvidenceItems !== undefined
    || autoParsedEvidenceItemIds !== undefined
    || autoParsedEvidenceCount !== undefined;
  const hasFindings = autoParsedReportFindings !== undefined
    || autoParsedReportFindingIds !== undefined
    || autoParsedFindingCount !== undefined;
  if (!hasEvidence && !hasFindings) {
    return null;
  }
  return (
    <div className="ai-action-report-result">
      {hasEvidence && (
        <section>
          <strong>{zhCN.aiActions.autoParsedEvidence}</strong>
          <DetailGrid rows={[
            [zhCN.aiActions.autoParsedEvidenceCount, autoParsedEvidenceCount],
            [zhCN.aiActions.autoParsedEvidenceRefs, autoParsedEvidenceItemIds?.join(', ')],
          ]} />
          {autoParsedEvidenceItems !== undefined && (
            <>
              {autoParsedEvidenceItems.length === 0 && <EmptyState text={zhCN.aiActions.noAutoParsedEvidence} />}
              <div className="report-list">
                {autoParsedEvidenceItems.map(item => (
                  <AIActionEvidenceItem key={item.id} item={item} onOpenFile={onOpenFile} onOpenReference={onOpenReference} />
                ))}
              </div>
            </>
          )}
        </section>
      )}
      {hasFindings && (
        <section>
          <strong>{zhCN.aiActions.autoParsedFindings}</strong>
          <DetailGrid rows={[
            [zhCN.aiActions.autoParsedFindingCount, autoParsedFindingCount],
            [zhCN.aiActions.autoParsedFindingRefs, autoParsedReportFindingIds?.join(', ')],
          ]} />
          {autoParsedReportFindings !== undefined && (
            <>
              {autoParsedReportFindings.length === 0 && <EmptyState text={zhCN.aiActions.noAutoParsedFindings} />}
              <div className="report-list">
                {autoParsedReportFindings.map(finding => (
                  <article key={finding.id}>
                    <strong>{finding.title}</strong>
                    <span>{severityLabel(finding.severity, finding.rawSeverity)}</span>
                    <DetailGrid rows={[
                      [zhCN.aiActions.reportFindingEndpoint, finding.endpoint],
                      [zhCN.aiActions.reportFindingDescription, finding.description],
                      [zhCN.aiActions.reportFindingEvidence, finding.evidence],
                      [zhCN.aiActions.reportFindingRecommendation, finding.recommendation],
                      [zhCN.aiActions.reportFindingSource, finding.source],
                      [zhCN.aiActions.executionId, finding.executionId],
                      [zhCN.aiActions.agentTaskId, finding.agentTaskId],
                      [zhCN.aiActions.blackboardItemId, finding.blackboardItemId],
                      [zhCN.aiActions.promptReferenceResult, finding.promptVersionId || finding.promptId],
                      [zhCN.ai.referenceAIMessage, finding.aiMessageIds?.join(', ')],
                      [zhCN.ai.referenceToolCall, finding.toolCallIds?.join(', ')],
                      [zhCN.ai.referenceActionTrace, finding.actionTraceIds?.join(', ')],
                    ]} />
                    <AIActionStructuredReferenceActions references={referencesForReportFinding(finding)} onOpenReference={onOpenReference} compact={false} />
                    <div className="row-actions detail-actions">
                      {finding.filePath && <button type="button" onClick={() => onOpenFile(finding.filePath as string)}>{zhCN.navigation.openEvidenceFile}</button>}
                      {finding.path && <button type="button" onClick={() => onOpenFile(finding.path as string)}>{zhCN.aiActions.openResultFile}</button>}
                    </div>
                  </article>
                ))}
              </div>
            </>
          )}
        </section>
      )}
    </div>
  );
}

