function HarnessResultTrace({
  result,
  onOpenFile,
}: {
  result: HarnessResult;
  onOpenFile: (filePath: string) => void;
}) {
  return (
    <div className="harness-result-trace">
      {result.aiMessageIds.length > 0 && (
        <section>
          <strong>{zhCN.harness.aiMessages}</strong>
          <div className="chip-list">
            {result.aiMessageIds.map(id => (
              <code key={id} data-harness-ai-message-id={id}>{id}</code>
            ))}
          </div>
        </section>
      )}
      {result.toolCallIds.length > 0 && (
        <section>
          <strong>{zhCN.harness.toolCalls}</strong>
          <div className="chip-list">
            {result.toolCallIds.map(id => (
              <code key={id} data-harness-tool-call-id={id}>{id}</code>
            ))}
          </div>
        </section>
      )}
      {result.fileDiffs.length > 0 && (
        <section>
          <strong>{zhCN.harness.fileDiffs}</strong>
          <div className="harness-trace-list">
            {result.fileDiffs.map((diff, index) => (
              <article key={`${diff.path ?? 'diff'}:${diff.actionId ?? ''}:${diff.messageId ?? ''}:${index}`} data-harness-file-diff="true">
                <DetailGrid rows={[
                  [zhCN.harness.filePath, diff.path],
                  [zhCN.ai.fileChangeOperation, aiFileChangeOperationLabel(diff.operation)],
                  [zhCN.harness.summaryText, diff.summary],
                  [zhCN.ai.fileChangeAction, diff.actionId],
                  [zhCN.harness.aiMessages, diff.messageId],
                  [zhCN.harness.toolCalls, diff.toolCallId],
                ]} />
                {diff.path && (
                  <button type="button" onClick={() => onOpenFile(diff.path as string)}>{zhCN.harness.openFile}</button>
                )}
                {diff.diff && (
                  <pre data-harness-file-diff-content="true">{aiDisplayText(diff.diff, '')}</pre>
                )}
              </article>
            ))}
          </div>
        </section>
      )}
      {result.eventlogReferences.length > 0 && (
        <section>
          <strong>{zhCN.harness.eventlogReferences}</strong>
          <div className="harness-trace-list">
            {result.eventlogReferences.map((reference, index) => (
              <article key={`${reference.id ?? ''}:${reference.replayEventId ?? ''}:${reference.rawEventId ?? ''}:${index}`} data-harness-eventlog-reference="true">
                <DetailGrid rows={[
                  [zhCN.harness.resultId, reference.id],
                  [zhCN.harness.rawEventId, reference.rawEventId],
                  [zhCN.harness.replayEventId, reference.replayEventId],
                  [zhCN.details.eventType, reference.eventType ? eventlogTypeLabel(reference.eventType) : undefined],
                  [zhCN.details.eventLane, reference.lane ? eventlogLaneLabel(reference.lane) : undefined],
                  [zhCN.harness.summaryText, reference.summary],
                ]} />
                <code>{reference.replayEventId || reference.rawEventId || reference.id}</code>
              </article>
            ))}
          </div>
        </section>
      )}
    </div>
  );
}

