function AIActionRuntimeWorkerResult({
  state,
  workers,
  orchestrations,
  orchestration,
  onOpenFile,
}: {
  state?: RuntimeWorkerState;
  workers?: RuntimeWorker[];
  orchestrations?: RuntimeWorkerOrchestration[];
  orchestration?: RuntimeWorkerOrchestration;
  onOpenFile: (filePath: string) => void;
}) {
  const hasWorkerPayload = Boolean(state || workers !== undefined);
  const hasOrchestrationPayload = Boolean(state || orchestrations !== undefined || orchestration);
  if (!hasWorkerPayload && !hasOrchestrationPayload) {
    return null;
  }
  const visibleWorkers = state?.workers ?? workers ?? [];
  const visibleOrchestrations = mergeRuntimeWorkerOrchestrations(
    state?.orchestrations ?? orchestrations ?? [],
    orchestration,
  );
  return (
    <section className="ai-action-worker-result" data-ai-action-worker-result="true">
      <strong>{orchestration ? zhCN.aiActions.workerOrchestrationResult : zhCN.aiActions.workerReadResult}</strong>
      {state && (
        <DetailGrid rows={[
          [zhCN.runtimeWorkers.total, state.workers.length],
          [zhCN.runtimeWorkers.ready, state.workers.filter(worker => runtimeWorkerStatusTone(worker) === 'ready').length],
          [zhCN.runtimeWorkers.stale, state.workers.filter(worker => worker.stale).length],
          [zhCN.runtimeWorkers.orchestrations, state.orchestrations.length],
          [zhCN.runtimeWorkers.updatedAt, formatAIInstant(state.updatedAt)],
          [zhCN.runtimeWorkers.staleAfterSeconds, `${state.staleAfterSeconds} ${zhCN.runtimeWorkers.seconds}`],
        ]} />
      )}
      {hasWorkerPayload && (
        <div className="ai-action-worker-section">
          <h4>{zhCN.runtimeWorkers.unitsTitle}</h4>
          {visibleWorkers.length === 0 && <EmptyState text={zhCN.runtimeWorkers.empty} />}
          <RuntimeWorkerList workers={visibleWorkers} onOpenFile={onOpenFile} />
        </div>
      )}
      {hasOrchestrationPayload && (
        <div className="ai-action-worker-section">
          <h4>{zhCN.runtimeWorkers.orchestrations}</h4>
          {visibleOrchestrations.length === 0 && <EmptyState text={zhCN.runtimeWorkers.orchestrationEmpty} />}
          <RuntimeWorkerOrchestrationList orchestrations={visibleOrchestrations} onOpenFile={onOpenFile} />
        </div>
      )}
    </section>
  );
}

function mergeRuntimeWorkerOrchestrations(
  orchestrations: RuntimeWorkerOrchestration[],
  orchestration?: RuntimeWorkerOrchestration,
): RuntimeWorkerOrchestration[] {
  const merged = orchestration ? [orchestration, ...orchestrations] : orchestrations;
  const seen = new Set<string>();
  return merged
    .filter(item => {
      const key = item.path || item.runId;
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .sort(compareRuntimeWorkerOrchestrationsNewestFirst);
}

function agentTaskResultTitle(result: AIActionRunResponse['result']): string {
  if (result.operation === 'update_agent_task') {
    return zhCN.aiActions.agentUpdateResult;
  }
  if (result.operation === 'append_agent_task_event' || result.kind === 'agent_task_event') {
    return zhCN.aiActions.agentEventResult;
  }
  return zhCN.aiActions.agentCreateResult;
}

