interface LineOrientedAIMessageField {
  label: string;
  value: string;
}

interface LineOrientedAIMessage {
  title?: string;
  fields: LineOrientedAIMessageField[];
  raw: string;
}

function parseLineOrientedAIMessage(content: string): LineOrientedAIMessage | null {
  const lines = content.replace(/\r\n/g, '\n').split('\n').map(line => line.trim()).filter(Boolean);
  if (lines.length < 3) {
    return null;
  }
  const fieldPattern = /^([^:：\n]{1,32})[:：]\s*(.+)$/;
  const fields = lines.flatMap(line => {
    const match = line.match(fieldPattern);
    if (!match) {
      return [];
    }
    return [{ label: match[1].trim(), value: match[2].trim() }];
  });
  if (fields.length < 3) {
    return null;
  }
  return {
    title: fieldPattern.test(lines[0]) ? undefined : lines[0],
    fields,
    raw: content.trim(),
  };
}

function localizedAIToolFieldValue(label: string, value: string): string {
  const normalizedLabel = label.trim();
  const normalizedValue = value.trim().toLowerCase().replace(/-/g, '_');
  if (normalizedLabel === zhCN.node.type || normalizedLabel === zhCN.node.kinds.action) {
    const knownKinds = new Set([
      'command',
      'execution',
      'tool',
      'toolchain',
      'tool_result',
      'file',
      'workspace_file',
      'evidence',
      'report',
      'blackboard',
      'agent',
      'harness',
      'strategy',
      'frontier',
      'orchestrator',
      'planner',
      'prompt',
      'eventlog',
    ]);
    if (knownKinds.has(normalizedValue)) {
      return aiActionTraceKindLabel(normalizedValue);
    }
  }
  if (normalizedLabel === zhCN.harness.status) {
    return localizedStatusLabel(value, value);
  }
  return value;
}

function AIToolMessageContent({ content }: { content: string }) {
  const structured = parseLineOrientedAIMessage(content);
  if (!structured) {
    return <ReactMarkdown remarkPlugins={[remarkGfm]}>{aiDisplayText(content, '')}</ReactMarkdown>;
  }
  const summaryFields = structured.fields.slice(0, 4);
  return (
    <div className="ai-tool-message-summary" data-ai-tool-summary="true">
      {structured.title && <strong className="ai-tool-message-title">{structured.title}</strong>}
      <dl className="ai-tool-message-fields">
        {summaryFields.map((field, index) => (
          <div key={`${field.label}-${index}`} title={`${field.label}: ${field.value}`}>
            <dt>{field.label}</dt>
            <dd>{localizedAIToolFieldValue(field.label, field.value)}</dd>
          </div>
        ))}
      </dl>
      <details className="ai-tool-message-details">
        <summary>{zhCN.ai.toolResultDetails} ({structured.fields.length})</summary>
        <pre>{aiDisplayText(structured.raw, '')}</pre>
      </details>
    </div>
  );
}

function AIMessageToolCorrelation({ message }: { message: AIMessage }) {
  const providerToolCalls = message.role === 'assistant' ? (message.providerToolCalls ?? []) : [];
  const providerToolNames = providerToolCalls.map(call => call.name).join('、');
  const rows = ([
    [zhCN.ai.toolCallMode, message.nativeToolCall ? zhCN.ai.nativeToolCall : undefined],
    [zhCN.ai.providerToolCallBatch, providerToolCalls.length > 0 ? `${providerToolCalls.length} ${zhCN.ai.providerToolCallCount}` : undefined],
    [zhCN.ai.providerToolCallNames, providerToolNames || undefined],
    [zhCN.ai.providerToolName, message.toolName],
    [zhCN.ai.streamEventActionId, message.actionId],
    [zhCN.ai.streamEventToolCallId, message.toolCallId],
  ] satisfies Array<[string, string | undefined]>).filter(([, value]) => Boolean(value));
  const nativeToolResultForwarded = message.role === 'tool' && message.nativeToolResultForwarded;
  if (rows.length === 0 && !nativeToolResultForwarded) {
    return null;
  }
  return (
    <section className="ai-message-tool-correlation" data-ai-message-tool-correlation="true" aria-label={zhCN.ai.messageToolCorrelation}>
      <strong>{zhCN.ai.messageToolCorrelation}</strong>
      {nativeToolResultForwarded && (
        <small className="ai-message-status" data-native-tool-result-forwarded="true">
          {formatNativeToolResultForwarded(message.toolCallId)}
        </small>
      )}
      <dl className="ai-stream-event-meta">
        {rows.map(([label, value]) => (
          <div key={`${label}-${value}`}>
            <dt>{label}</dt>
            <dd>{value}</dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

function AIMessageRow({
  message,
  onOpenReference,
  onRunFollowupAction,
  actionRunningId,
}: {
  message: AIMessage;
  onOpenReference: (reference: AIContextReference) => void;
  onRunFollowupAction: AIActionFollowupRunner;
  actionRunningId: string;
}) {
  const { content, createdAt: createdAtValue, role, status, tokenCount } = message;
  const createdAt = formatAITime(createdAtValue);
  const references = contextReferencesForAIMessage(message);
  const visibleContent = visibleAIText(content) ?? '';
  const protocolHidden = hasHiddenAIActionProtocol(content);
  const settlingHarness = actionRunningId === 'harness.cases.from_ai_conversation';
  return (
    <article className="ai-message-row" data-role={role}>
      <div className={role === 'assistant' ? 'ai-message-avatar assistant' : 'ai-message-avatar'} aria-hidden="true">
        {role === 'user' ? <User size={15} /> : role === 'assistant' ? <img className="ai-avatar-ring" src={ouroborosMark} alt="" /> : <TerminalSquare size={14} />}
      </div>
      <div className="ai-message-body">
        <div className="ai-message-head">
          <span>{zhCN.ai.roles[role]}</span>
          {createdAt && <time>{createdAt}</time>}
          {tokenCount !== undefined && <small>{zhCN.ai.tokenUsage}: {tokenCount}</small>}
        </div>
        {visibleContent && (
          <div className="ai-message-content">
            {role === 'tool'
              ? <AIToolMessageContent content={visibleContent} />
              : <ReactMarkdown remarkPlugins={[remarkGfm]}>{aiDisplayText(visibleContent, '')}</ReactMarkdown>}
          </div>
        )}
        <AIMessageToolCorrelation message={message} />
        {protocolHidden && <small className="ai-message-protocol-hidden">{zhCN.ai.actionProtocolHidden}</small>}
        {status && <small className="ai-message-status">{localizedStatusLabel(status)}</small>}
        {references.length > 0 && (
          <details className="ai-message-references">
            <summary>
              <ChevronRight size={13} />
              {zhCN.ai.contextReferences} ({references.length})
            </summary>
            <AIReferenceActions references={references} onOpenReference={onOpenReference} />
          </details>
        )}
        <div className="row-actions detail-actions ai-message-actions">
          <button
            type="button"
            onClick={() => onRunFollowupAction('harness.cases.from_ai_conversation', buildAIConversationHarnessFollowupInput({
              aiMessageIds: [message.id],
              toolCallIds: [message.toolCallId],
              source: 'desktop.ai.message',
            }))}
            disabled={settlingHarness}
          >
            <ClipboardCheck size={13} />
            {settlingHarness ? zhCN.ai.settleAsHarnessRunning : zhCN.ai.settleAsHarness}
          </button>
        </div>
        <AIMessageRoutingMeta routing={message.routing} usage={message.usage} />
      </div>
    </article>
  );
}

