function contextReferencesForAIMessage(message: AIMessage): AIContextReference[] {
  return Array.isArray(message.contextReferences) ? message.contextReferences : [];
}

function aiReferenceFilePath(reference: AIContextReference): string {
  const kind = reference.kind?.trim() ?? '';
  const path = (reference.path || '').trim();
  if (['file', 'artifact', 'artifactDir', 'report', 'evidence', 'executionLog', 'toolchain'].includes(kind)) {
    return path || reference.id?.trim() || '';
  }
  return '';
}

function frontierDependencyReferenceMode(reference: AIContextReference): IDEMode {
  const source = (reference.source || '').trim();
  return source === 'frontier.dependencies' ? 'ai' : 'ai';
}

function AIProviderRoutingPanel({
  routing,
  provider,
  model,
  usage,
}: {
  routing?: AIRoutingMetadata;
  provider?: string;
  model?: string;
  usage?: AIUsage;
}) {
  const finalProvider = routing?.finalProvider ?? routing?.provider ?? provider;
  const finalModel = routing?.finalModel ?? routing?.model ?? model;
  const attempts = providerAttemptsForRouting(routing);
  const hasRoutingDetails = Boolean(routing?.routingStrategy || routing?.fallbackFrom || routing?.failover !== undefined || attempts.length > 0 || formatAIUsageCost(usage));
  if (!finalProvider && !finalModel && !hasRoutingDetails) {
    return null;
  }
  return (
    <div className="ai-provider-routing">
      <DetailGrid rows={[
        [zhCN.ai.routingStrategy, routing?.routingStrategy ? providerRoutingStrategyLabel(routing.routingStrategy) : undefined],
        [zhCN.ai.finalProvider, finalProvider],
        [zhCN.ai.finalModel, finalModel],
        [zhCN.ai.fallbackFrom, routing?.fallbackFrom],
        [zhCN.ai.failover, formatFailoverState(routing?.failover)],
        [zhCN.ai.costUsage, formatAIUsageCost(usage)],
      ]} />
      {attempts.length > 0 && (
        <div className="ai-provider-attempts">
          <h4>{zhCN.ai.providerAttempts}</h4>
          {attempts.map((attempt, index) => (
            <article key={`${attempt.provider ?? zhCN.ai.providerAttempts}-${attempt.model ?? index}-${index}`}>
              <strong>{zhCN.ai.attemptSummary}: {formatProviderAttemptSummary(attempt, index)}</strong>
              <DetailGrid rows={[
                [zhCN.ai.attemptStatus, formatProviderAttemptStatus(attempt.status)],
                [zhCN.ai.provider, attempt.provider],
                [zhCN.ai.model, attempt.model],
                [zhCN.ai.costUsage, formatAIUsageCost(attempt.usage ?? {
                  latencyMs: attempt.latencyMs,
                  costUsd: attempt.costUsd,
                  costKnown: attempt.costKnown,
                })],
                [zhCN.ai.attemptError, attempt.error],
              ]} />
            </article>
          ))}
        </div>
      )}
    </div>
  );
}

function AIMessageRoutingMeta({ routing, usage }: { routing?: AIRoutingMetadata; usage?: AIUsage }) {
  const finalProvider = routing?.finalProvider ?? routing?.provider;
  const finalModel = routing?.finalModel ?? routing?.model;
  const attempts = providerAttemptsForRouting(routing);
  if (!routing && !usage) {
    return null;
  }
  return (
    <details className="ai-message-routing">
      <summary>{zhCN.ai.modelCallDetails}</summary>
      <DetailGrid rows={[
          [zhCN.ai.routingStrategy, routing?.routingStrategy ? providerRoutingStrategyLabel(routing.routingStrategy) : undefined],
          [zhCN.ai.finalProvider, finalProvider],
          [zhCN.ai.finalModel, finalModel],
          [zhCN.ai.fallbackFrom, routing?.fallbackFrom],
          [zhCN.ai.failover, formatFailoverState(routing?.failover)],
          [zhCN.ai.costUsage, formatAIUsageCost(usage ?? routing?.usage)],
          [zhCN.ai.attemptSummary, attempts.map(formatProviderAttemptSummary).join(' / ')],
        ]} />
    </details>
  );
}

function providerAttemptsForRouting(routing?: AIRoutingMetadata): AIProviderAttempt[] {
  return routing?.providerAttempts ?? routing?.attempts ?? [];
}

function formatProviderAttemptSummary(attempt: AIProviderAttempt, index: number): string {
  const providerModel = [attempt.provider, attempt.model].filter(Boolean).join(' / ');
  const usage = formatAIUsageCost(attempt.usage ?? {
    latencyMs: attempt.latencyMs,
    costUsd: attempt.costUsd,
    costKnown: attempt.costKnown,
  });
  return [
    `${index + 1}`,
    providerModel,
    formatProviderAttemptStatus(attempt.status),
    usage,
    attempt.error,
  ].filter(Boolean).join(' · ');
}

function formatProviderAttemptStatus(status?: string): string | undefined {
  if (!status) {
    return undefined;
  }
  if (status === 'succeeded') {
    return zhCN.ai.attemptSucceeded;
  }
  if (status === 'failed') {
    return zhCN.ai.attemptFailed;
  }
  return unknownBackendValueLabel(zhCN.ai.attemptUnknown, status);
}

function formatFailoverState(value?: boolean): string | undefined {
  if (value === undefined) {
    return undefined;
  }
  return value ? zhCN.ai.failoverYes : zhCN.ai.failoverNo;
}

function formatAIUsageCost(usage?: AIUsage): string | undefined {
  if (!usage) {
    return undefined;
  }
  const parts = [
    usage.totalTokens !== undefined ? `${usage.totalTokens} ${zhCN.ai.tokenUnit}` : undefined,
    usage.costUsd !== undefined ? formatCostUSD(usage.costUsd) : undefined,
    usage.costUsd === undefined && usage.costKnown === false ? zhCN.ai.runtimeCostUnknown : undefined,
    formatMilliseconds(usage.latencyMs),
  ].filter(Boolean);
  return parts.length > 0 ? parts.join(' · ') : undefined;
}

function executionStatusLabel(status?: string, rawStatus?: string) {
  return status === 'unknown'
    ? unknownBackendValueLabel(zhCN.executionStatus.unknown, rawStatus)
    : localizedStatusLabel(status, zhCN.executionStatus.unknown);
}

function severityLabel(severity?: Severity, rawSeverity?: string): string | undefined {
  if (!severity) {
    return undefined;
  }
  return severity === 'unknown'
    ? unknownBackendValueLabel(zhCN.severity.unknown, rawSeverity)
    : zhCN.severity[severity];
}

function AIContextList({ references, onOpenReference }: { references: AIContextReference[]; onOpenReference: (reference: AIContextReference) => void }) {
  return (
    <section className="ai-context-list">
      <PanelTitle icon={FileText} title={zhCN.ai.contextReferences} meta={`${references.length}`} />
      {references.length === 0 && <EmptyState text={zhCN.ai.noContextReferences} />}
      {references.map((reference, index) => (
        <article key={`${reference.kind ?? ''}:${reference.id ?? ''}:${reference.path ?? ''}:${index}`}>
          <div className="ai-context-reference-head">
            <strong>{reference.label || reference.title || reference.path || reference.id || zhCN.ai.referenceGeneric}</strong>
            <button type="button" onClick={() => onOpenReference(reference)}>
              <ChevronRight size={14} />
              {zhCN.ai.jumpToReference}
            </button>
          </div>
          <DetailGrid rows={[
            [zhCN.ai.referenceId, traceDisplayValue(reference.id, backendValueNotProvided)],
            [zhCN.ai.referenceKind, aiReferenceKindName(reference.kind)],
            [zhCN.ai.referencePath, reference.path],
            [zhCN.ai.referenceLine, reference.line],
            [zhCN.ai.actionTraceSummary, reference.summary],
            [zhCN.replay.detail, reference.detail],
            [zhCN.details.source, reference.source],
          ]} />
        </article>
      ))}
    </section>
  );
}

function AIReferenceActions({
  references,
  onOpenReference,
  compact = false,
}: {
  references: AIContextReference[];
  onOpenReference: (reference: AIContextReference) => void;
  compact?: boolean;
}) {
  const visibleReferences = references.slice(0, compact ? 5 : references.length);
  if (visibleReferences.length === 0) {
    return null;
  }
  return (
    <div className={compact ? 'ai-reference-actions compact' : 'ai-reference-actions'}>
      <span>{zhCN.ai.referenceNavigation}</span>
      {visibleReferences.map((reference, index) => (
        <button key={`${reference.kind ?? ''}:${reference.id ?? ''}:${reference.path ?? ''}:${index}`} type="button" onClick={() => onOpenReference(reference)}>
          <ChevronRight size={13} />
          {aiReferenceActionLabel(reference)}
        </button>
      ))}
      {compact && references.length > visibleReferences.length && (
        <small>{zhCN.ai.moreReferences}: {references.length - visibleReferences.length}</small>
      )}
    </div>
  );
}

function aiReferenceActionLabel(reference: AIContextReference): string {
  const label = aiReferenceKindLabel(reference.kind);
  const targetLabel = (reference.label || reference.title || '').trim();
  const targetIdentity = aiReferenceTargetIdentity(reference);
  const target = targetLabel && targetIdentity
    ? `${targetLabel} (${targetIdentity})`
    : targetLabel || targetIdentity || reference.source;
  return target ? `${label}: ${target}` : label;
}

function aiReferenceTargetIdentity(reference: AIContextReference): string {
  const id = reference.id?.trim() ?? '';
  const path = (reference.path || '').trim();
  const label = (reference.label || reference.title || '').trim();
  if (path && path !== label) {
    return path;
  }
  if (id && id !== label) {
    return id;
  }
  return '';
}

function settingsFocusForAIReference(reference: AIContextReference, sequence: number): SettingsFocus {
  const id = reference.id?.trim() ?? '';
  const title = (reference.title || '').trim();
  const label = (reference.label || '').trim();
  const source = (reference.source || '').trim();
  const identity = id || title || label || source;
  if (reference.kind === 'provider') {
    return { section: 'provider', providerName: identity, sequence };
  }
  if (reference.kind === 'prompt' || reference.kind === 'promptVersion') {
    const [promptIdFromID, versionIdFromID] = splitPromptReferenceID(id);
    const promptId = reference.kind === 'prompt'
      ? promptIdFromID || id || title || label
      : promptIdFromID;
    const promptVersionId = reference.kind === 'promptVersion'
      ? versionIdFromID || id || title || label
      : versionIdFromID;
    return {
      section: 'prompts',
      promptId: promptId || undefined,
      promptVersionId: promptVersionId || undefined,
      sequence,
    };
  }
  return { section: 'status', sequence };
}

function splitPromptReferenceID(id: string): [string, string] {
  const trimmed = id.trim();
  if (!trimmed.includes(':')) {
    return [trimmed, ''];
  }
  const [promptId, ...versionParts] = trimmed.split(':');
  return [promptId.trim(), versionParts.join(':').trim()];
}

