function blackboardStatusLabel(status?: string) {
  const normalized = normalizeBlackboardStatusKey(status);
  switch (normalized) {
    case 'open':
      return zhCN.blackboard.statuses.open;
    case 'in_progress':
      return zhCN.blackboard.statuses.inProgress;
    case 'done':
      return zhCN.blackboard.statuses.done;
    case 'failed':
      return zhCN.blackboard.statuses.failed;
    case 'blocked':
      return zhCN.blackboard.statuses.blocked;
    case 'closed':
      return zhCN.blackboard.statuses.closed;
    case '':
      return zhCN.blackboard.statuses.unknown;
    default:
      return unknownBackendValueLabel(zhCN.blackboard.statuses.unknown, status);
  }
}

function normalizeBlackboardStatusKey(status?: string): string {
  const normalized = (status ?? '').trim();
  switch (normalized) {
    case 'inProgress':
    case 'in-progress':
    case 'running':
      return 'in_progress';
    case 'completed':
    case 'complete':
    case 'succeeded':
    case 'success':
      return 'done';
    case 'error':
      return 'failed';
    case 'blocked':
      return 'blocked';
    default:
      return normalized;
  }
}

function normalizeBlackboardLifecycleStatus(status?: string): BlackboardLifecycleStatus | '' {
  const normalized = normalizeBlackboardStatusKey(status);
  switch (normalized) {
    case 'in_progress':
    case 'blocked':
      return 'in_progress';
    case 'done':
    case 'failed':
      return normalized;
    default:
      return '';
  }
}

