function AgentWorkbench({
  agentState,
  providerConfig,
  promptRegistry,
  onCreateProfile,
  onUpdateProfile,
  onDeleteProfile,
  onCreateTask,
  onUpdateTask,
  runtimeWorkerState,
  runtimeWorkerLoadState,
  runtimeWorkerStatus,
  onRefreshRuntimeWorkers,
  onOpenFile,
  onOpenReference,
  onInspectExecution,
  onFocusReplayEvent,
  onFocusReportFinding,
  lifecycleBusy,
  lifecycleStatus,
  onUpdateLifecycle,
  eventBusy,
  eventStatus,
  onCreateEvent,
  providerRuns,
  providerRunBusyTaskIds,
  providerRunErrors,
  onRunWithProvider,
  providerBatchRun,
  providerBatchRunRunning,
  providerBatchRunError,
  onRunProviderBatch,
}: {
  agentState: AgentState;
  providerConfig: ProviderConfig;
  promptRegistry: PromptRegistry | null;
  onCreateProfile: (request: AgentProfileCreateRequest) => Promise<AgentProfile>;
  onUpdateProfile: (id: string, request: AgentProfileUpdateRequest) => Promise<AgentProfile>;
  onDeleteProfile: (id: string) => Promise<void>;
  onCreateTask: (request: AgentTaskCreateRequest) => Promise<AgentTask>;
  onUpdateTask: (id: string, request: AgentTaskUpdateRequest) => Promise<AgentTask>;
  runtimeWorkerState: RuntimeWorkerState | null;
  runtimeWorkerLoadState: RuntimeWorkerLoadState;
  runtimeWorkerStatus: string;
  onRefreshRuntimeWorkers: () => void;
  onOpenFile: (filePath: string) => void;
  onOpenReference: (reference: AIContextReference) => void;
  onInspectExecution: (executionId: string) => void;
  onFocusReplayEvent: (eventId: string) => void;
  onFocusReportFinding: (findingId: string) => void;
  lifecycleBusy: AgentTaskLifecycleBusy | null;
  lifecycleStatus: string;
  onUpdateLifecycle: (task: AgentTask, status: AgentTaskLifecycleStatus) => void;
  eventBusy: AgentTaskEventBusy | null;
  eventStatus: string;
  onCreateEvent: (task: AgentTask, action: AgentTaskEventAction, input: AgentTaskEventSubmitInput) => void;
  providerRuns: AgentProviderRunMap;
  providerRunBusyTaskIds: string[];
  providerRunErrors: AgentProviderRunErrorMap;
  onRunWithProvider: (task: AgentTask, request: AgentProviderRunRequest) => void;
  providerBatchRun: AgentProviderBatchRun | null;
  providerBatchRunRunning: boolean;
  providerBatchRunError: string;
  onRunProviderBatch: (request: AgentProviderBatchRunRequest) => void;
}) {
  const countRows = [
    [zhCN.agents.queued, agentState.counts.queued],
    [zhCN.agents.inProgress, agentState.counts.inProgress],
    [zhCN.agents.completed, agentState.counts.completed],
    [zhCN.agents.failed, agentState.counts.failed],
  ] as const;
  const hasCounts = countRows.some(([, count]) => typeof count === 'number');
  return (
    <section className="agent-workbench" aria-label={zhCN.modes.agents}>
      <div className="workbench-header">
        <div>
          <p className="eyeline">{zhCN.agents.eyeline}</p>
          <h1>{zhCN.agents.title}</h1>
        </div>
        <div className="workbench-header-meta">
          <span>{agentState.path || zhCN.agents.noPath}</span>
          <strong>{agentState.tasks.length} {zhCN.agents.taskCount}</strong>
        </div>
      </div>
      <div className="agent-workbench-content">
        <AgentProfileWorkbench
          agentState={agentState}
          providerConfig={providerConfig}
          promptRegistry={promptRegistry}
          onCreateProfile={onCreateProfile}
          onUpdateProfile={onUpdateProfile}
          onDeleteProfile={onDeleteProfile}
        />
        <AgentTaskEditor
          profiles={agentState.profiles}
          tasks={agentState.tasks}
          onCreateTask={onCreateTask}
          onUpdateTask={onUpdateTask}
        />
        <div className="agent-grid">
          <section className="agent-task-list">
          <PanelTitle icon={UsersRound} title={zhCN.agents.tasks} meta={agentState.path || zhCN.agents.meta} />
          <AgentProviderBatchRunControls
            run={providerBatchRun ?? undefined}
            running={providerBatchRunRunning}
            requestError={providerBatchRunError}
            onRun={onRunProviderBatch}
            onOpenFile={onOpenFile}
          />
          {lifecycleStatus && (
            <div className="ai-collaboration-dispatch-status">
              <CircleDot size={13} />
              <span>{lifecycleStatus}</span>
            </div>
          )}
          {eventStatus && (
            <div className="ai-collaboration-dispatch-status">
              <CircleDot size={13} />
              <span>{eventStatus}</span>
            </div>
          )}
          {agentState.tasks.length === 0 && <EmptyState text={zhCN.agents.empty} />}
          {agentState.tasks.map(task => (
            <AgentTaskCard
              key={task.id}
              task={task}
              profile={agentState.profiles.find(profile => profile.id === task.agentId)}
              events={latestAgentTaskEvents(agentState.events, task.id, 3)}
              onOpenFile={onOpenFile}
              onOpenReference={onOpenReference}
              onInspectExecution={onInspectExecution}
              onFocusReplayEvent={onFocusReplayEvent}
              onFocusReportFinding={onFocusReportFinding}
              lifecycleBusy={lifecycleBusy}
              onUpdateLifecycle={onUpdateLifecycle}
              eventBusy={eventBusy}
              onCreateEvent={onCreateEvent}
              providerRun={providerRuns[task.id]}
              providerRunRunning={providerRunBusyTaskIds.includes(task.id)}
              providerRunError={providerRunErrors[task.id]}
              onRunWithProvider={onRunWithProvider}
            />
          ))}
          </section>
          <section className="agent-summary">
          <PanelTitle icon={Activity} title={zhCN.agents.summary} meta={zhCN.agents.summaryMeta} />
          <DetailGrid rows={[
            [zhCN.agents.total, agentState.tasks.length],
            [zhCN.agents.path, agentState.path],
            [zhCN.agents.eventPath, agentState.eventPath],
            [zhCN.agents.eventCount, agentState.events.length],
          ]} />
          <div className="agent-count-grid">
            {!hasCounts && <EmptyState text={zhCN.aiActions.noAgentTasks} />}
            {countRows.map(([label, count]) => (
              typeof count === 'number' && (
                <div key={label}>
                  <span>{label}</span>
                  <strong>{count}</strong>
                </div>
              )
            ))}
          </div>
          <AgentStrategySummary
            tasks={agentState.tasks}
            onOpenFile={onOpenFile}
            onInspectExecution={onInspectExecution}
          />
          </section>
        </div>
        <RuntimeWorkerWorkbench
          state={runtimeWorkerState}
          loadState={runtimeWorkerLoadState}
          status={runtimeWorkerStatus}
          onRefresh={onRefreshRuntimeWorkers}
          onOpenFile={onOpenFile}
        />
      </div>
    </section>
  );
}

