function AgentTaskEventControls({
  task,
  busy,
  onCreateEvent,
}: {
  task: AgentTask;
  busy: AgentTaskEventBusy | null;
  onCreateEvent: (task: AgentTask, action: AgentTaskEventAction, input: AgentTaskEventSubmitInput) => void;
}) {
  const [agentId, setAgentId] = useState(task.agentId ?? '');
  const [summary, setSummary] = useState('');
  const [detail, setDetail] = useState('');
  const [artifactPath, setArtifactPath] = useState('');
  const [executionId, setExecutionId] = useState(task.executionId ?? '');
  const agentIdInputRef = useRef<HTMLInputElement | null>(null);
  const summaryInputRef = useRef<HTMLTextAreaElement | null>(null);
  const detailInputRef = useRef<HTMLTextAreaElement | null>(null);
  const artifactPathInputRef = useRef<HTMLInputElement | null>(null);
  const executionIdInputRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    setAgentId(task.agentId ?? '');
  }, [task.id, task.agentId]);

  useEffect(() => {
    setExecutionId(task.executionId ?? '');
  }, [task.id, task.executionId]);

  const disabled = busy !== null;
  const taskBusy = busy?.id === task.id;
  const currentSubmitInput = (): AgentTaskEventSubmitInput => ({
    agentId: agentIdInputRef.current?.value ?? agentId,
    summary: summaryInputRef.current?.value ?? summary,
    detail: detailInputRef.current?.value ?? detail,
    artifactPath: artifactPathInputRef.current?.value ?? artifactPath,
    executionId: executionIdInputRef.current?.value ?? executionId,
  });
  return (
    <section
      className="ai-collaboration-dispatch-form agent-task-event-controls"
      aria-label={zhCN.agents.eventControls}
      data-agent-task-event-controls="true"
      data-agent-task-id={task.id}
      data-ai-agent-task-id={task.id}
      data-agent-task-title={task.title}
    >
      <div className="ai-collaboration-dispatch-fields">
        <label>
          <span>{zhCN.agents.agentId}</span>
          <input
            ref={agentIdInputRef}
            data-agent-task-event-field="agentId"
            value={agentId}
            onChange={event => setAgentId(event.target.value)}
            placeholder={zhCN.agents.eventAgentIdPlaceholder}
            aria-label={zhCN.agents.agentId}
          />
        </label>
        <label className="ai-collaboration-dispatch-wide">
          <span>{zhCN.ai.agentTaskEventSummary}</span>
          <textarea
            ref={summaryInputRef}
            data-agent-task-event-field="summary"
            value={summary}
            onChange={event => setSummary(event.target.value)}
            placeholder={zhCN.agents.eventSummaryPlaceholder}
            aria-label={zhCN.ai.agentTaskEventSummary}
          />
        </label>
        <label>
          <span>{zhCN.ai.agentTaskEventDetail}</span>
          <textarea
            ref={detailInputRef}
            data-agent-task-event-field="detail"
            value={detail}
            onChange={event => setDetail(event.target.value)}
            placeholder={zhCN.ai.agentTaskEventDetail}
            aria-label={zhCN.ai.agentTaskEventDetail}
          />
        </label>
        <label>
          <span>{zhCN.agents.artifactPath}</span>
          <input
            ref={artifactPathInputRef}
            data-agent-task-event-field="artifactPath"
            value={artifactPath}
            onChange={event => setArtifactPath(event.target.value)}
            placeholder={zhCN.agents.eventArtifactPlaceholder}
            aria-label={zhCN.agents.artifactPath}
          />
        </label>
        <label>
          <span>{zhCN.agents.executionId}</span>
          <input
            ref={executionIdInputRef}
            data-agent-task-event-field="executionId"
            value={executionId}
            onChange={event => setExecutionId(event.target.value)}
            placeholder={zhCN.agents.eventExecutionPlaceholder}
            aria-label={zhCN.agents.executionId}
          />
        </label>
      </div>
      <div className="row-actions detail-actions" aria-label={zhCN.agents.eventControls} aria-busy={taskBusy}>
        <button
          type="button"
          data-agent-task-event-action="claim"
          onClick={() => onCreateEvent(task, 'claim', currentSubmitInput())}
          disabled={disabled}
        >
          <UserCheck size={13} />
          {taskBusy && busy?.action === 'claim' ? zhCN.agents.eventRecordingShort : zhCN.ai.agentTaskClaim}
        </button>
        <button
          type="button"
          data-agent-task-event-action="log"
          onClick={() => onCreateEvent(task, 'log', currentSubmitInput())}
          disabled={disabled}
        >
          <FileText size={13} />
          {taskBusy && busy?.action === 'log' ? zhCN.agents.eventRecordingShort : zhCN.ai.agentTaskEventLog}
        </button>
      </div>
    </section>
  );
}

function AgentTaskLifecycleActions({
  task,
  busy,
  onUpdateLifecycle,
}: {
  task: AgentTask;
  busy: AgentTaskLifecycleBusy | null;
  onUpdateLifecycle: (task: AgentTask, status: AgentTaskLifecycleStatus) => void;
}) {
  const normalizedStatus = normalizeAgentLifecycleStatus(task.status);
  const taskBusy = busy?.id === task.id;
  const lifecycleBusy = busy !== null;
  return (
    <div className="row-actions detail-actions" aria-label={zhCN.ai.agentTaskLifecycleUpdate} aria-busy={taskBusy}>
      {agentTaskLifecycleActions.map(action => {
        const Icon = action.icon;
        const currentStatus = normalizedStatus === action.status;
        const updatingThisStatus = taskBusy && busy?.status === action.status;
        return (
          <button
            key={action.status}
            type="button"
            data-agent-task-lifecycle-action={action.action}
            data-agent-task-next-status={action.status}
            onClick={() => onUpdateLifecycle(task, action.status)}
            disabled={lifecycleBusy || currentStatus}
            title={taskBusy ? zhCN.ai.agentTaskLifecycleUpdating : currentStatus ? `${zhCN.ai.agentTaskLifecycleCurrent}: ${action.label}` : action.label}
          >
            <Icon size={13} />
            {updatingThisStatus ? zhCN.ai.agentTaskLifecycleUpdating : action.label}
          </button>
        );
      })}
    </div>
  );
}

function normalizeAgentLifecycleStatus(status?: string): AgentTaskLifecycleStatus | '' {
  const normalized = (status ?? '').trim();
  switch (normalized) {
    case 'queued':
    case 'pending':
    case 'open':
    case 'ready':
      return 'queued';
    case 'in_progress':
    case 'in-progress':
    case 'running':
    case 'active':
      return 'in_progress';
    case 'completed':
    case 'complete':
    case 'done':
    case 'success':
    case 'succeeded':
      return 'completed';
    case 'failed':
    case 'failure':
    case 'error':
      return 'failed';
    default:
      return '';
  }
}

function agentTaskLifecycleLabel(status: AgentTaskLifecycleStatus): string {
  const action = agentTaskLifecycleActions.find(item => item.status === status);
  return action?.label ?? zhCN.agents.statuses.unknown;
}

function agentTaskEventActionLabel(action: AgentTaskEventAction): string {
  switch (action) {
    case 'claim':
      return zhCN.agents.claimTask;
    case 'log':
      return zhCN.agents.recordLog;
    default:
      return zhCN.agents.eventKinds.unknown;
  }
}

function agentTaskEventKindLabel(kind?: string): string {
  const normalized = (kind ?? '').trim().toLowerCase();
  switch (normalized) {
    case 'started':
    case 'start':
      return zhCN.agents.eventKinds.started;
    case 'claim':
      return zhCN.agents.eventKinds.claim;
    case 'log':
      return zhCN.agents.eventKinds.log;
    case 'result':
      return zhCN.agents.eventKinds.result;
    case 'handoff':
      return zhCN.agents.eventKinds.handoff;
    default:
      return unknownBackendValueLabel(zhCN.agents.eventKinds.unknown, kind);
  }
}

function latestAgentTaskEvents(events: AgentTaskEvent[], taskId: string, limit: number): AgentTaskEvent[] {
  return events
    .filter(event => event.taskId === taskId)
    .sort((left, right) => right.createdAt - left.createdAt)
    .slice(0, limit);
}

function agentStatusLabel(status?: string) {
  const normalized = (status ?? '').trim().toLowerCase();
  switch (normalized) {
    case 'queued':
    case 'pending':
    case 'open':
    case 'ready':
      return zhCN.agents.statuses.queued;
    case 'in_progress':
    case 'in-progress':
    case 'running':
    case 'active':
      return zhCN.agents.statuses.inProgress;
    case 'completed':
    case 'complete':
    case 'done':
    case 'success':
    case 'succeeded':
      return zhCN.agents.statuses.completed;
    case 'failed':
    case 'failure':
    case 'error':
      return zhCN.agents.statuses.failed;
    case '':
      return zhCN.agents.statuses.unknown;
    default:
      return unknownBackendValueLabel(zhCN.agents.statuses.unknown, status);
  }
}

function agentPriorityLabel(priority?: string) {
  return localizedPriorityLabel(priority);
}

function HarnessWorkbench({
  harness,
  agentTasks,
  draft,
  status,
  runningCaseId,
  onDraftChange,
  onRefreshHarness,
  onCreateHarnessCase,
  onRunHarnessCase,
  onOpenFile,
  onOpenResultFile,
  onOpenLogFile,
  onOpenArtifactDir,
  onInspectExecution,
  onOpenReference,
}: {
  harness: IDEData['harness'];
  agentTasks: AgentTask[];
  draft: HarnessCaseCreateRequest;
  status: string;
  runningCaseId: string;
  onDraftChange: (field: keyof HarnessCaseCreateRequest, value: string) => void;
  onRefreshHarness: () => void;
  onCreateHarnessCase: (draft: HarnessCaseCreateRequest) => void;
  onRunHarnessCase: (id: string) => void;
  onOpenFile: (filePath: string) => void;
  onOpenResultFile: (filePath: string) => void;
  onOpenLogFile: (filePath: string) => void;
  onOpenArtifactDir: (filePath: string) => void;
  onInspectExecution: (executionId: string) => void;
  onOpenReference: (reference: AIContextReference) => void;
}) {
  const promptHarnessAnalysis = buildPromptHarnessAnalysis(harness.results);

  return (
    <section className="harness-workbench" aria-label={zhCN.modes.harness}>
      <div className="workbench-header">
        <div>
          <p className="eyeline">{zhCN.harness.eyeline}</p>
          <h1>{zhCN.harness.title}</h1>
        </div>
        <div className="workbench-header-actions">
          {status && <span>{status}</span>}
          <button type="button" className="primary-action" onClick={onRefreshHarness}>
            <RefreshCw size={16} />
            {zhCN.harness.refresh}
          </button>
        </div>
      </div>
      <PromptHarnessAnalysisPanel analysis={promptHarnessAnalysis} />
      <div className="harness-grid">
        <section className="harness-case-list">
          <PanelTitle icon={ClipboardCheck} title={zhCN.harness.cases} meta={harness.path || zhCN.harness.noPath} />
          {harness.cases.length === 0 && <EmptyState text={zhCN.harness.emptyCases} />}
          {harness.cases.map(testCase => (
            <HarnessCaseCard
              key={testCase.id}
              testCase={testCase}
              running={runningCaseId === testCase.id}
              onRunHarnessCase={onRunHarnessCase}
              onOpenFile={onOpenFile}
            />
          ))}
        </section>
        <section className="harness-result-list">
          <PanelTitle icon={Activity} title={zhCN.harness.results} meta={harness.resultPath || zhCN.harness.noResultPath} />
          {harness.results.length === 0 && <EmptyState text={zhCN.harness.emptyResults} />}
          {harness.results.map(result => (
            <HarnessResultCard
              key={result.id}
              result={result}
              onOpenResultFile={onOpenResultFile}
              onOpenLogFile={onOpenLogFile}
              onOpenArtifactDir={onOpenArtifactDir}
              onInspectExecution={onInspectExecution}
              onOpenReference={onOpenReference}
            />
          ))}
        </section>
        <aside className="harness-summary">
          <PanelTitle icon={ClipboardList} title={zhCN.harness.summary} meta={zhCN.harness.summaryMeta} />
          <div className="harness-count-grid">
            <div>
              <span>{zhCN.harness.totalCases}</span>
              <strong>{harness.counts.totalCases}</strong>
            </div>
            <div>
              <span>{zhCN.harness.totalResults}</span>
              <strong>{harness.counts.totalResults}</strong>
            </div>
            <div>
              <span>{zhCN.harness.running}</span>
              <strong>{harness.counts.running}</strong>
            </div>
            <div>
              <span>{zhCN.harness.passed}</span>
              <strong>{harness.counts.passed}</strong>
            </div>
            <div>
              <span>{zhCN.harness.failed}</span>
              <strong>{harness.counts.failed}</strong>
            </div>
          </div>
          <DetailGrid rows={[
            [zhCN.harness.path, harness.path],
            [zhCN.harness.resultPath, harness.resultPath],
          ]} />
          <HarnessCreateForm agentTasks={agentTasks} draft={draft} onDraftChange={onDraftChange} onCreateHarnessCase={onCreateHarnessCase} />
        </aside>
      </div>
    </section>
  );
}

type PromptHarnessAnalysis = {
  results: HarnessResult[];
  groups: PromptHarnessVersionGroup[];
  recentResults: HarnessResult[];
  totals: {
    resultCount: number;
    providerCount: number;
    modelCount: number;
    promptCount: number;
    versionCount: number;
    totalTokens: number;
    totalCostUsd?: number;
    latestResultId?: string;
  };
};

type PromptHarnessVersionGroup = {
  key: string;
  promptId?: string;
  versionId?: string;
  provider?: string;
  model?: string;
  count: number;
  statusCounts: Record<string, number>;
  totalTokens: number;
  totalCostUsd?: number;
  latestResult: HarnessResult;
  latestOutput?: string;
};

