function HarnessInputSnapshotSummary({ testCase }: { testCase: HarnessCase }) {
  const provider = testCase.providerSnapshot;
  const toolchain = testCase.toolchainSnapshot;
  if (!provider && !toolchain) {
    return null;
  }
  const activeProvider = provider?.active;
  const firstPack = toolchain?.packs[0];
  const firstAction = toolchain?.actions[0];
  return (
    <section className="harness-trace-section" data-harness-input-snapshot="true" aria-label={zhCN.harness.inputSnapshots}>
      <strong>{zhCN.harness.inputSnapshots}</strong>
      {provider && (
        <div data-harness-provider-snapshot="true">
          <DetailGrid rows={[
            [zhCN.harness.providerSnapshot, localizedStatusLabel(provider.status)],
            [zhCN.harness.providerConfigPath, provider.configPath],
            [zhCN.harness.providerRoutingStrategy, providerRoutingStrategyLabel(provider.routingStrategy)],
            [zhCN.harness.providerActive, [activeProvider?.name, activeProvider?.model].filter(Boolean).join(' / ')],
            [zhCN.harness.providerApiKeyEnv, activeProvider?.apiKeyEnv],
            [zhCN.harness.providerCapabilities, formatProviderCapabilities(activeProvider?.capabilities)],
            [zhCN.harness.providerCount, provider.providers.length],
            [zhCN.harness.snapshotError, provider.error],
          ]} />
        </div>
      )}
      {toolchain && (
        <div data-harness-toolchain-snapshot="true">
          <DetailGrid rows={[
            [zhCN.harness.toolchainSnapshot, localizedStatusLabel(toolchain.status)],
            [zhCN.harness.toolchainPackCount, toolchain.packs.length],
            [zhCN.harness.toolchainActionCount, toolchain.actions.length],
            [zhCN.harness.toolchainFirstPack, [firstPack?.name, firstPack?.version].filter(Boolean).join(' / ')],
            [zhCN.harness.toolchainFirstAction, firstAction?.label || firstAction?.id],
            [zhCN.harness.toolchainManifestPath, firstAction?.manifestPath || firstPack?.manifestPath],
            [zhCN.harness.toolchainCommand, firstAction?.commandText || firstAction?.command.join(' ') || firstPack?.runCommand.join(' ')],
            [zhCN.harness.snapshotError, toolchain.error],
          ]} />
        </div>
      )}
    </section>
  );
}

