let toolActionArgumentDraftSequence = 0;

function createToolActionArgumentDraft(): ToolActionArgumentDraft {
  toolActionArgumentDraftSequence += 1;
  return { id: `tool-action-argument-${toolActionArgumentDraftSequence}`, value: '' };
}

function isCatalogToolAction(action: ToolAction): boolean {
  return action.source === 'catalog' || action.id.startsWith('catalog.');
}

function toolActionTargetKinds(action: ToolAction): string[] {
  const targetKinds = action.targetKinds.filter(Boolean);
  if (action.targetKind && !targetKinds.includes(action.targetKind)) {
    targetKinds.unshift(action.targetKind);
  }
  return [...new Set(targetKinds)];
}

function toolActionLaunchDraft(action: ToolAction, drafts: ToolActionLaunchDrafts): ToolActionLaunchDraft {
  const existing = drafts[action.id];
  if (existing) {
    return existing.targetKind ? existing : {
      ...existing,
      targetKind: action.targetKind || toolActionTargetKinds(action)[0] || '',
    };
  }
  return {
    target: '',
    targetKind: action.targetKind || toolActionTargetKinds(action)[0] || '',
    args: [],
    arguments: '',
  };
}

function toolActionRunDisabled(action: ToolAction, draft: ToolActionLaunchDraft): boolean {
  const catalogAction = action.source === 'catalog' || action.id.startsWith('catalog.');
  return catalogAction && draft.target.trim() === '';
}

function toolActionRunRequest(action: ToolAction, draft: ToolActionLaunchDraft): ToolActionRunRequest {
  if (isCatalogToolAction(action)) {
    return {
      target: draft.target.trim(),
      targetKind: draft.targetKind,
      args: draft.args.map(argument => argument.value),
    };
  }
  return { arguments: draft.arguments };
}

function toolCatalogLabel(labels: Record<string, string>, value: string, fallback: string): string {
  const normalized = value.trim();
  if (!normalized) {
    return fallback || zhCN.toolLaunch.notReported;
  }
  return labels[normalized] || unknownBackendValueLabel(fallback, normalized);
}

function toolCapabilityLabel(capability: string): string {
  const normalized = capability.trim();
  const labels = zhCN.toolLaunch.capabilityLabels as Record<string, string>;
  return labels[normalized] ?? unknownBackendValueLabel(zhCN.toolLaunch.unknownCapability, capability);
}

function formatToolCapabilities(capabilities?: string[]): string {
  return (capabilities ?? []).map(toolCapabilityLabel).join(', ');
}

function toolActionDisplayLabel(action: ToolAction): string {
  if (!isCatalogToolAction(action)) {
    return action.label;
  }
  const tool = toolCatalogLabel(zhCN.toolLaunch.tools, action.toolId, zhCN.toolLaunch.unknownTool);
  const operation = toolCatalogLabel(zhCN.toolLaunch.operations, action.operation, zhCN.toolLaunch.unknownOperation);
  return `${tool} · ${operation}`;
}

function toolTargetKindLabel(targetKind: string): string {
  return toolCatalogLabel(zhCN.toolLaunch.targetKinds, targetKind, zhCN.toolLaunch.unknownTargetKind);
}

function ToolActionLaunchFields({
  action,
  draft,
  onDraftChange,
  onRun,
}: {
  action: ToolAction;
  draft: ToolActionLaunchDraft;
  onDraftChange: (draft: ToolActionLaunchDraft) => void;
  onRun: () => void;
}) {
  const catalogAction = isCatalogToolAction(action);
  const targetKinds = action.targetKinds.length > 0
    ? toolActionTargetKinds(action)
    : [action.targetKind].filter(Boolean);
  const updateArgument = (argumentID: string, value: string) => {
    onDraftChange({
      ...draft,
      args: draft.args.map(argument => argument.id === argumentID ? { ...argument, value } : argument),
    });
  };
  const runOnEnter = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key !== 'Enter' || event.nativeEvent.isComposing || toolActionRunDisabled(action, draft)) {
      return;
    }
    event.preventDefault();
    onRun();
  };

  if (!catalogAction) {
    return (
      <div className="tool-action-fields legacy-tool-action-fields">
        <div className="tool-action-main">
          <header>
            <strong>{action.label}</strong>
            <span>{zhCN.toolLaunch.manifestAction}</span>
          </header>
          <code>{action.commandText}</code>
          <small>{[action.packName || action.packId, action.parser, formatToolCapabilities(action.capabilities)].filter(Boolean).join(' / ') || action.manifestPath}</small>
        </div>
        <label className="tool-action-legacy-arguments">
          <span>{zhCN.toolLaunch.arguments}</span>
          <input
            value={draft.arguments}
            onChange={event => onDraftChange({ ...draft, arguments: event.target.value })}
            onKeyDown={runOnEnter}
            placeholder={action.argumentHint || zhCN.toolLaunch.argumentPlaceholder}
            aria-label={`${zhCN.toolLaunch.arguments}: ${action.label}`}
          />
        </label>
      </div>
    );
  }

  const toolName = toolCatalogLabel(zhCN.toolLaunch.tools, action.toolId, zhCN.toolLaunch.unknownTool);
  const operation = toolCatalogLabel(zhCN.toolLaunch.operations, action.operation, zhCN.toolLaunch.unknownOperation);
  const category = toolCatalogLabel(zhCN.toolLaunch.categories, action.category, zhCN.toolLaunch.unknownCategory);
  const dependencyKind = toolCatalogLabel(zhCN.toolLaunch.dependencyKinds, action.dependencyKind, zhCN.toolLaunch.unknownDependencyKind);
  const dependencyStatus = action.dependencyStatus
    ? localizedStatusLabel(action.dependencyStatus)
    : zhCN.toolLaunch.notReported;

  return (
    <div className="tool-action-fields catalog-tool-action-fields" data-tool-action-source={action.source}>
      <div className="tool-action-main">
        <header>
          <strong>{toolActionDisplayLabel(action)}</strong>
          <span>{zhCN.toolLaunch.catalogAction}</span>
        </header>
        <small>{[action.packName || action.packId, category].filter(Boolean).join(' / ')}</small>
        <dl className="tool-action-metadata">
          <div><dt>{zhCN.toolLaunch.tool}</dt><dd>{toolName}</dd></div>
          <div><dt>{zhCN.toolLaunch.operation}</dt><dd>{operation}</dd></div>
          <div><dt>{zhCN.toolLaunch.dependency}</dt><dd>{action.dependencyName || action.binary || zhCN.toolLaunch.notReported}</dd></div>
          <div><dt>{zhCN.toolLaunch.dependencyKind}</dt><dd>{dependencyKind}</dd></div>
          <div>
            <dt>{zhCN.toolLaunch.dependencyStatus}</dt>
            <dd data-dependency-ready={action.dependencyReady ? 'true' : 'false'}>
              <CircleDot size={11} />
              {dependencyStatus} · {action.dependencyReady ? zhCN.toolLaunch.dependencyReady : zhCN.toolLaunch.dependencyNotReady}
            </dd>
          </div>
          <div><dt>{zhCN.toolLaunch.dependencyVersion}</dt><dd>{action.dependencyVersion || zhCN.toolLaunch.notReported}</dd></div>
          <div><dt>{zhCN.toolLaunch.dependencyMessage}</dt><dd>{action.dependencyMessage || zhCN.toolLaunch.notReported}</dd></div>
          <div><dt>{zhCN.toolLaunch.dependencySource}</dt><dd>{action.dependencySource || zhCN.toolLaunch.notReported}</dd></div>
          <div><dt>{zhCN.toolLaunch.parser}</dt><dd><code>{action.parser || zhCN.toolLaunch.notReported}</code></dd></div>
          <div><dt>{zhCN.toolLaunch.capabilities}</dt><dd><code>{action.capabilities.length > 0 ? formatToolCapabilities(action.capabilities) : zhCN.toolLaunch.notReported}</code></dd></div>
        </dl>
      </div>
      <div className="tool-action-structured-inputs">
        <label>
          <span>{zhCN.toolLaunch.targetKind}</span>
          <select
            value={draft.targetKind}
            onChange={event => onDraftChange({ ...draft, targetKind: event.target.value })}
            aria-label={`${zhCN.toolLaunch.targetKind}: ${toolName}`}
          >
            {targetKinds.map(targetKind => (
              <option key={targetKind} value={targetKind}>{toolTargetKindLabel(targetKind)}</option>
            ))}
          </select>
        </label>
        <label>
          <span>{zhCN.toolLaunch.target}</span>
          <input
            value={draft.target}
            onChange={event => onDraftChange({ ...draft, target: event.target.value })}
            onKeyDown={runOnEnter}
            placeholder={zhCN.toolLaunch.targetPlaceholder}
            aria-label={`${zhCN.toolLaunch.target}: ${toolName}`}
            required
          />
        </label>
        <div className="tool-action-arguments-editor">
          <header>
            <span>{zhCN.toolLaunch.additionalArguments}</span>
            <button
              type="button"
              className="tool-argument-icon-button"
              onClick={() => onDraftChange({ ...draft, args: [...draft.args, createToolActionArgumentDraft()] })}
              title={zhCN.toolLaunch.addArgument}
              aria-label={zhCN.toolLaunch.addArgument}
            >
              <Plus size={14} />
            </button>
          </header>
          {draft.args.length === 0 && <small>{zhCN.toolLaunch.noAdditionalArguments}</small>}
          {draft.args.map((argument, index) => (
            <div key={argument.id} className="tool-action-argument-row">
              <span aria-hidden="true">{index + 1}</span>
              <input
                value={argument.value}
                onChange={event => updateArgument(argument.id, event.target.value)}
                onKeyDown={runOnEnter}
                placeholder={zhCN.toolLaunch.argumentItemPlaceholder}
                aria-label={`${zhCN.toolLaunch.argumentItem} ${index + 1}: ${toolName}`}
              />
              <button
                type="button"
                className="tool-argument-icon-button"
                onClick={() => onDraftChange({ ...draft, args: draft.args.filter(item => item.id !== argument.id) })}
                title={zhCN.toolLaunch.removeArgument}
                aria-label={`${zhCN.toolLaunch.removeArgument}: ${index + 1}`}
              >
                <X size={14} />
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function ToolLaunchPanel({
  toolActions,
  toolActionDrafts,
  status,
  onDraftChange,
  onRunToolAction,
}: {
  toolActions: ToolAction[];
  toolActionDrafts: ToolActionLaunchDrafts;
  status: string;
  onDraftChange: (action: ToolAction, draft: ToolActionLaunchDraft) => void;
  onRunToolAction: (action: ToolAction) => void;
}) {
  return (
    <section className="tool-launch-panel">
      <PanelTitle icon={TerminalSquare} title={zhCN.toolLaunch.title} meta={status || zhCN.toolLaunch.meta} />
      {toolActions.length === 0 && <EmptyState text={zhCN.toolLaunch.empty} />}
      {toolActions.map(action => {
        const draft = toolActionLaunchDraft(action, toolActionDrafts);
        return (
          <div key={action.id} className="tool-action-row" data-tool-action-id={action.id}>
            <ToolActionLaunchFields
              action={action}
              draft={draft}
              onDraftChange={nextDraft => onDraftChange(action, nextDraft)}
              onRun={() => onRunToolAction(action)}
            />
            <button
              type="button"
              onClick={() => onRunToolAction(action)}
              disabled={toolActionRunDisabled(action, draft)}
            >
              <Radar size={14} />
              {zhCN.toolLaunch.run}
            </button>
          </div>
        );
      })}
    </section>
  );
}

