function ToolExecution({
  steps,
  nodes,
  events,
  findings,
  status,
  log,
  artifacts,
  artifactsExecutionId,
  selectedExecutionId,
  detailBusy,
  onSelect,
  onStop,
  onRetry,
  onLoadLogs,
  onLoadArtifacts,
  onOpenExecutionFile,
  onFocusGraphNode,
  onFocusReplayEvent,
  onFocusReportFinding,
}: {
  steps: ExecutionStep[];
  nodes: GraphNode[];
  events: ReplayEvent[];
  findings: ReportFinding[];
  status: string;
  log: ExecutionLog | null;
  artifacts: ExecutionArtifact[];
  artifactsExecutionId: string;
  selectedExecutionId: string;
  detailBusy: ExecutionDetailBusy;
  onSelect: (id: string) => void;
  onStop: (id: string) => void;
  onRetry: (id: string) => void;
  onLoadLogs: (id: string) => void;
  onLoadArtifacts: (id: string) => void;
  onOpenExecutionFile: (filePath: string) => void;
  onFocusGraphNode: (nodeId: string) => void;
  onFocusReplayEvent: (eventId: string) => void;
  onFocusReportFinding: (findingId: string) => void;
}) {
  const activeStep = steps.find(step => step.id === selectedExecutionId)
    ?? steps.find(step => step.id === artifactsExecutionId)
    ?? steps.find(step => step.id === log?.id)
    ?? steps[0];
  const activeLog = activeStep && log?.id === activeStep.id ? log : null;
  const activeArtifacts = activeStep && artifactsExecutionId === activeStep.id ? artifacts : [];
  const activeLogsLoading = Boolean(activeStep && detailBusy.logs === activeStep.id);
  const activeArtifactsLoading = Boolean(activeStep && detailBusy.artifacts === activeStep.id);
  const activeArtifactsLoaded = Boolean(activeStep && artifactsExecutionId === activeStep.id);
  const executionSummary = steps.length > 0 && status === zhCN.execution.empty
    ? `${steps.length} ${zhCN.execution.records}`
    : status || `${steps.length} ${zhCN.execution.records}`;
  const referenceTargets: ExecutionReferenceTargets = activeStep ? {
    node: nodes.find(node => node.executionId === activeStep.id),
    event: events.find(event => event.executionId === activeStep.id),
    finding: findings.find(finding => finding.executionId === activeStep.id),
  } : {};
  return (
    <section className="execution-panel">
      <PanelTitle icon={TerminalSquare} title={zhCN.mission.execution} meta={executionSummary} />
      {steps.length === 0 && <EmptyState text={zhCN.execution.empty} />}
      {steps.length > 0 && (
        <div
          role="list"
          aria-label={`${steps.length} ${zhCN.execution.records}`}
          style={{ maxHeight: 'min(210px, 38vh)', overflowY: 'auto', overscrollBehavior: 'contain' }}
        >
          {steps.map(step => {
            const selected = step.id === activeStep?.id;
            const logsLoading = detailBusy.logs === step.id;
            const artifactsLoading = detailBusy.artifacts === step.id;
            return (
              <div
                key={step.id}
                role="listitem"
                className={`execution-step ${step.status}${selected ? ' active' : ''}`}
                data-selected={selected ? 'true' : 'false'}
              >
                <CircleDot size={13} />
                <div>
                  <button
                    type="button"
                    className="detail-link"
                    aria-current={selected ? 'true' : undefined}
                    onClick={() => onSelect(step.id)}
                  >
                    {step.label}
                  </button>
                  <code>{step.command}</code>
                  {step.exitCode !== undefined && <small>{zhCN.execution.exitCode}: {step.exitCode}</small>}
                </div>
                <div className="execution-actions">
                  {step.status === 'running' && <button type="button" onClick={() => onStop(step.id)}>{zhCN.execution.stop}</button>}
                  <button type="button" onClick={() => onRetry(step.id)}>{zhCN.execution.retry}</button>
                  <button
                    type="button"
                    aria-label={logsLoading ? zhCN.execution.loadingLogs : zhCN.execution.logs}
                    title={logsLoading ? zhCN.execution.loadingLogs : zhCN.execution.logs}
                    onClick={() => onLoadLogs(step.id)}
                    disabled={logsLoading}
                  >
                    {logsLoading ? zhCN.execution.loadingShort : zhCN.execution.logs}
                  </button>
                  <button
                    type="button"
                    aria-label={artifactsLoading ? zhCN.execution.loadingArtifacts : zhCN.execution.artifacts}
                    title={artifactsLoading ? zhCN.execution.loadingArtifacts : zhCN.execution.artifacts}
                    onClick={() => onLoadArtifacts(step.id)}
                    disabled={artifactsLoading}
                  >
                    {artifactsLoading ? zhCN.execution.loadingShort : zhCN.execution.artifacts}
                  </button>
                </div>
                <span>{executionStatusLabel(step.status, step.rawStatus)}</span>
              </div>
            );
          })}
        </div>
      )}
      {activeStep && (
        <ExecutionDetailPanel
          step={activeStep}
          log={activeLog}
          artifacts={activeArtifacts}
          references={referenceTargets}
          onFocusGraphNode={onFocusGraphNode}
          onFocusReplayEvent={onFocusReplayEvent}
          onFocusReportFinding={onFocusReportFinding}
        />
      )}
      {(activeLog || activeArtifacts.length > 0 || activeLogsLoading || activeArtifactsLoading || activeArtifactsLoaded) && (
        <div className="execution-detail">
          {activeLogsLoading && <EmptyState text={zhCN.execution.loadingLogs} />}
          {activeLog && (
            <div>
              <strong>{zhCN.execution.logs}: {activeLog.path}</strong>
              <button type="button" onClick={() => onOpenExecutionFile(activeLog.path)}>{zhCN.execution.openLogFile}</button>
              <pre>{aiDisplayText(activeLog.content, zhCN.execution.noLogs)}</pre>
            </div>
          )}
          {activeArtifactsLoading && <EmptyState text={zhCN.execution.loadingArtifacts} />}
          {!activeArtifactsLoading && activeArtifactsLoaded && activeArtifacts.length === 0 && <EmptyState text={zhCN.execution.noArtifacts} />}
          {activeArtifacts.length > 0 && (
            <div>
              <strong>{zhCN.execution.artifacts}</strong>
              {activeArtifacts.map(artifact => (
                <article key={artifact.path}>
                  <span>{artifact.path}</span>
                  <small>{artifact.size} {zhCN.details.bytes}</small>
                  {artifact.filePath && <button type="button" onClick={() => onOpenExecutionFile(artifact.filePath as string)}>{zhCN.execution.openArtifactFile}</button>}
                  {artifact.contentPreview && <code>{aiDisplayText(artifact.contentPreview, '')}</code>}
                </article>
              ))}
            </div>
          )}
        </div>
      )}
    </section>
  );
}

function RightRail({
  data,
  selectedNode,
  onSelectNode,
  onOpenGraph,
  onOpenAgents,
}: {
  data: IDEData;
  selectedNode?: GraphNode;
  onSelectNode: (id: string) => void;
  onOpenGraph: () => void;
  onOpenAgents: () => void;
}) {
  const inspectedNode = selectedNode;
  const inspectedExecution = data.executionSteps.find(execution => (
    execution.id === inspectedNode?.executionId || execution.id === inspectedNode?.id
  ));
  return (
    <aside className={inspectedNode ? 'right-rail has-selection' : 'right-rail no-selection'}>
      <section className="rail-section graph-mini">
        <RailPanelHeader
          icon={GitBranch}
          title={zhCN.mission.attackGraph}
          meta={`${data.graphNodes.length} ${zhCN.graph.nodeCount} / ${data.graphEdges.length} ${zhCN.graph.edgeCount}`}
          onOpen={onOpenGraph}
        />
        <GraphCanvas compact nodes={data.graphNodes} edges={data.graphEdges} selectedNodeId={inspectedNode?.id ?? ''} onSelectNode={onSelectNode} />
      </section>
      <section className="rail-section agent-graph-mini">
        <RailPanelHeader
          icon={UsersRound}
          title={zhCN.mission.agentGraph}
          meta={`${data.agentState.tasks.length} ${zhCN.mission.agentTaskCount}`}
          onOpen={onOpenAgents}
        />
        <AgentGraphCanvas data={data} onOpen={onOpenAgents} />
      </section>
      <section className="rail-section inspector">
        <PanelTitle icon={Lock} title={zhCN.mission.inspector} meta={inspectedNode ? inspectedNode.subtitle : zhCN.mission.noSelectedGraphNode} />
        <NodeSummary node={inspectedNode} execution={inspectedExecution} />
      </section>
    </aside>
  );
}

function RailPanelHeader({
  icon: Icon,
  title,
  meta,
  onOpen,
}: {
  icon: LucideIcon;
  title: string;
  meta: string;
  onOpen: () => void;
}) {
  return (
    <div className="panel-title rail-panel-title">
      <div><Icon size={14} /><span>{title}</span></div>
      <div className="rail-panel-tools">
        <small>{meta}</small>
        <button type="button" onClick={onOpen} aria-label={`${zhCN.navigation.open} ${title}`} title={`${zhCN.navigation.open} ${title}`}>
          <Maximize2 size={13} />
        </button>
      </div>
    </div>
  );
}

const agentGraphPositions = [
  { x: 50, y: 20 },
  { x: 19, y: 48 },
  { x: 81, y: 48 },
  { x: 31, y: 80 },
  { x: 69, y: 80 },
];

function AgentGraphCanvas({ data, onOpen }: { data: IDEData; onOpen: () => void }) {
  const tasks = data.agentState.tasks.slice().sort((left, right) => right.updatedAt - left.updatedAt).slice(0, agentGraphPositions.length);
  const taskByID = new Map(tasks.map((task, index) => [task.id, { task, index }]));
  const taskByAgentID = new Map(tasks.filter(task => task.agentId).map((task, index) => [task.agentId as string, { task, index }]));
  const taskByRole = new Map(tasks.filter(task => task.role).map((task, index) => [task.role, { task, index }]));
  const orchestrationTaskIDs = new Set(data.orchestratorState.runs.map(run => run.agentTaskId).filter(Boolean));
  const handoffLinks = tasks.flatMap((task, index) => {
    const target = task.handoffTarget?.trim();
    if (!target) {
      return [];
    }
    const linkedTask = taskByID.get(target) ?? taskByAgentID.get(target) ?? taskByRole.get(target);
    if (!linkedTask || linkedTask.index === index) {
      return [];
    }
    return [{ from: index, to: linkedTask.index, id: `${task.id}:${linkedTask.task.id}` }];
  });
  const runCount = data.orchestratorState.runs.length;
  if (tasks.length === 0 && runCount === 0) {
    return <EmptyState text={zhCN.mission.noAgentGraph} />;
  }
  return (
    <div className="agent-graph-canvas">
      <svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">
        {runCount > 0 && tasks.map((task, index) => {
          const position = agentGraphPositions[index];
          if (!orchestrationTaskIDs.has(task.id)) {
            return null;
          }
          return <path className="agent-graph-link orchestration" key={`run:${task.id}`} d={`M50 50 L${position.x} ${position.y}`} />;
        })}
        {handoffLinks.map(link => {
          const from = agentGraphPositions[link.from];
          const to = agentGraphPositions[link.to];
          return <path className="agent-graph-link handoff" key={`handoff:${link.id}`} d={`M${from.x} ${from.y} L${to.x} ${to.y}`} />;
        })}
      </svg>
      {runCount > 0 && (
        <button type="button" className="agent-graph-node orchestrator" style={{ left: '50%', top: '50%' }} onClick={onOpen}>
          <strong>{zhCN.mission.orchestrator}</strong>
          <small>{runCount} {zhCN.mission.orchestratorRunCount}</small>
        </button>
      )}
      {tasks.map((task, index) => {
        const position = agentGraphPositions[index];
        return (
          <button
            key={task.id}
            type="button"
            className={`agent-graph-node ${task.status || ''}`}
          style={{ left: `${position.x}%`, top: `${position.y}%` }}
          onClick={onOpen}
          title={task.title}
          aria-label={`${task.role || task.title}，${localizedStatusLabel(task.status)}`}
          >
            <strong>{task.role || task.title}</strong>
            <small>{localizedStatusLabel(task.status)}</small>
          </button>
        );
      })}
    </div>
  );
}

function GraphWorkbench({
  nodes,
  edges,
  executions,
  findings,
  selectedNodeId,
  exportStatus,
  executionLog,
  executionArtifacts,
  executionArtifactsExecutionId,
  onSelectNode,
  onOpenFindingFile,
  onFocusReplayEvent,
  onInspectExecution,
  onFocusReportFinding,
  onLoadExecutionLogs,
  onLoadExecutionArtifacts,
  onOpenExecutionFile,
  onExportGraph,
}: {
  nodes: GraphNode[];
  edges: GraphEdge[];
  executions: ExecutionStep[];
  findings: ReportFinding[];
  selectedNodeId: string;
  exportStatus: string;
  executionLog: ExecutionLog | null;
  executionArtifacts: ExecutionArtifact[];
  executionArtifactsExecutionId: string;
  onSelectNode: (id: string) => void;
  onOpenFindingFile: (filePath: string) => void;
  onFocusReplayEvent: (eventId: string) => void;
  onInspectExecution: (executionId: string) => void;
  onFocusReportFinding: (findingId: string) => void;
  onLoadExecutionLogs: (executionId: string) => void;
  onLoadExecutionArtifacts: (executionId: string) => void;
  onOpenExecutionFile: (filePath: string) => void;
  onExportGraph: () => void;
}) {
  const selectedNode = nodes.find(node => node.id === selectedNodeId);
  const graphFinding = findings.find(finding => finding.nodeId === selectedNode?.id)
    ?? findings.find(finding => finding.executionId === selectedNode?.executionId)
    ?? findings.find(finding => finding.replayEventId === selectedNode?.replayEventId);
  const graphExecution = executions.find(execution => execution.id === selectedNode?.executionId)
    ?? executions.find(execution => execution.id === graphFinding?.executionId);
  const graphLog = graphExecution && executionLog?.id === graphExecution.id ? executionLog : null;
  const graphArtifacts = graphExecution && executionArtifactsExecutionId === graphExecution.id ? executionArtifacts : [];
  const selectedNodeIndex = selectedNode ? nodes.findIndex(node => node.id === selectedNode.id) : -1;

  function selectRelativeNode(offset: number) {
    if (selectedNodeIndex < 0) {
      return;
    }
    const nextNode = nodes[selectedNodeIndex + offset];
    if (nextNode) {
      onSelectNode(nextNode.id);
    }
  }

  return (
    <section className="graph-workbench">
      <div className="graph-toolbar">
        <strong>{zhCN.graph.toolbarTitle}</strong>
        <div>
          {exportStatus && <span>{exportStatus}</span>}
          {!exportStatus && (
            <span>
              {selectedNode
                ? `${zhCN.graph.selectedNode}: ${selectedNodeIndex + 1}/${nodes.length} · ${selectedNode.label}`
                : zhCN.graph.noNodeSelection}
            </span>
          )}
          <button
            type="button"
            aria-label={zhCN.graph.previousNode}
            title={zhCN.graph.previousNode}
            disabled={selectedNodeIndex <= 0}
            onClick={() => selectRelativeNode(-1)}
          >
            <ChevronLeft size={14} />
          </button>
          <button
            type="button"
            aria-label={zhCN.graph.nextNode}
            title={zhCN.graph.nextNode}
            disabled={selectedNodeIndex < 0 || selectedNodeIndex >= nodes.length - 1}
            onClick={() => selectRelativeNode(1)}
          >
            <ChevronRight size={14} />
          </button>
          <button type="button" onClick={() => onSelectNode(nodes[0]?.id ?? '')} disabled={nodes.length === 0}>{zhCN.graph.defaultView}</button>
          <button type="button" onClick={onExportGraph}>{zhCN.graph.export}</button>
        </div>
      </div>
      <div className="graph-workbench-body">
        <GraphCanvas nodes={nodes} edges={edges} selectedNodeId={selectedNodeId} onSelectNode={onSelectNode} />
        <GraphDetailPanel
          node={selectedNode}
          execution={graphExecution}
          finding={graphFinding}
          log={graphLog}
          artifacts={graphArtifacts}
          onOpenFindingFile={onOpenFindingFile}
          onFocusReplayEvent={onFocusReplayEvent}
          onInspectExecution={onInspectExecution}
          onFocusReportFinding={onFocusReportFinding}
          onLoadExecutionLogs={onLoadExecutionLogs}
          onLoadExecutionArtifacts={onLoadExecutionArtifacts}
          onOpenExecutionFile={onOpenExecutionFile}
        />
      </div>
    </section>
  );
}

function graphPosition(index: number, nodeCount: number, compact: boolean) {
  const columns: number = compact ? 6 : 4;
  const rows = Math.max(1, Math.ceil(nodeCount / columns));
  const column = index % columns;
  const row = Math.floor(index / columns);
  return {
    x: columns === 1 ? 50 : 10 + (column * 80) / (columns - 1),
    y: rows === 1 ? 50 : 8 + (row * 84) / (rows - 1),
  };
}

function GraphCanvas({
  compact = false,
  nodes,
  edges,
  selectedNodeId,
  onSelectNode,
}: {
  compact?: boolean;
  nodes: GraphNode[];
  edges: GraphEdge[];
  selectedNodeId: string;
  onSelectNode: (id: string) => void;
}) {
  const visibleNodes = nodes;
  const nodePositions = new Map(visibleNodes.map((node, index) => [
    node.id,
    graphPosition(index, visibleNodes.length, compact),
  ]));
  return (
    <div className={compact ? 'graph-canvas compact' : 'graph-canvas'}>
      {nodes.length === 0 && <EmptyState text={zhCN.mission.noGraph} />}
      <svg className="graph-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">
        {edges.map(edge => {
          const from = nodePositions.get(edge.from);
          const to = nodePositions.get(edge.to);
          if (!from || !to) {
            return null;
          }
          return <path key={edge.id} d={`M${from.x} ${from.y} L${to.x} ${to.y}`} />;
        })}
      </svg>
      {visibleNodes.map(node => {
        const position = nodePositions.get(node.id) ?? { x: node.x, y: node.y };
        return (
          <button
            key={node.id}
            type="button"
            className={`graph-node ${node.kind} ${node.id === selectedNodeId ? 'selected' : ''}`}
            style={{ left: `${position.x}%`, top: `${position.y}%` }}
            onClick={() => onSelectNode(node.id)}
            title={`${node.label} · ${node.subtitle}`}
            aria-label={`${node.label}，${node.subtitle}`}
          >
            <strong>{node.label}</strong>
            <span>{node.subtitle}</span>
          </button>
        );
      })}
    </div>
  );
}

