function SettingsSectionContent({ section, children }: { section: SettingsSectionID; children: React.ReactNode }) {
  return (
    <div className="settings-grid" data-settings-section={section}>
      {children}
    </div>
  );
}

function emptyPromptHarnessDraft(): PromptHarnessDraft {
  return {
    content: '',
    goal: '',
    expectedResult: '',
    maxTokens: '',
    source: '',
    agentRole: '',
    templateVariables: {},
  };
}

function nextPromptVariableName(variables: PromptVariable[]): string {
  const used = new Set(variables.map(variable => variable.name));
  let index = variables.length + 1;
  while (used.has(`custom.${index}`)) {
    index += 1;
  }
  return `custom.${index}`;
}

function promptVariableNameAt(
  registry: PromptRegistry | null,
  promptID: string,
  versionID: string,
  index: number,
): string {
  return registry?.prompts
    .find(prompt => prompt.id === promptID)
    ?.versions.find(version => version.id === versionID)
    ?.variables[index]?.name ?? '';
}

function promptHarnessTemplateVariables(version: PromptRegistry['prompts'][number]['versions'][number] | undefined, draft: PromptHarnessDraft): Record<string, string> | undefined {
  if (!version || version.variables.length === 0) {
    return undefined;
  }
  const values: Record<string, string> = {};
  for (const variable of version.variables) {
    const name = variable.name.trim();
    if (!name) {
      continue;
    }
    const draftValue = draft.templateVariables[name];
    if (draftValue !== undefined) {
      values[name] = draftValue;
      continue;
    }
    values[name] = variable.default ?? '';
  }
  return Object.keys(values).length > 0 ? values : undefined;
}

function reconcilePromptSelectedVersions(registry: PromptRegistry, current: Record<string, string>): Record<string, string> {
  const next: Record<string, string> = {};
  for (const prompt of registry.prompts) {
    next[prompt.id] = promptVersionExists(prompt, current[prompt.id])
      ? current[prompt.id]
      : prompt.activeVersion || prompt.versions[0]?.id || '';
  }
  return next;
}

function reconcilePromptCompareVersions(
  registry: PromptRegistry,
  current: Record<string, { baseVersionId: string; targetVersionId: string }>,
): Record<string, { baseVersionId: string; targetVersionId: string }> {
  const next: Record<string, { baseVersionId: string; targetVersionId: string }> = {};
  for (const prompt of registry.prompts) {
    const existing = current[prompt.id];
    const fallbackBase = prompt.activeVersion || prompt.versions[0]?.id || '';
    const fallbackTarget = prompt.versions.find(version => version.id !== fallbackBase)?.id || fallbackBase;
    next[prompt.id] = {
      baseVersionId: promptVersionExists(prompt, existing?.baseVersionId) ? existing.baseVersionId : fallbackBase,
      targetVersionId: promptVersionExists(prompt, existing?.targetVersionId) ? existing.targetVersionId : fallbackTarget,
    };
  }
  return next;
}

function reconcilePromptHarnessDrafts(registry: PromptRegistry, current: Record<string, PromptHarnessDraft>): Record<string, PromptHarnessDraft> {
  const next: Record<string, PromptHarnessDraft> = {};
  for (const prompt of registry.prompts) {
    next[prompt.id] = { ...emptyPromptHarnessDraft(), ...current[prompt.id] };
  }
  return next;
}

function resolvePromptFocusTarget(registry: PromptRegistry, focus: SettingsFocus): { promptId: string; versionId: string } {
  const [promptIdFromPrompt, versionIdFromPrompt] = splitPromptReferenceID(focus.promptId ?? '');
  const [promptIdFromVersion, versionIdFromVersion] = splitPromptReferenceID(focus.promptVersionId ?? '');
  const requestedPromptId = promptIdFromPrompt || promptIdFromVersion;
  const requestedVersionId = versionIdFromVersion || versionIdFromPrompt || (focus.promptVersionId ?? '').trim();
  const exactPrompt = requestedPromptId
    ? registry.prompts.find(prompt => prompt.id === requestedPromptId)
    : undefined;
  if (exactPrompt) {
    return {
      promptId: exactPrompt.id,
      versionId: promptVersionExists(exactPrompt, requestedVersionId) ? requestedVersionId : exactPrompt.activeVersion || exactPrompt.versions[0]?.id || '',
    };
  }
  if (requestedVersionId) {
    const promptByVersion = registry.prompts.find(prompt => promptVersionExists(prompt, requestedVersionId));
    if (promptByVersion) {
      return { promptId: promptByVersion.id, versionId: requestedVersionId };
    }
  }
  return { promptId: '', versionId: '' };
}

function selectedPromptVersion(prompt: PromptRegistry['prompts'][number], selectedPromptVersions: Record<string, string>) {
  const selectedVersionID = selectedPromptVersions[prompt.id] || prompt.activeVersion || prompt.versions[0]?.id || '';
  return prompt.versions.find(version => version.id === selectedVersionID) ?? prompt.versions[0];
}

function activePromptVersion(prompt: PromptRegistry['prompts'][number]) {
  return prompt.versions.find(version => version.id === prompt.activeVersion) ?? prompt.versions[0];
}

function promptCompareVersionSelection(
  prompt: PromptRegistry['prompts'][number],
  promptCompareVersions: Record<string, { baseVersionId: string; targetVersionId: string }>,
): { baseVersionId: string; targetVersionId: string } {
  const existing = promptCompareVersions[prompt.id];
  const baseVersionId = promptVersionExists(prompt, existing?.baseVersionId)
    ? existing.baseVersionId
    : prompt.activeVersion || prompt.versions[0]?.id || '';
  const targetVersionId = promptVersionExists(prompt, existing?.targetVersionId)
    ? existing.targetVersionId
    : prompt.versions.find(version => version.id !== baseVersionId)?.id || baseVersionId;
  return { baseVersionId, targetVersionId };
}

function promptVersionExists(prompt: PromptRegistry['prompts'][number], versionID?: string): versionID is string {
  return Boolean(versionID && prompt.versions.some(version => version.id === versionID));
}

type PromptKindCategory = 'workbench' | 'system' | 'role' | 'prompt';

function promptKindGroups(prompts: PromptRegistry['prompts']): Array<{ key: PromptKindCategory; label: string; count: number }> {
  const counts: Record<PromptKindCategory, number> = {
    workbench: 0,
    system: 0,
    role: 0,
    prompt: 0,
  };
  for (const prompt of prompts) {
    counts[promptKindCategory(prompt.kind)] += 1;
  }
  return [
    { key: 'workbench' as const, label: zhCN.settings.promptKindGroups.workbench, count: counts.workbench },
    { key: 'role' as const, label: zhCN.settings.promptKindGroups.role, count: counts.role },
    { key: 'system' as const, label: zhCN.settings.promptKindGroups.system, count: counts.system },
    { key: 'prompt' as const, label: zhCN.settings.promptKindGroups.prompt, count: counts.prompt },
  ].filter(group => group.count > 0);
}

function promptKindFilterOptions(prompts: PromptRegistry['prompts']): Array<{ key: PromptKindFilter; label: string; count: number }> {
  const kindCounts = new Map<string, { label: string; count: number }>();
  for (const prompt of prompts) {
    const normalized = normalizePromptKind(prompt.kind);
    const current = kindCounts.get(normalized);
    kindCounts.set(normalized, {
      label: current?.label || promptKindLabel(prompt.kind),
      count: (current?.count ?? 0) + 1,
    });
  }
  const categoryOptions = promptKindGroups(prompts).map(group => ({
    key: `category:${group.key}` as const,
    label: group.label,
    count: group.count,
  }));
  const kindOptions = [...kindCounts.entries()]
    .sort((left, right) => left[1].label.localeCompare(right[1].label, 'zh-CN'))
    .map(([kind, value]) => ({
      key: `kind:${kind}` as const,
      label: value.label,
      count: value.count,
    }));
  return [
    { key: 'all' as const, label: zhCN.settings.promptKindGroups.all, count: prompts.length },
    ...categoryOptions,
    ...kindOptions,
  ];
}

function filterPromptsByKind(prompts: PromptRegistry['prompts'], filter: PromptKindFilter): PromptRegistry['prompts'] {
  if (filter === 'all') {
    return prompts;
  }
  if (filter.startsWith('category:')) {
    const category = filter.slice('category:'.length) as PromptKindCategory;
    return prompts.filter(prompt => promptKindCategory(prompt.kind) === category);
  }
  if (filter.startsWith('kind:')) {
    const kind = filter.slice('kind:'.length);
    return prompts.filter(prompt => normalizePromptKind(prompt.kind) === kind);
  }
  return prompts;
}

function promptKindCategory(kind: string): PromptKindCategory {
  const normalized = normalizePromptKind(kind);
  if (isWorkbenchPromptKind(normalized)) {
    return 'workbench';
  }
  if (normalized === 'system') {
    return 'system';
  }
  if (isRolePromptKind(normalized)) {
    return 'role';
  }
  return 'prompt';
}

function isRolePromptKind(kind: string): boolean {
  return [
    'agent',
    'planner',
    'operator',
    'tool',
    'reviewer',
    'report',
    'failure',
    'strategy',
    'prompt_engineer',
    'harness',
    'multi_agent',
    'multi_agent_role',
    'agent_role',
  ].includes(normalizePromptKind(kind));
}

function isWorkbenchPromptKind(kind: string): boolean {
  return [
    'action_protocol',
    'reflection',
    'workbench_action_protocol',
    'workbench_reflection',
    'workbench_system',
    'ai.workbench.action_protocol',
    'ai.workbench.reflection',
    'ai.workbench.system',
  ].includes(normalizePromptKind(kind));
}

function promptKindCategoryLabel(kind: string): string {
  const normalized = normalizePromptKind(kind);
  if (isWorkbenchPromptKind(normalized)) {
    return zhCN.settings.promptKindCategories.workbench;
  }
  if (normalized === 'tool') {
    return zhCN.settings.promptKindCategories.toolRole;
  }
  if (isRolePromptKind(normalized)) {
    return zhCN.settings.promptKindCategories.agentRole;
  }
  if (normalized === 'system') {
    return zhCN.settings.promptKindCategories.system;
  }
  return zhCN.settings.promptKindCategories.prompt;
}

function promptBindingSummary(version?: PromptRegistry['prompts'][number]['versions'][number]): string {
  if (!version) {
    return zhCN.settings.unbound;
  }
  const provider = version.providerName?.trim() || zhCN.settings.unboundProvider;
  const model = version.model?.trim() || zhCN.settings.unboundModel;
  return `${provider} / ${model}`;
}

function promptVariableSummary(version?: PromptRegistry['prompts'][number]['versions'][number]): string {
  const count = version?.variables.length ?? 0;
  return `${count} ${zhCN.settings.promptVariableUnit}`;
}

function promptVersionSummary(version: PromptRegistry['prompts'][number]['versions'][number]): string {
  return `${promptBindingSummary(version)} · ${promptVariableSummary(version)}`;
}

async function writeClipboardText(content: string): Promise<void> {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(content);
    return;
  }
  const element = document.createElement('textarea');
  element.value = content;
  element.style.position = 'fixed';
  element.style.left = '-9999px';
  document.body.appendChild(element);
  element.focus();
  element.select();
  try {
    document.execCommand('copy');
  } finally {
    document.body.removeChild(element);
  }
}

function promptKindLabel(kind: string): string {
  const normalized = normalizePromptKind(kind);
  switch (normalized) {
    case 'system':
      return zhCN.settings.promptKinds.system;
    case 'ai.workbench.system':
    case 'workbench_system':
      return zhCN.settings.promptKinds.workbench_system;
    case 'ai.workbench.action_protocol':
    case 'workbench_action_protocol':
    case 'action_protocol':
      return zhCN.settings.promptKinds.action_protocol;
    case 'ai.workbench.reflection':
    case 'workbench_reflection':
    case 'reflection':
      return zhCN.settings.promptKinds.reflection;
    case 'planner':
      return zhCN.settings.promptKinds.planner;
    case 'operator':
      return zhCN.settings.promptKinds.operator;
    case 'tool':
      return zhCN.settings.promptKinds.tool;
    case 'reviewer':
      return zhCN.settings.promptKinds.reviewer;
    case 'report':
      return zhCN.settings.promptKinds.report;
    case 'failure':
      return zhCN.settings.promptKinds.failure;
    case 'strategy':
      return zhCN.settings.promptKinds.strategy;
    case 'prompt_engineer':
      return zhCN.settings.promptKinds.prompt_engineer;
    case 'harness':
      return zhCN.settings.promptKinds.harness;
    case 'agent':
    case 'agent_role':
    case 'multi_agent':
    case 'multi_agent_role':
      return zhCN.settings.promptKinds.multi_agent;
    default:
      return unknownBackendValueLabel(zhCN.settings.promptKinds.unknown, kind);
  }
}

function normalizePromptKind(kind: string): string {
  return kind.trim().toLowerCase().replace(/-/g, '_');
}

function ProviderTestResultPanel({ result }: { result: ProviderTestResult }) {
  const attempts = result.attempts ?? [];
  return (
    <section className="provider-test-result" data-provider-test-result="true">
      <header>
        <strong>{zhCN.settings.providerTestResult}</strong>
        <span>{localizedStatusLabel(result.status)}</span>
      </header>
      <div className="provider-test-grid">
        <span>{zhCN.settings.usage.providerModel}: <strong>{result.provider || zhCN.settings.notConfigured} / {result.model || zhCN.settings.notConfigured}</strong></span>
        {result.latencyMs !== undefined && <span>{zhCN.settings.providerTestLatency}: <strong>{formatMilliseconds(result.latencyMs)}</strong></span>}
        {result.usage?.inputTokens !== undefined && <span>{zhCN.settings.usage.inputTokens}: <strong>{formatNumber(result.usage.inputTokens)}</strong></span>}
        {result.usage?.outputTokens !== undefined && <span>{zhCN.settings.usage.outputTokens}: <strong>{formatNumber(result.usage.outputTokens)}</strong></span>}
        {result.usage?.totalTokens !== undefined && <span>{zhCN.settings.usage.totalTokens}: <strong>{formatNumber(result.usage.totalTokens)}</strong></span>}
        {result.usage?.costUsd !== undefined && <span>{zhCN.settings.usage.estimatedCost}: <strong>{formatCostUSD(result.usage.costUsd) ?? zhCN.settings.usage.costUnavailable}</strong></span>}
      </div>
      {result.content && (
        <pre data-provider-test-content="true">{contentPreview(result.content)}</pre>
      )}
      {attempts.length > 0 && (
        <div className="provider-test-attempts" data-provider-test-attempts="true">
          {attempts.map((attempt, index) => (
            <span key={`${attempt.provider ?? index}-${attempt.model ?? ''}-${attempt.status ?? ''}`}>
              {attempt.provider || zhCN.settings.notConfigured} / {attempt.model || zhCN.settings.notConfigured} · {formatProviderAttemptStatus(attempt.status) || zhCN.settings.notConfigured}
              {attempt.error ? ` · ${attempt.error}` : ''}
            </span>
          ))}
        </div>
      )}
    </section>
  );
}

function ProviderUsagePanel({ usage }: { usage: ProviderUsageState }) {
  const summary = usage.summary;
  const providerList = summary.providers.length > 0 ? summary.providers.join(', ') : zhCN.settings.notConfigured;
  const modelList = summary.models.length > 0 ? summary.models.join(', ') : zhCN.settings.notConfigured;
  const summaryCost = summary.estimatedCostRecordCount > 0
    ? formatCostUSD(summary.estimatedCostUsd) ?? zhCN.settings.usage.costUnavailable
    : zhCN.settings.usage.costUnavailable;

  return (
    <SettingsGroup title={zhCN.settings.groups.providerUsage}>
      <SettingRow label={zhCN.settings.rows.providerUsagePath}><SettingValue>{usage.path || zhCN.settings.notConfigured}</SettingValue></SettingRow>
      <SettingRow label={zhCN.settings.rows.providerUsageProviders}><SettingValue>{providerList}</SettingValue></SettingRow>
      <SettingRow label={zhCN.settings.rows.providerUsageModels}><SettingValue>{modelList}</SettingValue></SettingRow>
      <SettingRow label={zhCN.settings.rows.providerUsageFirstCall}><SettingValue>{formatAIInstant(summary.firstCreatedAt) || zhCN.settings.notConfigured}</SettingValue></SettingRow>
      <SettingRow label={zhCN.settings.rows.providerUsageLastCall}><SettingValue>{formatAIInstant(summary.lastCreatedAt) || zhCN.settings.notConfigured}</SettingValue></SettingRow>
      <div className="provider-usage-metrics" aria-label={zhCN.settings.groups.providerUsage}>
        <div>
          <span>{zhCN.settings.usage.recordCount}</span>
          <strong>{formatNumber(summary.recordCount)}</strong>
        </div>
        <div>
          <span>{zhCN.settings.usage.totalTokens}</span>
          <strong>{formatNumber(summary.totalTokens)}</strong>
        </div>
        <div>
          <span>{zhCN.settings.usage.inputTokens}</span>
          <strong>{formatNumber(summary.inputTokens)}</strong>
        </div>
        <div>
          <span>{zhCN.settings.usage.outputTokens}</span>
          <strong>{formatNumber(summary.outputTokens)}</strong>
        </div>
        <div>
          <span>{zhCN.settings.usage.estimatedCost}</span>
          <strong>{summaryCost}</strong>
        </div>
        <div>
          <span>{zhCN.settings.usage.estimatedCostRecords}</span>
          <strong>{formatNumber(summary.estimatedCostRecordCount)}</strong>
        </div>
      </div>
      {usage.records.length === 0 ? (
        <div className="provider-usage-empty">
          <strong>{zhCN.settings.usage.noRecords}</strong>
          <span>{zhCN.settings.usage.emptyHelp}</span>
        </div>
      ) : (
        <div className="provider-usage-records" aria-label={zhCN.settings.rows.providerUsageRecords}>
          {usage.records.map(record => (
            <ProviderUsageRecordRow key={record.recordId || record.path || `${record.createdAt}-${record.providerName}-${record.model}`} record={record} />
          ))}
        </div>
      )}
    </SettingsGroup>
  );
}

function ProviderUsageRecordRow({ record }: { record: ProviderUsageRecord }) {
  const cost = record.estimatedCostAvailable
    ? formatCostUSD(record.estimatedCostUsd) ?? zhCN.settings.usage.costUnavailable
    : zhCN.settings.usage.costUnavailable;
  const capability = record.capabilities.length > 0 ? formatProviderCapabilities(record.capabilities) : zhCN.settings.notConfigured;
  const budget = record.budgetEnforced
    ? [
        record.budgetStatus,
        formatCostUSD(record.budgetMaxEstimatedCostUsd),
      ].filter(Boolean).join(' / ')
    : '';
  return (
    <article className="provider-usage-record">
      <header>
        <strong>{record.providerName || zhCN.settings.notConfigured} / {record.model || zhCN.settings.notConfigured}</strong>
        <time>{formatAIInstant(record.createdAt) || record.createdAt}</time>
      </header>
      <div className="provider-usage-record-grid">
        <span>{zhCN.settings.usage.totalTokens}: <strong>{formatNumber(record.totalTokens)}</strong></span>
        <span>{zhCN.settings.usage.inputTokens}: <strong>{formatNumber(record.inputTokens)}</strong></span>
        <span>{zhCN.settings.usage.outputTokens}: <strong>{formatNumber(record.outputTokens)}</strong></span>
        <span>{zhCN.settings.usage.estimatedCost}: <strong>{cost}</strong></span>
        {record.contextWindowTokens !== undefined && <span>{zhCN.settings.usage.contextWindow}: <strong>{formatNumber(record.contextWindowTokens)}</strong></span>}
        <span>{zhCN.settings.usage.capability}: <strong>{capability}</strong></span>
        {record.source && <span>{zhCN.settings.usage.source}: <strong>{record.source}</strong></span>}
        {budget && <span>{zhCN.settings.usage.budgetMetadata}: <strong>{budget}</strong></span>}
      </div>
      {(record.recordId || record.path) && (
        <footer>
          {record.recordId && <code>{record.recordId}</code>}
          {record.path && <code>{record.path}</code>}
        </footer>
      )}
    </article>
  );
}

function formatDesktopRuntimeMode(isPackaged?: boolean): string {
  if (isPackaged === true) {
    return zhCN.settings.runtimeModes.packaged;
  }
  if (isPackaged === false) {
    return zhCN.settings.runtimeModes.development;
  }
  return zhCN.settings.notConfigured;
}

function formatDesktopPair(first?: string, second?: string): string {
  const values = [first, second].filter(Boolean);
  return values.length > 0 ? values.join(' / ') : zhCN.settings.notConfigured;
}

function formatDesktopExists(exists?: boolean): string {
  if (exists === true) {
    return zhCN.settings.runtimeModes.exists;
  }
  if (exists === false) {
    return zhCN.settings.runtimeModes.missing;
  }
  return zhCN.settings.notConfigured;
}

function formatDesktopExit(code?: number | null, signal?: string): string {
  if (typeof code === 'number' && code >= 0) {
    return `${zhCN.details.status} ${code}`;
  }
  if (typeof code === 'number' && code < 0) {
    return zhCN.desktop.exitCodeUnknown;
  }
  if (signal) {
    return signal;
  }
  return zhCN.settings.runtimeModes.none;
}

