function ToolchainActionCatalog({
  actions,
  draftsByAction,
  executionsByAction,
  busyActionID,
  status,
  onDraftChange,
  onRunAction,
  onOpenExecution,
}: {
  actions: ToolAction[];
  draftsByAction: ToolActionLaunchDrafts;
  executionsByAction: Record<string, ExecutionStep>;
  busyActionID: string;
  status: string;
  onDraftChange: (action: ToolAction, draft: ToolActionLaunchDraft) => void;
  onRunAction: (action: ToolAction) => void;
  onOpenExecution: (executionID: string) => void;
}) {
  return (
    <section className="settings-toolchain-actions" data-settings-toolchain-actions="true">
      <header>
        <strong>{zhCN.settings.toolchainActions}</strong>
        <span>{status || `${actions.length} ${zhCN.settings.toolchainActionCount}`}</span>
      </header>
      {actions.length === 0 ? (
        <EmptyState text={zhCN.settings.toolchainActionsEmpty} />
      ) : (
        <div className="settings-toolchain-action-list">
          {actions.map(action => {
            const execution = executionsByAction[action.id];
            const running = busyActionID === action.id;
            const draft = toolActionLaunchDraft(action, draftsByAction);
            return (
              <div key={action.id} className="settings-toolchain-action-row" data-settings-toolchain-action-id={action.id}>
                <ToolActionLaunchFields
                  action={action}
                  draft={draft}
                  onDraftChange={nextDraft => onDraftChange(action, nextDraft)}
                  onRun={() => onRunAction(action)}
                />
                <div className="settings-toolchain-action-buttons">
                  <button type="button" onClick={() => onRunAction(action)} disabled={running || toolActionRunDisabled(action, draft)}>
                    <Radar size={14} />
                    {running ? zhCN.settings.toolchainActionRunningShort : zhCN.settings.toolchainRunAction}
                  </button>
                  <button
                    type="button"
                    className="secondary-action"
                    onClick={() => execution && onOpenExecution(execution.id)}
                    disabled={!execution}
                    data-settings-toolchain-execution-id={execution?.id || ''}
                  >
                    <TerminalSquare size={14} />
                    {zhCN.settings.toolchainOpenExecution}
                  </button>
                </div>
                {execution && (
                  <div className="settings-toolchain-action-execution">
                    <span>{zhCN.settings.toolchainLastExecution}</span>
                    <code>{execution.id}</code>
                    <small>{executionStatusLabel(execution.status, execution.rawStatus)}</small>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </section>
  );
}

function toolchainActionsForPack(actions: ToolAction[], pack: ToolchainPackSettings): ToolAction[] {
  const packID = pack.id.trim();
  const manifestPath = pack.manifestPath.trim();
  return actions
    .filter(action => {
      if (!packID && !manifestPath) {
        return true;
      }
      return (packID && action.packId === packID) || (manifestPath && action.manifestPath === manifestPath);
    })
    .sort((left, right) => left.label.localeCompare(right.label, 'zh-CN'));
}

function emptyToolchainPack(): ToolchainPackSettings {
  return {
    id: '',
    name: '',
    version: '',
    status: zhCN.settings.notConfigured,
    toolsReady: 0,
    manifestPath: '',
    manifestYaml: '',
    capabilities: [],
    runner: '',
    runCommand: [],
    runTimeoutMs: 0,
    parser: '',
    healthcheck: '',
    healthCommand: [],
    dependencies: [],
  };
}

function toolchainDraftWithManifestYaml(pack: ToolchainPackSettings, workspacePath: string): ToolchainPackSettings {
  const manifestPath = pack.manifestPath || toolchainManifestPathForPack(workspacePath, pack.id);
  const next = { ...pack, manifestPath };
  return { ...next, manifestYaml: buildToolchainManifestYaml(next) };
}

function toolchainManifestPathForPack(workspacePath: string, packID: string): string {
  const normalizedID = packID.trim().replace(/-pack$/, '');
  if (!workspacePath || !normalizedID) {
    return '';
  }
  return `${workspacePath.replace(/\/+$/, '')}/toolchain/${normalizedID}-pack/manifest.yaml`;
}

function toolchainDependencySummary(pack: ToolchainPackSettings): string {
  if (pack.dependencies.length === 0) {
    return zhCN.settings.notConfigured;
  }
  return pack.dependencies.map(dependency => {
    const optional = dependency.optional ? zhCN.settings.dependencyOptional : zhCN.settings.dependencyRequired;
    return `${dependency.name} / ${toolchainDependencyKindLabel(dependency.kind)} / ${optional}`;
  }).join(', ');
}

function parseToolchainManifestYaml(yaml: string, fallback: ToolchainPackSettings): ToolchainPackSettings {
  const runTimeout = Number(readToolchainYamlScalar(yaml, 'run_timeout_ms') || 0);
  return {
    ...fallback,
    name: readToolchainYamlScalar(yaml, 'name') ?? '',
    version: readToolchainYamlScalar(yaml, 'version') ?? '',
    capabilities: readToolchainYamlList(yaml, 'capabilities'),
    runner: readToolchainYamlScalar(yaml, 'runner') ?? '',
    runCommand: readToolchainYamlList(yaml, 'run_command'),
    runTimeoutMs: Number.isFinite(runTimeout) && runTimeout >= 0 ? runTimeout : 0,
    parser: readToolchainYamlScalar(yaml, 'parser') ?? '',
    healthcheck: readToolchainYamlScalar(yaml, 'healthcheck') ?? '',
    healthCommand: readToolchainYamlList(yaml, 'health_command'),
  };
}

function readToolchainYamlScalar(yaml: string, key: string): string | null {
  const line = yaml.split(/\r?\n/).find(item => item.startsWith(`${key}:`));
  if (!line) {
    return null;
  }
  return decodeYamlScalar(line.slice(line.indexOf(':') + 1).trim());
}

function readToolchainYamlList(yaml: string, key: string): string[] {
  const lines = yaml.split(/\r?\n/);
  const start = lines.findIndex(line => line.startsWith(`${key}:`));
  if (start < 0) {
    return [];
  }
  const firstValue = lines[start].slice(lines[start].indexOf(':') + 1).trim();
  if (firstValue === '[]') {
    return [];
  }
  if (firstValue.startsWith('[') && firstValue.endsWith(']')) {
    return parseInlineYamlList(firstValue);
  }
  const values: string[] = [];
  for (const line of lines.slice(start + 1)) {
    if (/^\S/.test(line)) {
      break;
    }
    const item = line.trim();
    if (!item.startsWith('- ')) {
      continue;
    }
    const value = decodeYamlScalar(item.slice(2).trim());
    if (value) {
      values.push(value);
    }
  }
  return values;
}

function parseInlineYamlList(value: string): string[] {
  const content = value.slice(1, -1).trim();
  if (!content) {
    return [];
  }
  return content.split(',').map(item => decodeYamlScalar(item.trim())).filter(Boolean);
}

function decodeYamlScalar(value: string): string {
  if (value === "''" || value === '""') {
    return '';
  }
  if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
    try {
      return value.startsWith('"')
        ? JSON.parse(value)
        : value.slice(1, -1).replace(/''/g, "'");
    } catch {
      return value.slice(1, -1);
    }
  }
  return value;
}

function emptyProviderDraft(name: string, routingStrategy: string, enabled: boolean): ProviderSettings {
  return {
    name,
    type: '',
    model: '',
    baseUrl: '',
    apiKeyEnv: '',
    apiKeyValue: '',
    apiKeyConfigured: false,
    enabled,
    timeoutMs: 0,
    contextWindowTokens: 0,
    capabilities: [],
    routingStrategy,
    status: zhCN.settings.notConfigured,
  };
}

function providerOptionsForConfig(config: ProviderConfig, fallback: ProviderSettings): ProviderSettings[] {
  if (config.providers.length > 0) {
    return config.providers;
  }
  return fallback.name ? [fallback] : [];
}

function selectedProviderForConfig(config: ProviderConfig, fallback: ProviderSettings): ProviderSettings {
  const providers = providerOptionsForConfig(config, fallback);
  return providers.find(provider => provider.name === config.active.name)
    ?? providers.find(provider => provider.enabled)
    ?? providers[0]
    ?? fallback;
}

function providerDraftWithRouting(provider: ProviderSettings, config: ProviderConfig): ProviderSettings {
  return {
    ...provider,
    routingStrategy: config.routingStrategy || provider.routingStrategy,
  };
}

function splitCommaList(value: string): string[] {
  return value.split(',').map(item => item.trim()).filter(Boolean);
}

