function CommandPalette({
  mode,
  status,
  desktopAvailable,
  recentWorkspaces,
  canRunCommand,
  canStartMission,
  onClose,
  onSelectMode,
  onRefresh,
  onOpenWorkspace,
  onOpenRecentWorkspace,
  onCreateWorkspace,
  onRestartBackend,
  onRunCommand,
  onSaveMission,
  onStartMission,
}: {
  mode: IDEMode;
  status: IDEData['status'];
  desktopAvailable: boolean;
  recentWorkspaces: string[];
  canRunCommand: boolean;
  canStartMission: boolean;
  onClose: () => void;
  onSelectMode: (mode: IDEMode) => void;
  onRefresh: () => void | Promise<void>;
  onOpenWorkspace: () => void | Promise<void>;
  onOpenRecentWorkspace: (path: string) => void | Promise<void>;
  onCreateWorkspace: () => void | Promise<void>;
  onRestartBackend: () => void | Promise<void>;
  onRunCommand: () => void | Promise<void>;
  onSaveMission: () => void | Promise<void>;
  onStartMission: () => void | Promise<void>;
}) {
  const [query, setQuery] = useState('');
  const [activeActionId, setActiveActionId] = useState('');
  const actionButtonRefs = useRef(new Map<string, HTMLButtonElement>());
  const paletteActions = useMemo<CommandPaletteAction[]>(() => [
    {
      id: 'refresh',
      label: zhCN.commandPalette.refresh,
      meta: status.workspace,
      icon: RefreshCw,
      run: onRefresh,
    },
    {
      id: 'open-workspace',
      label: zhCN.commandPalette.openWorkspace,
      meta: zhCN.commandPalette.desktopAction,
      icon: FolderOpen,
      disabled: !desktopAvailable,
      run: onOpenWorkspace,
    },
    ...recentWorkspaces.map(path => ({
      id: `recent-workspace-${path}`,
      label: zhCN.commandPalette.openRecentWorkspace,
      meta: path,
      icon: FolderOpen,
      disabled: !desktopAvailable,
      run: () => onOpenRecentWorkspace(path),
    })),
    {
      id: 'create-workspace',
      label: zhCN.commandPalette.createWorkspace,
      meta: zhCN.commandPalette.desktopAction,
      icon: FolderPlus,
      disabled: !desktopAvailable,
      run: onCreateWorkspace,
    },
    {
      id: 'restart-backend',
      label: zhCN.commandPalette.restartBackend,
      meta: status.backend,
      icon: Activity,
      run: onRestartBackend,
    },
    {
      id: 'run-command',
      label: zhCN.commandPalette.runCommand,
      meta: status.workspace,
      icon: TerminalSquare,
      disabled: !canRunCommand,
      run: onRunCommand,
    },
    {
      id: 'save-mission',
      label: zhCN.commandPalette.saveMission,
      meta: status.workflow,
      icon: Save,
      run: onSaveMission,
    },
    {
      id: 'start-mission',
      label: zhCN.commandPalette.startMission,
      meta: status.workflow,
      icon: Play,
      disabled: !canStartMission,
      run: onStartMission,
    },
    ...modes.map(item => ({
      id: `mode-${item.id}`,
      label: `${zhCN.commandPalette.switchTo}${zhCN.modes[item.id]}`,
      meta: item.id === mode ? zhCN.commandPalette.currentMode : zhCN.commandPalette.modeAction,
      icon: item.icon,
      run: () => onSelectMode(item.id),
    })),
  ], [canRunCommand, canStartMission, desktopAvailable, mode, onCreateWorkspace, onOpenRecentWorkspace, onOpenWorkspace, onRefresh, onRestartBackend, onRunCommand, onSaveMission, onSelectMode, onStartMission, recentWorkspaces, status.backend, status.workflow, status.workspace]);
  const normalizedQuery = query.trim().toLowerCase();
  const visibleActions = normalizedQuery
    ? paletteActions.filter(action => `${action.label} ${action.meta}`.toLowerCase().includes(normalizedQuery))
    : paletteActions;
  const enabledActions = visibleActions.filter(action => !action.disabled);
  const activeAction = enabledActions.find(action => action.id === activeActionId) ?? enabledActions[0];

  useEffect(() => {
    const nextActionId = activeAction?.id ?? '';
    if (nextActionId !== activeActionId) {
      setActiveActionId(nextActionId);
    }
  }, [activeAction?.id, activeActionId]);

  async function executeAction(action: CommandPaletteAction) {
    if (action.disabled) {
      return;
    }
    onClose();
    await action.run();
  }

  function selectAction(action?: CommandPaletteAction) {
    if (!action || action.disabled) {
      return;
    }
    setActiveActionId(action.id);
    window.requestAnimationFrame(() => {
      actionButtonRefs.current.get(action.id)?.scrollIntoView({ block: 'nearest' });
    });
  }

  function moveActiveAction(offset: number) {
    if (enabledActions.length === 0) {
      return;
    }
    const currentIndex = enabledActions.findIndex(action => action.id === activeAction?.id);
    const nextIndex = currentIndex < 0
      ? 0
      : (currentIndex + offset + enabledActions.length) % enabledActions.length;
    selectAction(enabledActions[nextIndex]);
  }

  function handlePaletteKeyDown(event: ReactKeyboardEvent<HTMLInputElement>) {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      moveActiveAction(1);
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      moveActiveAction(-1);
      return;
    }
    if (event.key === 'Home') {
      event.preventDefault();
      selectAction(enabledActions[0]);
      return;
    }
    if (event.key === 'End') {
      event.preventDefault();
      selectAction(enabledActions[enabledActions.length - 1]);
      return;
    }
    if (event.key === 'Enter' && activeAction) {
      event.preventDefault();
      void executeAction(activeAction);
    }
  }

  return (
    <div className="palette-backdrop" role="presentation" onClick={onClose}>
      <div className="command-palette" role="dialog" aria-modal="true" aria-label={zhCN.shell.commandPalette} onClick={event => event.stopPropagation()}>
        <div className="palette-input">
          <Command size={17} />
          <input
            autoFocus
            value={query}
            onChange={event => {
              setQuery(event.target.value);
              setActiveActionId('');
            }}
            onKeyDown={handlePaletteKeyDown}
            placeholder={zhCN.commandPalette.placeholder}
            aria-label={zhCN.shell.commandPalette}
          />
        </div>
        <div
          role="group"
          aria-label={zhCN.commandPalette.results}
          style={{ display: 'grid', gap: 8, maxHeight: 'min(520px, calc(100vh - 190px))', overflowY: 'auto', overscrollBehavior: 'contain' }}
        >
          {visibleActions.map(action => {
            const Icon = action.icon;
            const active = action.id === activeAction?.id;
            return (
              <button
                key={action.id}
                ref={element => {
                  if (element) {
                    actionButtonRefs.current.set(action.id, element);
                  } else {
                    actionButtonRefs.current.delete(action.id);
                  }
                }}
                type="button"
                data-command-action-id={action.id}
                data-command-action-active={active ? 'true' : 'false'}
                aria-current={active ? 'true' : undefined}
                onMouseEnter={() => selectAction(action)}
                onFocus={() => selectAction(action)}
                onClick={() => void executeAction(action)}
                disabled={action.disabled}
              >
                <Icon size={16} />
                <span>{action.label}</span>
                <small>{action.meta}</small>
              </button>
            );
          })}
          {visibleActions.length === 0 && <EmptyState text={zhCN.commandPalette.empty} />}
        </div>
      </div>
    </div>
  );
}

function StatusBar({ data, conversation }: { data: IDEData; conversation: AIConversation | null }) {
  const status = data.status;
  const connection = status.api === 'connected'
    ? `${zhCN.shell.statusConnected} ${formatLatencyValue(status.latency)}`
    : status.api === 'degraded'
      ? `${zhCN.shell.statusDegraded} ${formatLatencyValue(status.latency)}`
      : zhCN.shell.statusOffline;
  const usage = conversation?.usage;
  const model = conversation?.model || data.provider.model || (status.api === 'connected' ? zhCN.ai.providerMissing : zhCN.common.statuses.unavailable);
  const contextWindow = data.provider.contextWindowTokens;
  const totalTokens = usage?.totalTokens;
  const contextPercent = totalTokens !== undefined && contextWindow > 0
    ? Math.min(100, Math.round((totalTokens / contextWindow) * 100))
    : undefined;
  const totalAgents = data.agentState.tasks.length;
  const activeAgents = data.agentState.tasks.filter(task => ['active', 'claimed', 'in_progress', 'running'].includes(task.status)).length;
  const estimatedCost = usage?.costUsd !== undefined ? formatCostUSD(usage.costUsd) : zhCN.ai.runtimeCostUnknown;
  return (
    <footer className="status-bar">
      <span><strong>{zhCN.shell.statusModel}:</strong> {model}</span>
      <span className="status-context">
        <strong>{zhCN.shell.statusContext}:</strong>
        <i aria-hidden="true"><b style={{ width: `${contextPercent ?? 0}%` }} /></i>
        {contextPercent !== undefined && totalTokens !== undefined
          ? `${contextPercent}% (${totalTokens.toLocaleString('zh-CN')} / ${contextWindow.toLocaleString('zh-CN')})`
          : '--'}
      </span>
      <span><strong>{zhCN.shell.statusAgents}:</strong> {activeAgents} {zhCN.shell.statusActive} / {totalAgents} {zhCN.shell.statusTotal}</span>
      <span><strong>{zhCN.shell.statusEstimatedCost}:</strong> {estimatedCost}</span>
      <span className={status.api === 'connected' ? 'connected' : status.api === 'degraded' ? 'degraded' : 'offline'}><CircleDot size={10} /> {connection}</span>
    </footer>
  );
}
